const OPERATIONS_SHIFT_HANDOFF_CREATE_ACTION = 'operations.shift_handoff.create';
const OPERATIONS_SHIFT_HANDOFF_ACKNOWLEDGE_ACTION = 'operations.shift_handoff.acknowledge';
const OPERATIONS_SHIFT_HANDOFF_TARGET_PREFIX = 'operations:shift_handoff:';
const OPERATIONS_HANDOFF_OPEN_CASE_REVISION_KEY = 'open-cases';

function operationsShiftHandoffMetadata(metadata: Prisma.JsonValue | null | undefined) {
  if (!metadata || Array.isArray(metadata) || typeof metadata !== 'object') return null;

  const record = metadata as Prisma.JsonObject;
  const incomingOperator =
    typeof record.incomingOperator === 'string' ? normalizeNullable(record.incomingOperator) : null;
  const incomingOperatorId =
    typeof record.incomingOperatorId === 'string' ? normalizeNullable(record.incomingOperatorId) : null;
  const note = typeof record.note === 'string' ? normalizeNullable(record.note) : null;
  const outgoingShift =
    typeof record.outgoingShift === 'string' ? normalizeNullable(record.outgoingShift) : null;
  const owner =
    typeof record.followUpOwner === 'string'
      ? normalizeNullable(record.followUpOwner)
      : typeof record.owner === 'string'
        ? normalizeNullable(record.owner)
        : null;
  const ownerId =
    typeof record.followUpOwnerId === 'string'
      ? normalizeNullable(record.followUpOwnerId)
      : typeof record.ownerId === 'string'
        ? normalizeNullable(record.ownerId)
        : null;
  const unresolvedCaseIds = Array.isArray(record.unresolvedCaseIds)
    ? record.unresolvedCaseIds
        .filter((value): value is string => typeof value === 'string')
        .map((value) => normalizeNullable(value))
        .filter((value): value is string => Boolean(value))
    : [];
  const unresolvedCases = Array.isArray(record.unresolvedCases)
    ? record.unresolvedCases.flatMap((value) => {
        if (!value || Array.isArray(value) || typeof value !== 'object') return [];
        const item = value as Prisma.JsonObject;
        const caseId = typeof item.caseId === 'string' ? normalizeNullable(item.caseId) : null;
        const queueKey = typeof item.queueKey === 'string' ? normalizeNullable(item.queueKey) : null;
        return caseId && queueKey ? [{ caseId, queueKey }] : [];
      })
    : unresolvedCaseIds.map((caseId) => ({ caseId, queueKey: 'legacy' }));

  if (!incomingOperator || !outgoingShift || !owner || (unresolvedCaseIds.length > 0 && !note)) {
    return null;
  }

  return {
    followUpOwner: owner,
    followUpOwnerId: ownerId,
    incomingOperator,
    incomingOperatorId,
    note: note ?? '',
    outgoingShift,
    owner,
    ownerId,
    unresolvedCases,
    unresolvedCaseIds,
  };
}

type OperationsShiftHandoffListOptions = {
  readonly actorId?: string | null;
  readonly operator?: string | null;
  readonly page?: number | string | null;
  readonly pageSize?: number | string | null;
  readonly q?: string | null;
  readonly range?: string | null;
  readonly relationship?: string | null;
  readonly scope?: string | null;
  readonly status?: string | null;
};

function operationsShiftHandoffSql(
  options: OperationsShiftHandoffListOptions,
  status: 'acknowledged' | 'all' | 'open',
) {
  const conditions: Prisma.Sql[] = [
    Prisma.sql`handoff."action" = ${OPERATIONS_SHIFT_HANDOFF_CREATE_ACTION}`,
    Prisma.sql`jsonb_typeof(handoff."metadata") = 'object'`,
    Prisma.sql`NULLIF(BTRIM(handoff."metadata"->>'incomingOperator'), '') IS NOT NULL`,
    Prisma.sql`NULLIF(BTRIM(handoff."metadata"->>'outgoingShift'), '') IS NOT NULL`,
    Prisma.sql`COALESCE(
      NULLIF(BTRIM(handoff."metadata"->>'followUpOwner'), ''),
      NULLIF(BTRIM(handoff."metadata"->>'owner'), '')
    ) IS NOT NULL`,
    Prisma.sql`(
      COALESCE(jsonb_typeof(handoff."metadata"->'unresolvedCaseIds'), 'missing') <> 'array'
      OR jsonb_array_length(handoff."metadata"->'unresolvedCaseIds') = 0
      OR NULLIF(BTRIM(handoff."metadata"->>'note'), '') IS NOT NULL
    )`,
  ];
  const actorId = normalizeNullable(options.actorId);
  const relationship = normalizeNullable(options.relationship);
  if (options.scope === 'current' && actorId) {
    if (relationship === 'assigned') {
      conditions.push(Prisma.sql`handoff."metadata"->>'incomingOperatorId' = ${actorId}`);
    } else if (relationship === 'waiting') {
      conditions.push(
        Prisma.sql`handoff."actorId" = ${actorId}`,
        Prisma.sql`COALESCE(handoff."metadata"->>'incomingOperatorId', '') <> ${actorId}`,
      );
    } else {
      conditions.push(
        Prisma.sql`(
          handoff."actorId" = ${actorId}
          OR handoff."metadata"->>'incomingOperatorId' = ${actorId}
        )`,
      );
    }
  }
  const rangeStart = options.scope === 'current' ? null : operationsHandoffRangeStart(options.range);
  if (rangeStart) conditions.push(Prisma.sql`handoff."createdAt" >= ${rangeStart}`);

  const operator = normalizeNullable(options.operator);
  if (operator) {
    const search = `%${operator}%`;
    conditions.push(Prisma.sql`(
      handoff."actorId" ILIKE ${search}
      OR COALESCE(actor."fullName", '') ILIKE ${search}
      OR COALESCE(actor."email", '') ILIKE ${search}
      OR COALESCE(actor."phone", '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'incomingOperatorId', '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'incomingOperator', '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'followUpOwnerId', handoff."metadata"->>'ownerId', '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'followUpOwner', handoff."metadata"->>'owner', '') ILIKE ${search}
    )`);
  }
  const q = normalizeNullable(options.q);
  if (q) {
    const search = `%${q}%`;
    conditions.push(Prisma.sql`(
      handoff.id ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'outgoingShift', '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'note', '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'incomingOperator', '') ILIKE ${search}
      OR COALESCE(handoff."metadata"->>'followUpOwner', handoff."metadata"->>'owner', '') ILIKE ${search}
      OR handoff."metadata"::text ILIKE ${search}
    )`);
  }

  const acknowledgement = Prisma.sql`EXISTS (
    SELECT 1
    FROM "AdminAuditLog" acknowledgement
    WHERE acknowledgement."action" = ${OPERATIONS_SHIFT_HANDOFF_ACKNOWLEDGE_ACTION}
      AND acknowledgement."target" = ${OPERATIONS_SHIFT_HANDOFF_TARGET_PREFIX} || handoff.id
  )`;
  if (status === 'open') conditions.push(Prisma.sql`NOT ${acknowledgement}`);
  if (status === 'acknowledged') conditions.push(acknowledgement);

  return Prisma.sql`
    FROM "AdminAuditLog" handoff
    INNER JOIN "User" actor ON actor.id = handoff."actorId"
    WHERE ${Prisma.join(conditions, ' AND ')}
  `;
}

