  async customerReferralParentSummary(options: AdminReferralParentListQuery = {}) {
    const queueOptions = { ...options, reward: null };
    const [totalCount, referralCount, rewardGroups, attentionSummary] = await Promise.all([
      this.prisma.customerProfile.count({
        where: adminCustomerReferralParentWhere(options),
      }),
      this.prisma.referralAttribution.count({
        where: adminCustomerReferralAttributionWhere(options, { includeReward: true }),
      }),
      this.prisma.referralReward.groupBy({
        by: ['status'],
        where: { attribution: adminCustomerReferralAttributionWhere(queueOptions, { includeReward: false }) },
        _count: { _all: true },
        _sum: { amount: true },
      }),
      this.prisma.referralReward.aggregate({
        where: adminCustomerReferralRewardQueueWhere({ ...options, reward: 'attention' }),
        _count: { _all: true },
        _sum: { amount: true },
      }),
    ]);

    return {
      referralCount,
      totalCount,
      rewardQueueSummaries: adminReferralRewardQueueSummaries(rewardGroups, {
        amount: attentionSummary._sum.amount ?? 0,
        count: attentionSummary._count._all,
      }),
    };
  }

  private async customerReferralParentTotals(parentIds: readonly string[]) {
    if (parentIds.length === 0) {
      return new Map<string, ReturnType<typeof adminReferralRewardTotalsFromGroups>>();
    }

    const attributions = await this.prisma.referralAttribution.findMany({
      where: {
        audience: ReferralAudience.CUSTOMER,
        referrerCustomerProfileId: { in: [...parentIds] },
        NOT: referralAdminFixtureAttributionWhere,
      },
      select: { id: true, referrerCustomerProfileId: true },
    });
    const attributionIds = attributions.map((attribution) => attribution.id);
    const rewardGroups =
      attributionIds.length > 0
        ? await this.prisma.referralReward.groupBy({
            by: ['attributionId', 'status'],
            where: { attributionId: { in: attributionIds }, NOT: referralAdminFixtureRewardWhere },
            _count: { _all: true },
            _sum: { amount: true },
          })
        : [];

    return adminCustomerReferralParentTotalsByOwner(attributions, rewardGroups);
  }

