function adminCustomerReferralParentWhere(
  options: AdminReferralParentListQuery,
): Prisma.CustomerProfileWhereInput {
  const filters: Prisma.CustomerProfileWhereInput[] = [
    {
      referralsMade: {
        some: { audience: ReferralAudience.CUSTOMER, NOT: referralAdminFixtureAttributionWhere },
      },
    },
  ];
  const q = normalizeNullable(options.q);
  const attributionStatuses = adminReferralAttributionStatusFilter(options.status);
  const fraudReviewStatuses = adminReferralFraudReviewStatusFilter(options.fraud);
  const createdAt = adminReferralCreatedAtFilter(options.range);
  const rewardStatuses = adminReferralRewardStatusFilter(options.reward);

  if (q) {
    filters.push({ OR: adminCustomerReferralParentSearchFilters(q) });
  }
  if (attributionStatuses || fraudReviewStatuses || createdAt || rewardStatuses) {
    filters.push({
      referralsMade: {
        some: {
          audience: ReferralAudience.CUSTOMER,
          NOT: referralAdminFixtureAttributionWhere,
          ...(attributionStatuses ? { status: { in: attributionStatuses } } : {}),
          ...(fraudReviewStatuses ? { fraudReviewStatus: { in: fraudReviewStatuses } } : {}),
          ...(createdAt ? { createdAt } : {}),
          ...(rewardStatuses ? { rewards: { some: { status: { in: rewardStatuses } } } } : {}),
        },
      },
    });
  }

  return { AND: filters };
}

function adminCustomerReferralRewardQueueWhere(
  options: AdminReferralParentListQuery,
): Prisma.ReferralRewardWhereInput {
  const filters: Prisma.ReferralRewardWhereInput[] = [
    { attribution: { audience: ReferralAudience.CUSTOMER } },
    { NOT: referralAdminFixtureRewardWhere },
  ];
  const q = normalizeNullable(options.q);
  const attributionStatuses = adminReferralAttributionStatusFilter(options.status);
  const fraudReviewStatuses = adminReferralFraudReviewStatusFilter(options.fraud);
  const createdAt = adminReferralCreatedAtFilter(options.range);
  const reward = normalizeNullable(options.reward) ?? 'attention';

  if (q) {
    filters.push({ OR: adminReferralCashoutSearchFilters(q) });
  }
  if (attributionStatuses || fraudReviewStatuses || createdAt) {
    filters.push({
      attribution: {
        ...(attributionStatuses ? { status: { in: attributionStatuses } } : {}),
        ...(fraudReviewStatuses ? { fraudReviewStatus: { in: fraudReviewStatuses } } : {}),
        ...(createdAt ? { createdAt } : {}),
      },
    });
  }
  if (reward === 'attention') {
    filters.push({
      OR: [
        { status: ReferralRewardStatus.HELD },
        { status: ReferralRewardStatus.AVAILABLE },
        { status: ReferralRewardStatus.PENDING, availableAt: { lte: new Date() } },
      ],
    });
  } else {
    const statuses = adminReferralRewardStatusFilter(reward);
    if (statuses) {
      filters.push({ status: { in: statuses } });
    }
  }

  return { AND: filters };
}

