function adminReferralAttributionStatusFilter(
  value: string | null | undefined,
): ReferralAttributionStatus[] | null {
  const normalized = normalizeNullable(value);
  if (normalized === 'qualified') {
    return [ReferralAttributionStatus.QUALIFIED, ReferralAttributionStatus.REWARDED];
  }
  if (normalized === 'blocked') {
    return [ReferralAttributionStatus.BLOCKED, ReferralAttributionStatus.CANCELLED];
  }
  if (normalized === 'pending') {
    return [ReferralAttributionStatus.REGISTERED];
  }
  return null;
}

function adminReferralRewardStatusFilter(value: string | null | undefined): ReferralRewardStatus[] | null {
  const normalized = normalizeNullable(value);
  if (normalized === 'attention') {
    return [ReferralRewardStatus.AVAILABLE, ReferralRewardStatus.PENDING, ReferralRewardStatus.HELD];
  }
  if (normalized === 'available') return [ReferralRewardStatus.AVAILABLE];
  if (normalized === 'credited') return creditedReferralRewardStatuses();
  if (normalized === 'pending') return [ReferralRewardStatus.PENDING];
  if (normalized === 'held') return [ReferralRewardStatus.HELD];
  return null;
}

function adminReferralFraudReviewStatusFilter(
  value: string | null | undefined,
): ReferralFraudReviewStatus[] | null {
  const normalized = normalizeNullable(value);
  if (normalized === 'clear') return [ReferralFraudReviewStatus.CLEAR];
  if (normalized === 'flagged') return [ReferralFraudReviewStatus.FLAGGED];
  if (normalized === 'held') return [ReferralFraudReviewStatus.HELD];
  return null;
}

function adminReferralCreatedAtFilter(value: string | null | undefined): Prisma.DateTimeFilter | null {
  const normalized = normalizeNullable(value);
  if (normalized !== 'today' && normalized !== '7d' && normalized !== '30d') {
    return null;
  }

  const now = new Date();
  const vietnamOffsetMs = 7 * 60 * 60 * 1000;
  const vietnamNow = new Date(now.getTime() + vietnamOffsetMs);
  const todayStart = new Date(
    Date.UTC(vietnamNow.getUTCFullYear(), vietnamNow.getUTCMonth(), vietnamNow.getUTCDate()) -
      vietnamOffsetMs,
  );
  const startAt = new Date(todayStart);
  if (normalized === '7d') startAt.setUTCDate(startAt.getUTCDate() - 6);
  if (normalized === '30d') startAt.setUTCDate(startAt.getUTCDate() - 29);

  return { gte: startAt, lt: new Date(todayStart.getTime() + 24 * 60 * 60 * 1000) };
}

function adminInsensitiveContains(value: string): Prisma.StringFilter {
  return { contains: value, mode: 'insensitive' };
}

function adminAppSessionListWhere(
  options: AdminAppSessionListQuery,
): Prisma.AppSessionWhereInput | undefined {
  const filters: Prisma.AppSessionWhereInput[] = [];
  const role = normalizeAdminAppSessionRole(options.role);
  const platform = normalizeNullable(options.platform)?.toUpperCase();
  const stateWhere = adminAppSessionStateWhere(options.state);
  const q = normalizeNullable(options.q);

  if (role) {
    filters.push({ role });
  }
  if (platform) {
    filters.push({ platform: { equals: platform, mode: 'insensitive' } });
  }
  if (stateWhere) {
    filters.push(stateWhere);
  }
  if (q) {
    filters.push({
      OR: [
        { user: { phone: { contains: q, mode: 'insensitive' } } },
        { user: { fullName: { contains: q, mode: 'insensitive' } } },
        { deviceId: { contains: q, mode: 'insensitive' } },
        { ipAddress: { contains: q, mode: 'insensitive' } },
      ],
    });
  }

  return filters.length > 0 ? { AND: filters } : undefined;
}

function withAdminAppSessionWhere(
  baseWhere: Prisma.AppSessionWhereInput | undefined,
  ...nextWhere: Prisma.AppSessionWhereInput[]
): Prisma.AppSessionWhereInput {
  const filters = [baseWhere, ...nextWhere].filter(
    (filter): filter is Prisma.AppSessionWhereInput => filter !== undefined && Object.keys(filter).length > 0,
  );

  if (filters.length === 0) {
    return {};
  }
  if (filters.length === 1) {
    return filters[0];
  }

  return { AND: filters };
}

function normalizeAdminAppSessionRole(value: string | null | undefined): Role | undefined {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (normalized === 'PARTNER' || normalized === Role.PROVIDER) {
    return Role.PROVIDER;
  }
  if (normalized === Role.CUSTOMER) {
    return Role.CUSTOMER;
  }
  return undefined;
}

function adminAppSessionStateWhere(
  value: string | null | undefined,
): Prisma.AppSessionWhereInput | undefined {
  const state = normalizeNullable(value)?.toLowerCase();
  const now = new Date();
  const liveBoundary = new Date(now.getTime() - ADMIN_APP_SESSION_LIVE_WINDOW_MS);
  const recentBoundary = new Date(now.getTime() - ADMIN_APP_SESSION_RECENT_WINDOW_MS);
  const staleBoundary = new Date(now.getTime() - ADMIN_APP_SESSION_STALE_WINDOW_MS);
  const activeExpiryWhere = { active: true, expiresAt: { gte: now } };

  switch (state) {
    case 'live':
      return { OR: [activeExpiryWhere, { lastSeenAt: { gte: liveBoundary } }] };
    case 'recent':
      return {
        AND: [{ lastSeenAt: { gte: recentBoundary, lt: liveBoundary } }, { NOT: activeExpiryWhere }],
      };
    case 'stale':
      return {
        AND: [{ lastSeenAt: { gte: staleBoundary, lt: recentBoundary } }, { NOT: activeExpiryWhere }],
      };
    case 'expired':
      return { AND: [{ lastSeenAt: { lt: staleBoundary } }, { NOT: activeExpiryWhere }] };
    default:
      return undefined;
  }
}

function adminChatArchiveListTake(value: number | string | null | undefined): number {
  return boundedAdminListLimit(value, ADMIN_CHAT_ARCHIVE_LIST_LIMIT);
}

function adminChatArchiveListSkip(value: number | string | null | undefined): number {
  return boundedAdminListSkip(value);
}

function adminChatArchiveMessageWhere(query: AdminChatArchiveListQuery): Prisma.ChatMessageWhereInput {
  return {
    AND: [
      adminChatArchiveMessagePredicate(query),
      { chatRoom: { is: { booking: adminChatArchiveBookingWhere(query.status) } } },
    ],
  };
}

function adminChatArchiveMessagePredicate(query: AdminChatArchiveListQuery): Prisma.ChatMessageWhereInput {
  return {
    AND: [
      adminChatArchiveMessageDateWhere(query),
      adminChatArchiveSenderWhere(query.sender),
      adminChatArchiveSearchWhere(query.q),
    ].filter((filter): filter is Prisma.ChatMessageWhereInput => Boolean(filter)),
  };
}

function adminChatArchiveBookingWhere(status: string | null | undefined): Prisma.BookingWhereInput {
  const filters: Prisma.BookingWhereInput[] = [adminBookingProductionDataWhere()];
  switch (normalizeNullable(status)?.toLowerCase()) {
    case 'active':
      filters.push(adminBookingListStatusGroupWhere('realtime') ?? {});
      break;
    case 'completed':
      filters.push({ status: BookingStatus.COMPLETED });
      break;
    case 'closed':
      filters.push({
        status: {
          in: [BookingStatus.CANCELLED, BookingStatus.EXPIRED, BookingStatus.REFUNDED, BookingStatus.NO_SHOW],
        },
      });
      break;
  }
  return filters.length === 1 ? filters[0] : { AND: filters };
}

function adminChatArchiveSenderWhere(
  sender: string | null | undefined,
): Prisma.ChatMessageWhereInput | undefined {
  const role = adminChatArchiveSenderRole(sender);
  return role ? { sender: { roles: { has: role } } } : undefined;
}

function adminChatArchiveSenderRole(sender: string | null | undefined): Role | undefined {
  switch (normalizeNullable(sender)?.toLowerCase()) {
    case 'customer':
      return Role.CUSTOMER;
    case 'partner':
      return Role.PROVIDER;
    case 'admin':
      return Role.ADMIN;
    default:
      return undefined;
  }
}

function adminChatArchiveSearchWhere(q: string | null | undefined): Prisma.ChatMessageWhereInput | undefined {
  const query = adminChatArchiveQuery(q);
  if (!query) {
    return undefined;
  }

  const textFilter = { contains: query, mode: Prisma.QueryMode.insensitive };
  const userSearch = { fullName: textFilter };
  const providerSearch = {
    OR: [{ id: textFilter }, { displayName: textFilter }, { user: { is: userSearch } }],
  };

  return {
    OR: [
      { id: textFilter },
      { body: textFilter },
      {
        chatRoom: {
          is: {
            OR: [
              { id: textFilter },
              {
                booking: {
                  is: {
                    OR: [
                      { id: textFilter },
                      { customerProfileId: textFilter },
                      { preferredProviderId: textFilter },
                      { selectedProviderId: textFilter },
                      { customerProfile: { is: { id: textFilter } } },
                      { customerProfile: { is: { user: { is: userSearch } } } },
                      { preferredProvider: { is: providerSearch } },
                      { selectedProvider: { is: providerSearch } },
                      { services: { some: { service: { is: { name: textFilter } } } } },
                    ],
                  },
                },
              },
            ],
          },
        },
      },
    ],
  };
}

function adminChatArchiveMessageDateWhere(
  query: AdminChatArchiveListQuery,
): Prisma.ChatMessageWhereInput | undefined {
  const dateRange = normalizeNullable(query.dateRange)?.toLowerCase() ?? 'all';
  if (!['all', 'today', '7d', '30d', 'custom'].includes(dateRange)) {
    throw new BadRequestException('Unsupported chat archive date range');
  }
  const bounds = adminBookingListDateBounds({
    dateFrom: query.dateFrom,
    dateRange,
    dateTo: query.dateTo,
  });
  return bounds
    ? {
        createdAt: {
          gte: new Date(bounds.startMs),
          lte: new Date(bounds.endMs),
        },
      }
    : undefined;
}

function adminChatArchiveSortDirection(value: string | null | undefined): Prisma.SortOrder {
  return normalizeNullable(value)?.toLowerCase() === 'oldest' ? 'asc' : 'desc';
}

function adminChatArchiveAuditFilters(query: AdminChatArchiveListQuery) {
  const dateRange = normalizeNullable(query.dateRange)?.toLowerCase() ?? 'all';
  return {
    dateFrom: dateRange === 'custom' ? normalizeNullable(query.dateFrom) : null,
    dateRange,
    dateTo: dateRange === 'custom' ? normalizeNullable(query.dateTo) : null,
    q: adminChatArchiveQuery(query.q),
    sender: normalizeNullable(query.sender)?.toLowerCase() ?? null,
    skip: adminChatArchiveListSkip(query.skip),
    sort: adminChatArchiveSortDirection(query.sort) === 'asc' ? 'oldest' : 'newest',
    status: normalizeNullable(query.status)?.toLowerCase() ?? null,
    take: adminChatArchiveListTake(query.take),
  };
}

function adminChatArchiveQuery(value: string | null | undefined) {
  return normalizeNullable(value)?.slice(0, ADMIN_CHAT_ARCHIVE_QUERY_MAX_LENGTH) ?? null;
}

type AdminAuditGroupCount = {
  schemaVersion: number;
  action: string;
  actorId: string | null;
  actorType: string | null;
  area: string;
  outcome: string;
  severity: string;
  source: string | null;
  _count: { _all: number };
};

type AdminAuditWorkspaceFacetCounts = {
  actorTypeCounts: Record<string, number>;
  areaCounts: Record<string, number>;
  outcomeCounts: Record<string, number>;
  severityCounts: Record<string, number>;
};

function adminAuditWorkspaceWhere(
  options: AdminAuditLogListOptions,
  generatedAt: Date,
  view: AdminAuditSavedView | null,
): Prisma.AdminAuditLogWhereInput {
  const filters: Prisma.AdminAuditLogWhereInput[] = [
    view ? adminAuditSavedViewWhere(view) : adminAuditDefaultWhere(null),
  ];
  const actions = (Array.isArray(options.action) ? options.action : [options.action])
    .map((action) => normalizeNullable(action))
    .filter((action): action is string => Boolean(action));
  const reportWindow = adminAuditReportWindow(options, generatedAt);
  const q = normalizeNullable(options.q);
  const targetPrefix = adminAuditLogTargetPrefix(options.targetPrefix);
  const area = adminAuditAreaFilter(options.area);
  const outcome = adminAuditOutcomeFilter(options.outcome);
  const severity = adminAuditSeverityFilter(options.severity);
  const actorType = adminAuditActorTypeFilter(options.actorType);
  const objectType = normalizeNullable(options.objectType);
  const eventId = normalizeNullable(options.eventId);
  const correlationId = normalizeNullable(options.correlationId);
  const requestId = normalizeNullable(options.requestId);

  if (actions.length === 1) filters.push({ action: actions[0] });
  if (actions.length > 1) filters.push({ action: { in: actions } });
  if (reportWindow.from || reportWindow.to) {
    filters.push(adminAuditTimelineWhere(reportWindow.from, reportWindow.to));
  }
  if (targetPrefix) {
    filters.push({
      action: { in: adminAuditLogTargetActions(targetPrefix) },
      target: { startsWith: targetPrefix },
    });
  }
  if (q) {
    filters.push({
      OR: [
        { action: { contains: q, mode: 'insensitive' } },
        { target: { contains: q, mode: 'insensitive' } },
        { eventId: { contains: q, mode: 'insensitive' } },
        { objectId: { contains: q, mode: 'insensitive' } },
        { objectLabelSnapshot: { contains: q, mode: 'insensitive' } },
        { actorKey: { contains: q, mode: 'insensitive' } },
        { actorLabelSnapshot: { contains: q, mode: 'insensitive' } },
        { correlationId: { contains: q, mode: 'insensitive' } },
        { requestId: { contains: q, mode: 'insensitive' } },
        { actor: { id: { contains: q, mode: 'insensitive' } } },
        { actor: { email: { contains: q, mode: 'insensitive' } } },
        { actor: { fullName: { contains: q, mode: 'insensitive' } } },
        { actor: { phone: { contains: q, mode: 'insensitive' } } },
      ],
    });
  }
  if (area) filters.push(adminAuditAreaWhere(area));
  if (outcome) filters.push(adminAuditOutcomeWhere(outcome));
  if (severity) filters.push(adminAuditSeverityWhere(severity));
  if (actorType) filters.push(adminAuditActorTypeWhere(actorType));
  if (objectType) filters.push({ OR: [{ objectType }, { target: { startsWith: `${objectType}:` } }] });
  if (eventId) filters.push({ OR: [{ id: eventId }, { eventId }] });
  if (correlationId) {
    filters.push({
      OR: [{ correlationId }, { metadata: { path: ['correlationId'], equals: correlationId } }],
    });
  }
  if (requestId) {
    filters.push({ OR: [{ requestId }, { metadata: { path: ['requestId'], equals: requestId } }] });
  }
  const bucketWhere = adminAuditLogBucketWhere(normalizeNullable(options.bucket));
  const priorityWhere = adminAuditLogPriorityWhere(normalizeNullable(options.priority));
  if (bucketWhere) filters.push(bucketWhere);
  if (priorityWhere) filters.push(priorityWhere);

  return filters.length === 1 ? filters[0] : { AND: filters };
}

function adminAuditWorkspaceSourceWhere(
  options: AdminAuditLogListOptions,
  generatedAt: Date,
): Prisma.AdminAuditLogWhereInput {
  const filters: Prisma.AdminAuditLogWhereInput[] = [adminAuditDefaultWhere(null)];
  const reportWindow = adminAuditReportWindow(options, generatedAt);
  if (reportWindow.from || reportWindow.to) {
    filters.push(adminAuditTimelineWhere(reportWindow.from, reportWindow.to));
  }
  const bucketWhere = adminAuditLogBucketWhere(normalizeNullable(options.bucket));
  if (bucketWhere) filters.push(bucketWhere);
  return filters.length === 1 ? filters[0] : { AND: filters };
}

async function adminAuditActionableIncidentRows(
  tx: Prisma.TransactionClient,
  options: AdminAuditLogListOptions,
): Promise<AdminAuditRegistryRow[]> {
  const bucket = normalizeNullable(options.bucket);
  if (adminAuditLogBucketWhere(bucket) && bucket !== 'System') return [];

  return tx.$queryRaw<AdminAuditRegistryRow[]>(Prisma.sql`
    WITH latest_times AS MATERIALIZED (
      SELECT log.target, MAX(log."timelineAt") AS "timelineAt"
      FROM "AdminAuditLog" log
      WHERE log.action IN (
        'admin.background_jobs.recurring_incident_opened',
        'admin.background_jobs.recurring_incident_recovered'
      )
      GROUP BY log.target
    ), latest_ids AS MATERIALIZED (
      SELECT latest.target, latest."timelineAt", MAX(log.id) AS id
      FROM latest_times latest
      JOIN "AdminAuditLog" log
        ON log.target = latest.target
        AND log."timelineAt" = latest."timelineAt"
      WHERE log.action IN (
        'admin.background_jobs.recurring_incident_opened',
        'admin.background_jobs.recurring_incident_recovered'
      )
      GROUP BY latest.target, latest."timelineAt"
    ), open_incidents AS (
      SELECT latest.id, latest."timelineAt"
      FROM latest_ids latest
      JOIN "AdminAuditLog" state ON state.id = latest.id
      WHERE state.action = 'admin.background_jobs.recurring_incident_opened'
      ORDER BY latest."timelineAt" DESC, latest.id DESC
      LIMIT 10
    )
    SELECT log.*
    FROM open_incidents incident
    JOIN "AdminAuditLog" log ON log.id = incident.id
    ORDER BY incident."timelineAt" DESC, incident.id DESC
  `);
}

function adminAuditActionableIncidents(rows: readonly AdminAuditRegistryRow[]) {
  const latestByTarget = new Map<string, (typeof rows)[number]>();
  for (const row of rows) {
    if (!latestByTarget.has(row.target)) latestByTarget.set(row.target, row);
  }
  return [...latestByTarget.values()]
    .filter((row) => row.action === 'admin.background_jobs.recurring_incident_opened')
    .slice(0, 10)
    .map((row) => {
      const event = adminAuditEventReadModel(row, { includePayload: false });
      return {
        id: row.id,
        href: `/background-jobs/incidents/${encodeURIComponent(row.id)}`,
        label: event.object.labelSnapshot,
        openedAt: event.occurredAt,
        source: event.context.source,
        target: row.target,
      };
    });
}

function adminAuditReportWindow(options: AdminAuditLogListOptions, now: Date) {
  const explicitFrom = adminAuditLogDateBoundary(options.from, 'from');
  const explicitTo = adminAuditLogDateBoundary(options.to, 'to');
  if (explicitFrom || explicitTo) {
    if (explicitFrom && explicitTo && explicitFrom.getTime() >= explicitTo.getTime()) {
      throw new BadRequestException('Audit log date range is invalid');
    }
    return {
      range: 'custom',
      label: 'Custom range',
      from: explicitFrom?.toISOString() ?? null,
      to: explicitTo?.toISOString() ?? null,
    };
  }

  const window = adminVietnamOverviewRangeWindow(
    normalizeAdminVietnamOverviewRange(options.range ?? 'today'),
    now,
  );
  const dateWhere = adminVietnamOverviewDateWhere(window);
  return {
    range: window.range,
    label: `${window.label} (Vietnam)`,
    from: dateWhere?.gte.toISOString() ?? null,
    to: dateWhere?.lt.toISOString() ?? null,
  };
}

function adminAuditTimelineWhere(from: string | null, to: string | null): Prisma.AdminAuditLogWhereInput {
  return {
    timelineAt: {
      ...(from ? { gte: new Date(from) } : {}),
      ...(to ? { lt: new Date(to) } : {}),
    },
  };
}

function adminAuditLatestRecordedAt(value: { createdAt: Date | null; recordedAt: Date | null }) {
  if (!value.recordedAt) return value.createdAt;
  if (!value.createdAt) return value.recordedAt;
  return value.recordedAt > value.createdAt ? value.recordedAt : value.createdAt;
}

function adminAuditExportFormat(value: string | null | undefined): 'csv' | 'json' {
  const normalized = normalizeNullable(value)?.toLowerCase() ?? 'csv';
  if (normalized !== 'csv' && normalized !== 'json') {
    throw new BadRequestException('Unsupported audit export format');
  }
  return normalized;
}

function adminAuditExportFilterEvidence(options: AdminAuditLogListOptions, view: AdminAuditSavedView) {
  const normalizedFilters = {
    actorType: normalizeNullable(options.actorType),
    area: normalizeNullable(options.area),
    bucket: normalizeNullable(options.bucket),
    correlationId: normalizeNullable(options.correlationId),
    eventId: normalizeNullable(options.eventId),
    from: normalizeNullable(options.from),
    objectType: normalizeNullable(options.objectType),
    outcome: normalizeNullable(options.outcome),
    q: normalizeNullable(options.q),
    range: normalizeNullable(options.range),
    requestId: normalizeNullable(options.requestId),
    severity: normalizeNullable(options.severity),
    sort: normalizeNullable(options.sort),
    targetPrefix: normalizeNullable(options.targetPrefix),
    to: normalizeNullable(options.to),
    view,
  };
  const filterKeys = Object.entries(normalizedFilters)
    .filter(([, value]) => Boolean(value))
    .map(([key]) => key)
    .sort();
  return {
    filterHash: createHash('sha256').update(JSON.stringify(normalizedFilters)).digest('hex'),
    filterKeys,
  };
}

function adminAuditWorkspaceFacets(groups: readonly AdminAuditGroupCount[]): AdminAuditWorkspaceFacetCounts {
  const counts: AdminAuditWorkspaceFacetCounts = {
    actorTypeCounts: {},
    areaCounts: {},
    outcomeCounts: {},
    severityCounts: {},
  };
  for (const group of groups) {
    const classification = classifyAdminAuditAction(group.action);
    const canonical = group.schemaVersion >= 2;
    const actorType = classifyAdminAuditActorType(
      group.action,
      group.actorType,
      group.source,
      group.actorId,
      group.schemaVersion,
    );
    const area = canonical ? group.area : classification.area;
    const outcome = canonical ? group.outcome : classification.outcome;
    const severity = canonical ? group.severity : classification.severity;
    incrementAuditFacet(counts.actorTypeCounts, actorType, group._count._all);
    incrementAuditFacet(counts.areaCounts, area, group._count._all);
    incrementAuditFacet(counts.outcomeCounts, outcome, group._count._all);
    incrementAuditFacet(counts.severityCounts, severity, group._count._all);
  }
  return counts;
}

function adminAuditSavedViewCount(view: AdminAuditSavedView, groups: readonly AdminAuditGroupCount[]) {
  return groups.reduce((total, group) => {
    if (group.action === 'admin_web.page_view') return total;
    const classification = classifyAdminAuditAction(group.action);
    const canonical = group.schemaVersion >= 2;
    const area = canonical ? group.area : classification.area;
    const severity = canonical ? group.severity : classification.severity;
    const include =
      view === 'ALL' ||
      (view === 'REVIEW_REQUIRED' &&
        group.action !== 'admin.background_jobs.failure_registered' &&
        (severity === 'REVIEW' || severity === 'CRITICAL')) ||
      (view === 'OPERATOR_CHANGES' && area === 'OPERATOR') ||
      (view === 'MONEY_POLICY' && (area === 'MONEY' || area === 'POLICY')) ||
      (view === 'SECURITY_ACCESS' && area === 'SECURITY') ||
      (view === 'SYSTEM_INCIDENTS' &&
        area === 'SYSTEM' &&
        (severity === 'REVIEW' || severity === 'CRITICAL'));
    return include ? total + group._count._all : total;
  }, 0);
}

function auditFacetEntries(counts: Record<string, number>) {
  return Object.entries(counts)
    .map(([value, count]) => ({ value, count }))
    .sort((left, right) => right.count - left.count || left.value.localeCompare(right.value));
}

function incrementAuditFacet(counts: Record<string, number>, value: string, increment: number) {
  counts[value] = (counts[value] ?? 0) + increment;
}

function adminAuditLogSavedView(value: string | null | undefined): AdminAuditSavedView {
  const normalized = normalizeNullable(value)?.toUpperCase() ?? 'ALL';
  const supported = new Set<string>([...ADMIN_AUDIT_SAVED_VIEWS.map((view) => view.key), 'LEGACY_TELEMETRY']);
  if (!supported.has(normalized)) throw new BadRequestException('Unsupported audit saved view');
  return normalized as AdminAuditSavedView;
}

function adminAuditAreaFilter(value: string | null | undefined): AdminAuditAreaValue | null {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) return null;
  if (!['OPERATOR', 'POLICY', 'MONEY', 'BOOKING', 'SECURITY', 'SYSTEM', 'UNKNOWN'].includes(normalized)) {
    throw new BadRequestException('Unsupported audit area');
  }
  return normalized as AdminAuditAreaValue;
}

function adminAuditSeverityFilter(value: string | null | undefined): AdminAuditSeverityValue | null {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) return null;
  if (!['INFO', 'NOTICE', 'REVIEW', 'CRITICAL'].includes(normalized)) {
    throw new BadRequestException('Unsupported audit severity');
  }
  return normalized as AdminAuditSeverityValue;
}

function adminAuditOutcomeFilter(value: string | null | undefined): AdminAuditOutcomeValue | null {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) return null;
  if (
    ![
      'SUCCEEDED',
      'FAILED',
      'DENIED',
      'SKIPPED',
      'OPENED',
      'ACKNOWLEDGED',
      'RESOLVED',
      'RECORDED',
      'UNKNOWN',
    ].includes(normalized)
  ) {
    throw new BadRequestException('Unsupported audit outcome');
  }
  return normalized as AdminAuditOutcomeValue;
}

function adminAuditActorTypeFilter(value: string | null | undefined): AdminAuditActorTypeValue | null {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) return null;
  if (!['HUMAN', 'SYSTEM', 'SERVICE', 'UNKNOWN'].includes(normalized)) {
    throw new BadRequestException('Unsupported audit actor type');
  }
  return normalized as AdminAuditActorTypeValue;
}

type AdminAuditCursor = { occurredAt: Date; id: string; snapshotAt: Date };

function adminAuditLogCursor(value: string | null | undefined): AdminAuditCursor | null {
  const normalized = normalizeNullable(value);
  if (!normalized) return null;
  try {
    const parsed = JSON.parse(Buffer.from(normalized, 'base64url').toString('utf8')) as Record<
      string,
      unknown
    >;
    const occurredAt = new Date(String(parsed.occurredAt ?? ''));
    const snapshotAt = new Date(String(parsed.snapshotAt ?? ''));
    const id = typeof parsed.id === 'string' ? parsed.id : '';
    if (!id || Number.isNaN(occurredAt.getTime()) || Number.isNaN(snapshotAt.getTime())) throw new Error();
    return { occurredAt, id, snapshotAt };
  } catch {
    throw new BadRequestException('Audit cursor is invalid. Clear pagination and retry.');
  }
}

function adminAuditLogCursorValue(occurredAt: Date, id: string, snapshotAt: Date) {
  return Buffer.from(
    JSON.stringify({
      occurredAt: occurredAt.toISOString(),
      id,
      snapshotAt: snapshotAt.toISOString(),
    }),
  ).toString('base64url');
}

function adminAuditLogCursorWhere(
  cursor: AdminAuditCursor | null,
  generatedAt: Date,
  sort: 'asc' | 'desc',
): Prisma.AdminAuditLogWhereInput {
  return {
    AND: [
      { timelineAt: { lte: generatedAt } },
      ...(cursor
        ? [
            {
              OR:
                sort === 'desc'
                  ? [
                      { timelineAt: { lt: cursor.occurredAt } },
                      { timelineAt: cursor.occurredAt, id: { lt: cursor.id } },
                    ]
                  : [
                      { timelineAt: { gt: cursor.occurredAt } },
                      { timelineAt: cursor.occurredAt, id: { gt: cursor.id } },
                    ],
            },
          ]
        : []),
    ],
  };
}

function adminAuditLogPreviousPageWhere(
  cursor: AdminAuditCursor,
  generatedAt: Date,
  sort: 'asc' | 'desc',
): Prisma.AdminAuditLogWhereInput {
  return {
    AND: [
      { timelineAt: { lte: generatedAt } },
      {
        OR:
          sort === 'desc'
            ? [
                { timelineAt: { gt: cursor.occurredAt } },
                { timelineAt: cursor.occurredAt, id: { gt: cursor.id } },
              ]
            : [
                { timelineAt: { lt: cursor.occurredAt } },
                { timelineAt: cursor.occurredAt, id: { lt: cursor.id } },
              ],
      },
    ],
  };
}

function adminAuditLogSort(value: string | null | undefined): 'asc' | 'desc' {
  return normalizeNullable(value)?.toLowerCase() === 'oldest' ? 'asc' : 'desc';
}

function operationalPolicyAuditSource(value: string | null | undefined): AdminOperationalPolicyAuditSource {
  return value === 'automated_smoke' || value === 'legacy_unknown' ? value : 'operator';
}

function operationalPolicyAuditCursor(
  value: string | null | undefined,
  source: AdminOperationalPolicyAuditSource,
) {
  const normalized = normalizeNullable(value);
  if (!normalized || normalized.length > 500) return null;
  try {
    const parsed = JSON.parse(Buffer.from(normalized, 'base64url').toString('utf8')) as {
      id?: unknown;
      source?: unknown;
    };
    return typeof parsed.id === 'string' &&
      parsed.id.length > 0 &&
      parsed.id.length <= 200 &&
      parsed.source === source
      ? { id: parsed.id, source }
      : null;
  } catch {
    return null;
  }
}

function operationalPolicyAuditCursorValue(id: string, source: AdminOperationalPolicyAuditSource) {
  return Buffer.from(JSON.stringify({ id, source }), 'utf8').toString('base64url');
}

function adminAuditLogWhere(options: AdminAuditLogListOptions): Prisma.AdminAuditLogWhereInput | undefined {
  const filters: Prisma.AdminAuditLogWhereInput[] = [];
  const actions = (Array.isArray(options.action) ? options.action : [options.action])
    .map((action) => normalizeNullable(action))
    .filter((action): action is string => Boolean(action));
  const q = normalizeNullable(options.q);
  const bucket = normalizeNullable(options.bucket);
  const priority = normalizeNullable(options.priority);
  const targetPrefix = adminAuditLogTargetPrefix(options.targetPrefix);
  const createdAt = adminAuditLogDateWhere(options.from, options.to);
  const bucketWhere = adminAuditLogBucketWhere(bucket);
  const priorityWhere = adminAuditLogPriorityWhere(priority);

  if (actions.length === 1) {
    filters.push({ action: actions[0] });
  } else if (actions.length > 1) {
    filters.push({ action: { in: actions } });
  }
  if (targetPrefix) {
    filters.push({
      action: { in: adminAuditLogTargetActions(targetPrefix) },
      target: { startsWith: targetPrefix },
    });
  }
  if (createdAt) {
    filters.push(createdAt);
  }
  if (q) {
    filters.push({
      OR: [
        { action: { contains: q, mode: 'insensitive' } },
        { target: { contains: q, mode: 'insensitive' } },
        { actor: { id: { contains: q, mode: 'insensitive' } } },
        { actor: { email: { contains: q, mode: 'insensitive' } } },
        { actor: { fullName: { contains: q, mode: 'insensitive' } } },
        { actor: { phone: { contains: q, mode: 'insensitive' } } },
      ],
    });
  }
  if (bucketWhere) {
    filters.push(bucketWhere);
  }
  if (priorityWhere) {
    filters.push(priorityWhere);
  }

  if (filters.length === 0) {
    return undefined;
  }
  if (filters.length === 1) {
    return filters[0];
  }

  return { AND: filters };
}

const COMPANY_BANK_ACCOUNT_AUDIT_ACTIONS: string[] = [
  'company_bank_account.approval_requested',
  'company_bank_account.approval_rejected',
  'company_bank_account.classification',
  'company_bank_account.create',
  'company_bank_account.statement_verification',
  'company_bank_account.update',
];

function adminAuditLogTargetPrefix(value: string | null | undefined): string | null {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return null;
  }
  if (normalized === 'company_bank_account:') return normalized;
  if (/^finance_approver_request:[A-Za-z0-9_-]{1,128}$/u.test(normalized)) return normalized;
  throw new BadRequestException('Unsupported audit target prefix');
}

function adminAuditLogTargetActions(targetPrefix: string): string[] {
  return targetPrefix === 'company_bank_account:'
    ? COMPANY_BANK_ACCOUNT_AUDIT_ACTIONS
    : [...FINANCE_APPROVER_AUDIT_ACTIONS];
}

function withAdminAuditLogWhere(
  baseWhere: Prisma.AdminAuditLogWhereInput | undefined,
  nextWhere: Prisma.AdminAuditLogWhereInput,
): Prisma.AdminAuditLogWhereInput {
  if (!baseWhere) {
    return nextWhere;
  }

  return { AND: [baseWhere, nextWhere] };
}

function adminAuditLogActionSummary(actionGroups: Array<{ action: string; _count: { _all: number } }>) {
  return actionGroups.reduce(
    (summary, group) => {
      const count = group._count._all;
      if (isAdminAuditDispatchAction(group.action)) {
        summary.dispatch += count;
      }
      if (isAdminAuditPaymentAction(group.action)) {
        summary.payments += count;
      }
      if (isAdminAuditFinanceCloseoutAction(group.action)) {
        summary.financeCloseout += count;
      }
      if (isAdminAuditServicePricingAction(group.action)) {
        summary.servicePricing += count;
      }
      if (isAdminAuditNotificationAction(group.action)) {
        summary.notifications += count;
      }
      if (adminAuditLogActionPriority(group.action) >= 3) {
        summary.needsReview += count;
      }
      return summary;
    },
    {
      dispatch: 0,
      financeCloseout: 0,
      needsReview: 0,
      notifications: 0,
      payments: 0,
      servicePricing: 0,
    },
  );
}

function adminAuditLogActionPriority(action: string) {
  if (action.startsWith('operational_policy.')) {
    return 4;
  }
  if (action.startsWith('service_payout_rule.')) {
    return 4;
  }
  if (action === 'booking.completed.closeout') {
    return 4;
  }
  if (action.startsWith('payout_batch.')) {
    return 3;
  }
  if (action.startsWith('service.')) {
    return 3;
  }
  if (action.endsWith('.refund') || action.includes('reject') || action.endsWith('.retry')) {
    return 4;
  }
  if (action.startsWith('payment.') || action.startsWith('refund.')) {
    return 3;
  }
  if (action === 'admin_web.access_denied' || action === 'admin_web.action_denied') {
    return 3;
  }
  if (action.startsWith('booking.') || action.startsWith('notification.')) {
    return 2;
  }
  return 1;
}

function isAdminAuditDispatchAction(action: string) {
  return (
    action.startsWith('booking.') ||
    action.startsWith('provider.') ||
    action.startsWith('provider_') ||
    action.startsWith('provider-')
  );
}

function isAdminAuditPaymentAction(action: string) {
  return action.startsWith('payment.') || action.startsWith('refund.');
}

function isAdminAuditPayoutAction(action: string) {
  return action.startsWith('payout.') || action.startsWith('payout_batch.');
}

function isAdminAuditFinanceCloseoutAction(action: string) {
  return (
    isAdminAuditPaymentAction(action) ||
    isAdminAuditPayoutAction(action) ||
    action === 'booking.completed.closeout' ||
    action === 'booking.expire.manual' ||
    action === 'booking.no_show.mark' ||
    action.startsWith('earning.') ||
    action.startsWith('provider_wallet.') ||
    action.startsWith('wallet_ledger.')
  );
}

function isAdminAuditNotificationAction(action: string) {
  return action.startsWith('notification.') || action.startsWith('push_device.');
}

function isAdminAuditServicePricingAction(action: string) {
  return action.startsWith('service.') || action.startsWith('service_payout_rule.');
}

function adminAuditLogDateWhere(
  from: string | null | undefined,
  to: string | null | undefined,
): Prisma.AdminAuditLogWhereInput | undefined {
  const fromDate = adminAuditLogDateBoundary(from, 'from');
  const toDate = adminAuditLogDateBoundary(to, 'to');

  if (!fromDate && !toDate) {
    return undefined;
  }
  if (fromDate && toDate && fromDate.getTime() >= toDate.getTime()) {
    throw new BadRequestException('Audit log date range is invalid');
  }

  return {
    createdAt: {
      ...(fromDate ? { gte: fromDate } : {}),
      ...(toDate ? { lt: toDate } : {}),
    },
  };
}

function adminAuditLogDateBoundary(value: string | null | undefined, label: 'from' | 'to'): Date | undefined {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return undefined;
  }

  const hasExplicitOffset = /(?:z|[+-]\d{2}:?\d{2})$/i.test(normalized);
  const vietnamLocalValue = /^\d{4}-\d{2}-\d{2}$/.test(normalized)
    ? `${normalized}T00:00:00+07:00`
    : `${normalized}+07:00`;
  const date = new Date(hasExplicitOffset ? normalized : vietnamLocalValue);
  if (Number.isNaN(date.getTime())) {
    throw new BadRequestException(`Audit log ${label} date is invalid`);
  }

  return date;
}

function adminAuditLogBucketWhere(bucket: string | null): Prisma.AdminAuditLogWhereInput | undefined {
  switch (bucket) {
    case 'Dispatch':
      return {
        OR: [
          { action: { startsWith: 'booking.' } },
          { action: { startsWith: 'provider.' } },
          { action: { startsWith: 'provider_' } },
          { action: { startsWith: 'provider-' } },
        ],
      };
    case 'Operations/Policy':
      return { action: { startsWith: 'operational_policy.' } };
    case 'Payment':
      return { OR: [{ action: { startsWith: 'payment.' } }, { action: { startsWith: 'refund.' } }] };
    case 'Finance/Closeout':
      return {
        OR: [
          { action: { startsWith: 'payment.' } },
          { action: { startsWith: 'refund.' } },
          { action: { startsWith: 'payout.' } },
          { action: { startsWith: 'payout_batch.' } },
          { action: { startsWith: 'earning.' } },
          { action: { startsWith: 'provider_wallet.' } },
          { action: { startsWith: 'wallet_ledger.' } },
          { action: 'booking.completed.closeout' },
          { action: 'booking.expire.manual' },
          { action: 'booking.no_show.mark' },
        ],
      };
    case 'Service/Pricing':
      return {
        OR: [{ action: { startsWith: 'service.' } }, { action: { startsWith: 'service_payout_rule.' } }],
      };
    case 'Notification':
      return {
        OR: [{ action: { startsWith: 'notification.' } }, { action: { startsWith: 'push_device.' } }],
      };
    case 'Admin Web':
      return { action: { startsWith: 'admin_web.' } };
    case 'Partner':
      return {
        OR: [
          { action: { startsWith: 'provider_' } },
          { action: { startsWith: 'provider-' } },
          { action: { startsWith: 'provider-verification.' } },
        ],
      };
    case 'Tax':
      return { action: { startsWith: 'tax_' } };
    case 'System':
      return {
        NOT: {
          OR: [
            { action: { startsWith: 'booking.' } },
            { action: { startsWith: 'provider.' } },
            { action: { startsWith: 'provider_' } },
            { action: { startsWith: 'provider-' } },
            { action: { startsWith: 'operational_policy.' } },
            { action: { startsWith: 'payment.' } },
            { action: { startsWith: 'refund.' } },
            { action: { startsWith: 'payout.' } },
            { action: { startsWith: 'payout_batch.' } },
            { action: { startsWith: 'earning.' } },
            { action: { startsWith: 'provider_wallet.' } },
            { action: { startsWith: 'wallet_ledger.' } },
            { action: { startsWith: 'service.' } },
            { action: { startsWith: 'service_payout_rule.' } },
            { action: { startsWith: 'notification.' } },
            { action: { startsWith: 'push_device.' } },
            { action: { startsWith: 'tax_' } },
            { action: { startsWith: 'admin_web.' } },
          ],
        },
      };
    default:
      return undefined;
  }
}

function adminAuditLogPriorityWhere(priority: string | null): Prisma.AdminAuditLogWhereInput | undefined {
  switch (priority) {
    case '4':
      return {
        OR: [
          { action: { startsWith: 'operational_policy.' } },
          { action: { startsWith: 'service_payout_rule.' } },
          { action: 'booking.completed.closeout' },
          { action: { endsWith: '.refund' } },
          { action: { contains: 'reject' } },
          { action: { endsWith: '.retry' } },
        ],
      };
    case '3':
      return {
        OR: [
          { action: { startsWith: 'payout_batch.' } },
          { action: { startsWith: 'service.' } },
          { action: { startsWith: 'payment.' } },
          { action: { startsWith: 'refund.' } },
        ],
      };
    case '2':
      return {
        OR: [{ action: { startsWith: 'booking.' } }, { action: { startsWith: 'notification.' } }],
      };
    case '1':
      return {
        NOT: {
          OR: [
            { action: { startsWith: 'operational_policy.' } },
            { action: { startsWith: 'service_payout_rule.' } },
            { action: 'booking.completed.closeout' },
            { action: { endsWith: '.refund' } },
            { action: { contains: 'reject' } },
            { action: { endsWith: '.retry' } },
            { action: { startsWith: 'payout_batch.' } },
            { action: { startsWith: 'service.' } },
            { action: { startsWith: 'payment.' } },
            { action: { startsWith: 'refund.' } },
            { action: { startsWith: 'booking.' } },
            { action: { startsWith: 'notification.' } },
          ],
        },
      };
    default:
      return undefined;
  }
}

function adminBookingListLimit(value: number | string | null | undefined): number {
  return boundedAdminListLimit(value, ADMIN_BOOKING_LIST_LIMIT);
}

function adminBookingListPage(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return 1;
  }

  const numeric = typeof value === 'number' ? value : Number.parseInt(value, 10);
  if (!Number.isFinite(numeric)) {
    return 1;
  }

  return Math.min(Math.max(Math.trunc(numeric), 1), 500);
}

function adminBookingListPageSize(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return 20;
  }

  return boundedAdminListLimit(value, ADMIN_BOOKING_LIST_LIMIT);
}

function adminCalendarEventListTake(value: number | string | null | undefined): number {
  return boundedAdminListLimit(value, ADMIN_CALENDAR_EVENT_LIST_LIMIT);
}

function adminCalendarActor(
  actorId: string,
  input: { operatorIdentity?: string | null; operatorName?: string | null },
) {
  const id = normalizeNullable(input.operatorIdentity) ?? actorId;
  const name = normalizeNullable(input.operatorName) ?? displayAdminCalendarActorName(id);

  return { id, name };
}

function adminCalendarCreateData(
  input: CreateAdminCalendarEventDto,
  actor: { id: string; name: string },
): Prisma.AdminCalendarEventCreateInput {
  const title = normalizeRequiredAdminCalendarTitle(input.title);
  const startAt = parseRequiredAdminCalendarDate(input.start, 'Calendar start date');
  const endAt = parseRequiredAdminCalendarDate(input.end, 'Calendar end date');
  assertAdminCalendarDateRange(startAt, endAt);

  return {
    allDay: Boolean(input.allDay),
    authorId: actor.id,
    authorName: actor.name,
    description: normalizeNullable(input.description),
    endAt,
    location: normalizeNullable(input.location),
    startAt,
    tags: normalizeAdminCalendarTags(input.tags) as Prisma.InputJsonValue,
    title,
    updatedById: actor.id,
    url: normalizeNullable(input.url),
  };
}

function adminCalendarUpdateData(
  input: UpdateAdminCalendarEventDto,
  existing: { startAt: Date; endAt: Date },
  actor: { id: string },
): Prisma.AdminCalendarEventUpdateInput {
  const data: Prisma.AdminCalendarEventUpdateInput = {
    updatedById: actor.id,
  };
  const startAt =
    input.start === undefined
      ? existing.startAt
      : parseRequiredAdminCalendarDate(input.start, 'Calendar start date');
  const endAt =
    input.end === undefined ? existing.endAt : parseRequiredAdminCalendarDate(input.end, 'Calendar end date');
  assertAdminCalendarDateRange(startAt, endAt);

  if (input.title !== undefined) {
    data.title = normalizeRequiredAdminCalendarTitle(input.title);
  }
  if (input.start !== undefined) {
    data.startAt = startAt;
  }
  if (input.end !== undefined) {
    data.endAt = endAt;
  }
  if (input.allDay !== undefined) {
    data.allDay = Boolean(input.allDay);
  }
  if (input.description !== undefined) {
    data.description = normalizeNullable(input.description);
  }
  if (input.location !== undefined) {
    data.location = normalizeNullable(input.location);
  }
  if (input.tags !== undefined) {
    data.tags = normalizeAdminCalendarTags(input.tags) as Prisma.InputJsonValue;
  }
  if (input.url !== undefined) {
    data.url = normalizeNullable(input.url);
  }

  return data;
}

function adminCalendarEventView(event: {
  allDay: boolean;
  authorId: string;
  authorName: string;
  createdAt: Date;
  description: string | null;
  endAt: Date;
  id: string;
  location: string | null;
  startAt: Date;
  tags: Prisma.JsonValue | null;
  title: string;
  updatedAt: Date;
  updatedById: string | null;
  url: string | null;
}) {
  return {
    allDay: event.allDay,
    authorId: event.authorId,
    authorName: event.authorName,
    createdAt: event.createdAt.toISOString(),
    description: event.description ?? '',
    end: event.endAt.toISOString(),
    id: event.id,
    location: event.location ?? '',
    start: event.startAt.toISOString(),
    tags: normalizeAdminCalendarTags(event.tags),
    title: event.title,
    updatedAt: event.updatedAt.toISOString(),
    updatedById: event.updatedById,
    url: event.url ?? '',
  };
}

function normalizeRequiredAdminCalendarTitle(value: unknown) {
  const title = typeof value === 'string' ? normalizeNullable(value) : null;
  if (!title) {
    throw new BadRequestException('Calendar event title is required');
  }

  return title.slice(0, 160);
}

function parseOptionalAdminCalendarDate(value: unknown, label: string) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  return parseRequiredAdminCalendarDate(value, label);
}

function parseRequiredAdminCalendarDate(value: unknown, label: string) {
  if (typeof value !== 'string' && !(value instanceof Date)) {
    throw new BadRequestException(`${label} is required`);
  }

  const date = value instanceof Date ? value : new Date(value);
  if (!Number.isFinite(date.getTime())) {
    throw new BadRequestException(`${label} is invalid`);
  }

  return date;
}

function assertAdminCalendarDateRange(startAt: Date, endAt: Date) {
  if (endAt < startAt) {
    throw new BadRequestException('Calendar event end date cannot be before the start date');
  }
}

function normalizeAdminCalendarTags(value: unknown): string[] {
  const tags = Array.isArray(value) ? value : [];

  return [
    ...new Set(
      tags
        .map((tag) => normalizeAdminCalendarTag(String(tag ?? '')))
        .filter(Boolean)
        .slice(0, 20),
    ),
  ];
}

function normalizeAdminCalendarTag(value: string) {
  return value
    .trim()
    .replace(/^#+/, '')
    .replace(/[^\p{L}\p{N}_-]/gu, '')
    .toLowerCase()
    .slice(0, 50);
}

function displayAdminCalendarActorName(identity: string) {
  const [name] = identity.split('@');

  return (
    name
      .split(/[._-]+/)
      .filter(Boolean)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join(' ') || identity
  );
}

function adminMarketingDimensionTake(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return ADMIN_MARKETING_DIMENSION_PAGE_LIMIT;
  }

  return boundedAdminListLimit(value, ADMIN_MARKETING_DIMENSION_PAGE_MAX_LIMIT);
}

function adminMarketingCouponTake(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return ADMIN_MARKETING_COUPON_PAGE_LIMIT;
  }

  return boundedAdminListLimit(value, ADMIN_MARKETING_COUPON_PAGE_MAX_LIMIT);
}

function adminMarketingCouponBookingCte(window: { startAt: Date; endAt: Date }): Prisma.Sql {
  return Prisma.sql`
    WITH coupon_bookings AS (
      SELECT
        booking."id" AS "bookingId",
        booking."status" AS "bookingStatus",
        booking."createdAt" AS "bookingCreatedAt",
        payment."amount"::bigint AS "paymentAmount",
        NULLIF(payment."rawMeta"->>'couponId', '') AS "couponId",
        COALESCE(
          NULLIF(payment."rawMeta"->>'couponCode', ''),
          NULLIF(payment."rawMeta"->>'couponCodeSnapshot', ''),
          NULLIF(payment."rawMeta"->>'couponId', ''),
          'Historical coupon'
        ) AS "couponCode",
        CASE
          WHEN COALESCE(payment."rawMeta"->>'discountAmount', '') ~ '^[0-9]{1,18}$'
          THEN (payment."rawMeta"->>'discountAmount')::bigint
          ELSE 0
        END AS "discountAmount",
        EXISTS (
          SELECT 1
          FROM "Refund" refund
          WHERE refund."bookingId" = booking."id"
            AND UPPER(refund."status") NOT IN ('CANCELLED', 'FAILED', 'REJECTED')
        ) AS "hasRefund"
      FROM "Booking" booking
      INNER JOIN "Payment" payment ON payment."bookingId" = booking."id"
      WHERE booking."createdAt" >= ${window.startAt}
        AND booking."createdAt" < ${window.endAt}
        AND (
          payment."rawMeta" ? 'couponId'
          OR payment."rawMeta" ? 'couponCode'
          OR payment."rawMeta" ? 'couponCodeSnapshot'
        )
    )
  `;
}

function adminMarketingCouponSummary(
  row: AdminMarketingCouponAggregateRow | null | undefined,
): AdminMarketingCouponSummary {
  return withMarketingCouponRates({
    appliedBookingCount: numberValue(row?.appliedBookingCount),
    cancelledBookingCount: numberValue(row?.cancelledBookingCount),
    completedBookingCount: numberValue(row?.completedBookingCount),
    completedBookingValue: numberValue(row?.completedBookingValue),
    realizedDiscountAmount: numberValue(row?.realizedDiscountAmount),
    refundedBookingCount: numberValue(row?.refundedBookingCount),
  });
}

function adminMarketingCouponState(
  coupon:
    | {
        active: boolean;
        endsAt: Date | null;
        startsAt: Date | null;
      }
    | null
    | undefined,
  now = new Date(),
) {
  if (!coupon) return 'HISTORICAL' as const;
  if (!coupon.active) return 'PAUSED' as const;
  if (coupon.startsAt && coupon.startsAt > now) return 'SCHEDULED' as const;
  if (coupon.endsAt && coupon.endsAt <= now) return 'EXPIRED' as const;
  return 'LIVE' as const;
}

function adminVietnamRealtimePointLimit(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return ADMIN_VIETNAM_REALTIME_POINT_LIST_LIMIT;
  }

  return boundedAdminListLimit(value, ADMIN_VIETNAM_REALTIME_POINT_MAX_LIMIT);
}

function normalizeAdminMarketingDimensionKey(value: unknown): AdminMarketingDimensionKey {
  if (typeof value !== 'string') {
    throw new BadRequestException('Marketing dimension is required');
  }

  const normalized = value.trim().toLowerCase();
  if (ADMIN_MARKETING_DIMENSIONS.includes(normalized as AdminMarketingDimensionKey)) {
    return normalized as AdminMarketingDimensionKey;
  }

  throw new BadRequestException('Unsupported marketing dimension');
}

function boundedAdminListSkip(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return 0;
  }

  const numeric = typeof value === 'number' ? value : Number.parseInt(value, 10);
  if (!Number.isFinite(numeric)) {
    return 0;
  }

  return Math.min(Math.max(Math.trunc(numeric), 0), 10_000);
}

function boundedAdminListLimit(value: number | string | null | undefined, max: number): number {
  if (value === null || value === undefined || value === '') {
    return max;
  }

  const numeric = typeof value === 'number' ? value : Number.parseInt(value, 10);
  if (!Number.isFinite(numeric)) {
    return max;
  }

  return Math.min(Math.max(Math.trunc(numeric), 1), max);
}

function normalizedAdminPagedSkip(requestedSkip: number, take: number, totalCount: number) {
  if (totalCount <= 0) return 0;
  return Math.min(requestedSkip, Math.floor((totalCount - 1) / take) * take);
}

const adminPartnerControlRiskCandidateSelect = {
  id: true,
  status: true,
  blockedAt: true,
  currentLocationUpdatedAt: true,
  kyc: { select: { status: true } },
  bankAccounts: {
    where: {
      status: { in: [ProviderBankAccountStatus.APPROVED, ProviderBankAccountStatus.PENDING_REVIEW] },
    },
    select: { id: true, status: true },
  },
  walletBalanceSummaries: {
    where: { currency: 'VND' },
    take: 1,
    select: { balance: true, updatedAt: true },
  },
  reports: {
    where: { status: { in: [ProviderReportStatus.OPEN, ProviderReportStatus.INVESTIGATING] } },
    orderBy: [{ severity: 'desc' }, { createdAt: 'asc' }],
    take: 10,
    select: {
      id: true,
      severity: true,
      status: true,
      createdAt: true,
      assignedAdmin: { select: { fullName: true, phone: true } },
    },
  },
  sanctions: {
    where: { status: ProviderSanctionStatus.ACTIVE },
    orderBy: { startsAt: 'asc' },
    take: 10,
    select: {
      id: true,
      type: true,
      startsAt: true,
      issuedBy: { select: { fullName: true, phone: true } },
    },
  },
} satisfies Prisma.ProviderProfileSelect;

type AdminPartnerControlRiskCandidate = Prisma.ProviderProfileGetPayload<{
  select: typeof adminPartnerControlRiskCandidateSelect;
}>;

function adminPartnerControlProviderWhere(
  query: string | null | undefined,
  review: string,
): Prisma.ProviderProfileWhereInput {
  const q = normalizeNullable(query);
  const filters: Prisma.ProviderProfileWhereInput[] = [];
  if (q) {
    filters.push({
      OR: [
        { id: { contains: q, mode: 'insensitive' } },
        { displayName: { contains: q, mode: 'insensitive' } },
        { legalName: { contains: q, mode: 'insensitive' } },
        { user: { is: { fullName: { contains: q, mode: 'insensitive' } } } },
        { user: { is: { phone: { contains: q } } } },
      ],
    });
  }
  const reviewWhere = adminPartnerControlReviewWhere(review);
  if (reviewWhere) filters.push(reviewWhere);
  return filters.length === 0 ? {} : filters.length === 1 ? filters[0] : { AND: filters };
}

function adminPartnerControlReviewWhere(review: string): Prisma.ProviderProfileWhereInput | null {
  const staleBefore = new Date(Date.now() - ADMIN_PARTNER_CONTROL_LOCATION_FRESHNESS_MINUTES * 60_000);
  const openReport = {
    reports: { some: { status: { in: [ProviderReportStatus.OPEN, ProviderReportStatus.INVESTIGATING] } } },
  } satisfies Prisma.ProviderProfileWhereInput;
  const predicates: Record<string, Prisma.ProviderProfileWhereInput> = {
    'account-block': {
      OR: [
        { blockedAt: { not: null } },
        {
          sanctions: {
            some: { status: ProviderSanctionStatus.ACTIVE, type: ProviderSanctionType.ACCOUNT_BLOCK },
          },
        },
      ],
    },
    'cash-debt': { walletBalanceSummaries: { some: { balance: { lt: 0 }, currency: 'VND' } } },
    'payout-hold': {
      sanctions: { some: { status: ProviderSanctionStatus.ACTIVE, type: ProviderSanctionType.PAYOUT_HOLD } },
    },
    report: openReport,
    overdue: { reports: { some: adminPartnerControlOverdueReportWhere(new Date()) } },
    kyc: { OR: [{ kyc: { is: null } }, { kyc: { is: { status: { not: ProviderKycStatus.APPROVED } } } }] },
    bank: { bankAccounts: { none: { status: ProviderBankAccountStatus.APPROVED } } },
    location: {
      status: {
        in: [
          ProviderStatus.ONLINE_AVAILABLE,
          ProviderStatus.ONLINE_BUSY,
          ProviderStatus.ONLINE_AVAILABLE_SOON,
        ],
      },
      OR: [{ currentLocationUpdatedAt: null }, { currentLocationUpdatedAt: { lt: staleBefore } }],
    },
  };
  if (review === 'all') return null;
  if (predicates[review]) return predicates[review];
  return { OR: Object.values(predicates) };
}

function adminPartnerControlProviderItem(
  provider: Prisma.ProviderProfileGetPayload<{ select: typeof adminProviderControlSelect }>,
) {
  const { walletBalanceSummaries = [], ...profile } = provider;
  const walletBalance = numberValue(walletBalanceSummaries[0]?.balance);
  return {
    ...profile,
    activitySummary: { ...emptyProviderActivitySummary(), walletBalance },
    earnings: [{ netAmount: walletBalance, status: EarningStatus.PENDING }],
  };
}

function adminPartnerControlRisk(candidate: AdminPartnerControlRiskCandidate, review = 'attention') {
  const wallet = candidate.walletBalanceSummaries[0];
  const accountBlock = candidate.sanctions.find((row) => row.type === ProviderSanctionType.ACCOUNT_BLOCK);
  const payoutHold = candidate.sanctions.find((row) => row.type === ProviderSanctionType.PAYOUT_HOLD);
  const urgentReport = candidate.reports.find(
    (row) => row.severity === ProviderReportSeverity.CRITICAL || row.severity === ProviderReportSeverity.HIGH,
  );
  const overdueReport = candidate.reports.find(
    (row) =>
      Date.now() - row.createdAt.getTime() >= adminPartnerControlReportSlaHours(row.severity) * 3_600_000,
  );
  const openReport = candidate.reports[0];
  const risks = {
    'account-block':
      candidate.blockedAt || accountBlock
        ? {
            kind: 'ACCOUNT_BLOCK',
            priority: 100,
            startedAt: candidate.blockedAt ?? accountBlock?.startsAt ?? null,
            slaHours: null,
            owner: accountBlock?.issuedBy,
          }
        : null,
    'cash-debt':
      numberValue(wallet?.balance) < 0
        ? { kind: 'NEGATIVE_WALLET', priority: 90, startedAt: wallet?.updatedAt ?? null, slaHours: null }
        : null,
    'payout-hold': payoutHold
      ? {
          kind: 'PAYOUT_HOLD',
          priority: 85,
          startedAt: payoutHold.startsAt,
          slaHours: null,
          owner: payoutHold.issuedBy,
        }
      : null,
    report: urgentReport
      ? {
          kind: 'URGENT_REPORT',
          priority: urgentReport.severity === ProviderReportSeverity.CRITICAL ? 80 : 75,
          startedAt: urgentReport.createdAt,
          slaHours: adminPartnerControlReportSlaHours(urgentReport.severity),
          owner: urgentReport.assignedAdmin,
        }
      : overdueReport
        ? {
            kind: 'OVERDUE_REPORT',
            priority: 70,
            startedAt: overdueReport.createdAt,
            slaHours: adminPartnerControlReportSlaHours(overdueReport.severity),
            owner: overdueReport.assignedAdmin,
          }
        : openReport
          ? {
              kind: 'OPEN_REPORT',
              priority: 60,
              startedAt: openReport.createdAt,
              slaHours: adminPartnerControlReportSlaHours(openReport.severity),
              owner: openReport.assignedAdmin,
            }
          : null,
    overdue: overdueReport
      ? {
          kind: 'OVERDUE_REPORT',
          priority: 70,
          startedAt: overdueReport.createdAt,
          slaHours: adminPartnerControlReportSlaHours(overdueReport.severity),
          owner: overdueReport.assignedAdmin,
        }
      : null,
    kyc:
      candidate.kyc?.status !== ProviderKycStatus.APPROVED
        ? { kind: 'KYC_READINESS', priority: 50, startedAt: null, slaHours: null }
        : null,
    bank: !candidate.bankAccounts.some((account) => account.status === ProviderBankAccountStatus.APPROVED)
      ? { kind: 'BANK_APPROVAL', priority: 40, startedAt: null, slaHours: null }
      : null,
    location: adminPartnerControlLocationStale(candidate, new Date())
      ? {
          kind: 'STALE_LOCATION',
          priority: 30,
          startedAt: candidate.currentLocationUpdatedAt,
          slaHours: null,
        }
      : null,
  } as const;
  const risk =
    review !== 'attention' && review !== 'risk'
      ? (risks[review as keyof typeof risks] ?? null)
      : (Object.values(risks)
          .filter((value): value is NonNullable<typeof value> => Boolean(value))
          .sort((left, right) => right.priority - left.priority)[0] ?? null);
  if (!risk) return null;
  const owner = 'owner' in risk ? risk.owner : null;
  let ownerLabel = owner?.fullName || owner?.phone || 'Responsible queue not set';
  let nextActionLabel = 'Review blocker evidence';
  switch (risk.kind) {
    case 'ACCOUNT_BLOCK':
      nextActionLabel = 'Review restriction evidence';
      break;
    case 'NEGATIVE_WALLET':
      nextActionLabel = 'Review debt';
      break;
    case 'PAYOUT_HOLD':
      nextActionLabel = 'Review payout hold';
      break;
    case 'URGENT_REPORT':
      ownerLabel = owner?.fullName || owner?.phone || 'Report triage queue';
      nextActionLabel = 'Operator: review urgent report';
      break;
    case 'OVERDUE_REPORT':
      ownerLabel = owner?.fullName || owner?.phone || 'Report triage queue';
      nextActionLabel = 'Operator: review overdue report';
      break;
    case 'OPEN_REPORT':
      ownerLabel = owner?.fullName || owner?.phone || 'Report triage queue';
      nextActionLabel = 'Operator: review report';
      break;
    case 'KYC_READINESS':
      if (candidate.kyc?.status === ProviderKycStatus.PENDING) {
        ownerLabel = 'KYC review queue';
        nextActionLabel = 'Operator: review submitted KYC';
      } else {
        ownerLabel = 'Partner';
        nextActionLabel =
          candidate.kyc?.status === ProviderKycStatus.REJECTED ||
          candidate.kyc?.status === ProviderKycStatus.BLOCKED
            ? 'Partner: correct and resubmit KYC'
            : 'Partner: submit KYC';
      }
      break;
    case 'BANK_APPROVAL':
      if (
        candidate.bankAccounts.some((account) => account.status === ProviderBankAccountStatus.PENDING_REVIEW)
      ) {
        ownerLabel = 'Bank review queue';
        nextActionLabel = 'Operator: review pending bank account';
      } else {
        ownerLabel = 'Partner';
        nextActionLabel = 'Partner: submit bank details';
      }
      break;
    case 'STALE_LOCATION':
      ownerLabel = 'Partner';
      nextActionLabel = 'Partner: refresh app location';
      break;
  }
  return {
    providerId: candidate.id,
    ...risk,
    nextActionLabel,
    ownerLabel,
    overdue: Boolean(
      risk.slaHours && risk.startedAt && Date.now() - risk.startedAt.getTime() >= risk.slaHours * 3_600_000,
    ),
  };
}

function adminPartnerControlRiskOrder(sort: string | null | undefined) {
  return (
    left: NonNullable<ReturnType<typeof adminPartnerControlRisk>>,
    right: NonNullable<ReturnType<typeof adminPartnerControlRisk>>,
  ) => {
    const ageOrder =
      (left.startedAt?.getTime() ?? Number.MAX_SAFE_INTEGER) -
      (right.startedAt?.getTime() ?? Number.MAX_SAFE_INTEGER);
    if (sort === 'oldest') return ageOrder || left.providerId.localeCompare(right.providerId);
    if (sort === 'newest') return -ageOrder || left.providerId.localeCompare(right.providerId);
    return right.priority - left.priority || ageOrder || left.providerId.localeCompare(right.providerId);
  };
}

function adminPartnerControlLocationStale(candidate: AdminPartnerControlRiskCandidate, now: Date) {
  if (
    candidate.status !== ProviderStatus.ONLINE_AVAILABLE &&
    candidate.status !== ProviderStatus.ONLINE_BUSY &&
    candidate.status !== ProviderStatus.ONLINE_AVAILABLE_SOON
  ) {
    return false;
  }
  return (
    !candidate.currentLocationUpdatedAt ||
    candidate.currentLocationUpdatedAt.getTime() <
      now.getTime() - ADMIN_PARTNER_CONTROL_LOCATION_FRESHNESS_MINUTES * 60_000
  );
}

function adminPartnerControlReportSlaHours(severity: ProviderReportSeverity) {
  if (severity === ProviderReportSeverity.CRITICAL) return 2;
  if (severity === ProviderReportSeverity.HIGH) return 8;
  if (severity === ProviderReportSeverity.MEDIUM) return 24;
  return 72;
}

function adminPartnerControlOverdueReportWhere(now: Date): Prisma.ProviderReportWhereInput {
  return {
    status: { in: [ProviderReportStatus.OPEN, ProviderReportStatus.INVESTIGATING] },
    OR: Object.values(ProviderReportSeverity).map((severity) => ({
      severity,
      createdAt: { lte: new Date(now.getTime() - adminPartnerControlReportSlaHours(severity) * 3_600_000) },
    })),
  };
}

function adminProviderReportListWhere(
  options: AdminProviderControlEvidenceListOptions,
): Prisma.ProviderReportWhereInput {
  const q = normalizeNullable(options.q);
  const status = Object.values(ProviderReportStatus).find((value) => value === options.status);
  const severity = Object.values(ProviderReportSeverity).find((value) => value === options.severity);
  const base: Prisma.ProviderReportWhereInput = {
    ...(status
      ? { status }
      : options.review === 'active'
        ? { status: { in: [ProviderReportStatus.OPEN, ProviderReportStatus.INVESTIGATING] } }
        : {}),
    ...(options.severity === 'HIGH_PLUS'
      ? { severity: { in: [ProviderReportSeverity.CRITICAL, ProviderReportSeverity.HIGH] } }
      : severity
        ? { severity }
        : {}),
    ...(q
      ? {
          OR: [
            { id: { contains: q, mode: 'insensitive' } },
            { category: { contains: q, mode: 'insensitive' } },
            { summary: { contains: q, mode: 'insensitive' } },
            { details: { contains: q, mode: 'insensitive' } },
            { providerProfileId: { contains: q, mode: 'insensitive' } },
            { providerProfile: { is: { displayName: { contains: q, mode: 'insensitive' } } } },
            { providerProfile: { is: { user: { is: { fullName: { contains: q, mode: 'insensitive' } } } } } },
            { providerProfile: { is: { user: { is: { phone: { contains: q } } } } } },
          ],
        }
      : {}),
  };
  return options.review === 'overdue'
    ? { AND: [base, adminPartnerControlOverdueReportWhere(new Date())] }
    : base;
}

function adminProviderReportListOrderBy(
  sort: string | null | undefined,
): Prisma.ProviderReportOrderByWithRelationInput[] {
  if (sort === 'oldest') return [{ createdAt: 'asc' }, { id: 'asc' }];
  if (sort === 'newest') return [{ createdAt: 'desc' }, { id: 'desc' }];
  return [{ status: 'asc' }, { severity: 'desc' }, { createdAt: 'asc' }];
}

function adminProviderSanctionListWhere(
  options: AdminProviderControlEvidenceListOptions,
): Prisma.ProviderSanctionWhereInput {
  const q = normalizeNullable(options.q);
  const status = Object.values(ProviderSanctionStatus).find((value) => value === options.status);
  const type = Object.values(ProviderSanctionType).find((value) => value === options.type);
  return {
    ...(options.status === 'HISTORY'
      ? { status: { in: [ProviderSanctionStatus.LIFTED, ProviderSanctionStatus.EXPIRED] } }
      : status
        ? { status }
        : {}),
    ...(type ? { type } : {}),
    ...(q
      ? {
          OR: [
            { id: { contains: q, mode: 'insensitive' } },
            { reason: { contains: q, mode: 'insensitive' } },
            { providerProfileId: { contains: q, mode: 'insensitive' } },
            { providerProfile: { is: { displayName: { contains: q, mode: 'insensitive' } } } },
            { providerProfile: { is: { user: { is: { fullName: { contains: q, mode: 'insensitive' } } } } } },
            { providerProfile: { is: { user: { is: { phone: { contains: q } } } } } },
            { report: { is: { summary: { contains: q, mode: 'insensitive' } } } },
          ],
        }
      : {}),
  };
}

function adminProviderSanctionListOrderBy(
  sort: string | null | undefined,
): Prisma.ProviderSanctionOrderByWithRelationInput[] {
  if (sort === 'oldest') return [{ startsAt: 'asc' }, { id: 'asc' }];
  if (sort === 'newest') return [{ startsAt: 'desc' }, { id: 'desc' }];
  return [{ status: 'asc' }, { startsAt: 'desc' }];
}

function maskedAdminOwnerPhone(value: string | null | undefined) {
  const phone = value?.trim() ?? '';
  if (!phone) return null;
  if (phone.length <= 5) return '*'.repeat(phone.length);
  return `${phone.slice(0, 3)}${'*'.repeat(Math.max(3, phone.length - 5))}${phone.slice(-2)}`;
}

function adminOwnerReference(label: string, id: string) {
  return `${label} •••${id.slice(-6)}`;
}

function adminOperationsHandoffActivityPageNumber(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return 1;
  }
  const numeric = typeof value === 'number' ? value : Number.parseInt(value, 10);
  if (!Number.isFinite(numeric)) {
    return 1;
  }
  return Math.min(Math.max(Math.trunc(numeric), 1), 10_000);
}

function adminOperationsHandoffActivityPageSize(value: number | string | null | undefined): number {
  if (value === null || value === undefined || value === '') {
    return 3;
  }
  const numeric = typeof value === 'number' ? value : Number.parseInt(value, 10);
  if (!Number.isFinite(numeric)) {
    return 3;
  }
  return Math.min(Math.max(Math.trunc(numeric), 1), 20);
}

function operationsHandoffPageNumber(value: number | string | null | undefined) {
  const parsed = typeof value === 'number' ? value : Number.parseInt(value ?? '', 10);
  return Number.isFinite(parsed) ? Math.min(Math.max(Math.trunc(parsed), 1), 10_000) : 1;
}

function operationsHandoffPageSize(value: number | string | null | undefined) {
  const parsed = typeof value === 'number' ? value : Number.parseInt(value ?? '', 10);
  return Number.isFinite(parsed) ? Math.min(Math.max(Math.trunc(parsed), 1), 100) : 25;
}

function sameAdminOperatorIdentity(
  left: { email: string | null; phone: string | null },
  right: { email: string | null; phone: string | null },
) {
  const leftEmail = left.email?.trim().toLowerCase();
  const rightEmail = right.email?.trim().toLowerCase();
  const leftPhone = left.phone?.trim();
  const rightPhone = right.phone?.trim();
  return Boolean(
    (leftEmail && rightEmail && leftEmail === rightEmail) ||
    (leftPhone && rightPhone && leftPhone === rightPhone),
  );
}

function normalizeOperationsHandoffAge(value: string | null | undefined): string {
  const normalized = value ?? '';
  return ['under-1h', '1-4h', '4-24h', 'over-24h'].includes(normalized) ? normalized : 'all';
}

function operationsHandoffAgeMatches(ageMinutes: number, age: string) {
  if (age === 'under-1h') return ageMinutes < 60;
  if (age === '1-4h') return ageMinutes >= 60 && ageMinutes < 240;
  if (age === '4-24h') return ageMinutes >= 240 && ageMinutes < 1_440;
  if (age === 'over-24h') return ageMinutes >= 1_440;
  return true;
}

function operationsHandoffRangeStart(value: string | null | undefined) {
  if (value === 'all') return null;
  const dayCount = value === 'today' ? 1 : value === '30d' ? 30 : 7;
  return new Date(addLocalDays(startOfLocalDay(Date.now()), -(dayCount - 1)));
}

function adminOperationsHandoffActivityRefsCte(
  range: string | null | undefined,
  source: string | null | undefined,
  review: string | null | undefined,
  backlog: string | null | undefined,
  age: string | null | undefined,
  reason: string | null | undefined,
  now: Date,
) {
  const bounds = adminBookingListDateBounds({ dateRange: normalizeNullable(range) ?? undefined });
  const normalizedSource = adminOperationsHandoffActivitySource(source);
  const normalizedReview = adminOperationsHandoffActivityReview(review);
  const normalizedBacklog = adminOperationsHandoffActivityBacklog(backlog, normalizedReview);
  const normalizedAge = adminOperationsHandoffActivityAge(age, normalizedReview);
  const normalizedReason = adminOperationsHandoffActivityReason(reason, normalizedReview, normalizedSource);
  const bookingDateCondition = adminOperationsHandoffActivityDateCondition(
    Prisma.sql`booking."updatedAt"`,
    bounds,
  );
  const chatDateCondition = adminOperationsHandoffActivityDateCondition(
    Prisma.sql`message."createdAt"`,
    bounds,
  );
  const auditDateCondition = adminOperationsHandoffActivityDateCondition(
    Prisma.sql`audit."createdAt"`,
    bounds,
  );
  const notificationDateCondition = adminOperationsHandoffActivityDateCondition(
    Prisma.sql`notification."createdAt"`,
    bounds,
  );
  const financeOccurredAt = Prisma.sql`COALESCE(payout_batch."createdAt", earning."createdAt")`;
  const financeDateCondition = adminOperationsHandoffActivityDateCondition(financeOccurredAt, bounds);
  const bookingReviewCondition =
    normalizedReview === 'NEEDS_REVIEW'
      ? adminOperationsHandoffBookingNeedsReviewCondition(now)
      : Prisma.sql`TRUE`;
  const recordOnlyReviewCondition =
    normalizedReview === 'NEEDS_REVIEW' ? Prisma.sql`FALSE` : Prisma.sql`TRUE`;

  const branches: Record<Exclude<AdminOperationsHandoffActivitySource, 'ALL'>, Prisma.Sql> = {
    BOOKING: Prisma.sql`
      SELECT
        'BOOKING'::text AS kind,
        booking.id,
        booking."updatedAt" AS "occurredAt",
        ${adminOperationsHandoffBookingReasonExpression(now)} AS reason
      FROM "Booking" booking
      WHERE ${bookingDateCondition}
        AND ${adminBookingProductionDataSql()}
        AND ${bookingReviewCondition}
    `,
    CHAT: Prisma.sql`
      SELECT
        'CHAT'::text AS kind,
        message.id,
        message."createdAt" AS "occurredAt",
        'RECORD'::text AS reason
      FROM "ChatMessage" message
      INNER JOIN "ChatRoom" room ON room.id = message."chatRoomId"
      INNER JOIN "Booking" booking ON booking.id = room."bookingId"
      WHERE ${chatDateCondition}
        AND ${adminBookingProductionDataSql()}
        AND ${recordOnlyReviewCondition}
    `,
    AUDIT: Prisma.sql`
      SELECT
        'AUDIT'::text AS kind,
        audit.id,
        audit."createdAt" AS "occurredAt",
        'RECORD'::text AS reason
      FROM "AdminAuditLog" audit
      WHERE ${auditDateCondition}
        AND ${recordOnlyReviewCondition}
    `,
    NOTIFICATION: Prisma.sql`
      SELECT
        'NOTIFICATION'::text AS kind,
        notification.id,
        notification."createdAt" AS "occurredAt",
        'NOTIFICATION_FAILURE'::text AS reason
      FROM "Notification" notification
      WHERE ${notificationDateCondition}
        AND ${adminNotificationProductionDataSql()}
        AND EXISTS (
          SELECT 1
          FROM "NotificationDelivery" delivery
          INNER JOIN "PushDevice" failed_device
            ON failed_device.id = delivery."pushDeviceId"
          WHERE delivery."notificationId" = notification.id
            AND delivery.status = 'FAILED'
            AND failed_device.enabled = TRUE
        )
        AND NOT EXISTS (
          SELECT 1
          FROM "NotificationDelivery" recovered_delivery
          WHERE recovered_delivery."notificationId" = notification.id
            AND recovered_delivery.status IN ('SENT', 'DELIVERED', 'SUCCESS')
        )
    `,
    FINANCE: Prisma.sql`
      SELECT
        'FINANCE'::text AS kind,
        earning.id,
        ${financeOccurredAt} AS "occurredAt",
        'FINANCE_UNPAID'::text AS reason
      FROM "ProviderEarning" earning
      INNER JOIN "Booking" booking ON booking.id = earning."bookingId"
      LEFT JOIN "ProviderPayoutBatch" payout_batch
        ON payout_batch.id = earning."payoutBatchId"
      WHERE ${financeDateCondition}
        AND ${adminBookingProductionDataSql()}
        AND ${adminOperationsHandoffFinanceNeedsReviewCondition(now)}
    `,
  };
  const selectedBranches =
    normalizedSource === 'ALL'
      ? [branches.BOOKING, branches.CHAT, branches.AUDIT, branches.NOTIFICATION, branches.FINANCE]
      : [branches[normalizedSource]];
  const backlogCondition = adminOperationsHandoffActivityBacklogCondition(
    Prisma.sql`"occurredAt"`,
    normalizedBacklog,
    now,
  );
  const ageCondition = adminOperationsHandoffActivityAgeCondition(
    Prisma.sql`"occurredAt"`,
    normalizedAge,
    now,
  );
  const reasonCondition = adminOperationsHandoffActivityReasonCondition(Prisma.sql`reason`, normalizedReason);
  const over24hCondition = adminOperationsHandoffActivityAgeCondition(
    Prisma.sql`"occurredAt"`,
    'OVER_24H',
    now,
  );

  return Prisma.sql`
    raw_activity_refs AS (
      ${Prisma.join(selectedBranches, '\nUNION ALL\n')}
    ),
    backlog_activity_refs AS (
      SELECT kind, id, "occurredAt", reason
      FROM raw_activity_refs
      WHERE ${backlogCondition}
    ),
    over_24h_activity_refs AS (
      SELECT kind, id, "occurredAt", reason
      FROM backlog_activity_refs
      WHERE ${over24hCondition}
    ),
    aged_activity_refs AS (
      SELECT kind, id, "occurredAt", reason
      FROM backlog_activity_refs
      WHERE ${ageCondition}
    ),
    activity_refs AS (
      SELECT kind, id, "occurredAt", reason
      FROM aged_activity_refs
      WHERE ${reasonCondition}
    )
  `;
}

function adminOperationsHandoffActivitySource(
  value: string | null | undefined,
): AdminOperationsHandoffActivitySource {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (
    normalized === 'AUDIT' ||
    normalized === 'BOOKING' ||
    normalized === 'CHAT' ||
    normalized === 'FINANCE' ||
    normalized === 'NOTIFICATION'
  ) {
    return normalized;
  }
  return 'ALL';
}

function adminOperationsHandoffActivityReview(
  value: string | null | undefined,
): AdminOperationsHandoffActivityReview {
  return normalizeNullable(value)?.toLowerCase() === 'needs-review' ? 'NEEDS_REVIEW' : 'ALL';
}

function adminOperationsHandoffActivityBacklog(
  value: string | null | undefined,
  review: AdminOperationsHandoffActivityReview,
): AdminOperationsHandoffActivityBacklog {
  if (review !== 'NEEDS_REVIEW') {
    return 'ALL';
  }
  switch (normalizeNullable(value)?.toLowerCase()) {
    case 'legacy':
      return 'LEGACY';
    case 'all':
      return 'ALL';
    case 'current':
    default:
      return 'CURRENT';
  }
}

function adminOperationsHandoffCurrentBacklogBoundary(now: Date) {
  return new Date(now.getTime() - ADMIN_OPERATIONS_HANDOFF_CURRENT_BACKLOG_DAYS * 24 * 60 * 60 * 1000);
}

function adminOperationsHandoffActivityBacklogCondition(
  column: Prisma.Sql,
  backlog: AdminOperationsHandoffActivityBacklog,
  now: Date,
) {
  const boundary = adminOperationsHandoffCurrentBacklogBoundary(now);
  switch (backlog) {
    case 'CURRENT':
      return Prisma.sql`${column} >= ${boundary}`;
    case 'LEGACY':
      return Prisma.sql`${column} < ${boundary}`;
    case 'ALL':
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminOperationsHandoffActivityReason(
  value: string | null | undefined,
  review: AdminOperationsHandoffActivityReview,
  source: AdminOperationsHandoffActivitySource,
): AdminOperationsHandoffActivityReason {
  if (review !== 'NEEDS_REVIEW') {
    return 'ALL';
  }
  const requested = (() => {
    switch (normalizeNullable(value)?.toLowerCase()) {
      case 'booking-state':
        return 'BOOKING_STATE' as const;
      case 'payment':
        return 'PAYMENT' as const;
      case 'missing-settlement':
        return 'MISSING_SETTLEMENT' as const;
      case 'notification-failure':
        return 'NOTIFICATION_FAILURE' as const;
      case 'finance-unpaid':
        return 'FINANCE_UNPAID' as const;
      default:
        return 'ALL' as const;
    }
  })();
  if (requested === 'ALL' || source === 'ALL') {
    return requested;
  }
  if (
    source === 'BOOKING' &&
    (requested === 'BOOKING_STATE' || requested === 'PAYMENT' || requested === 'MISSING_SETTLEMENT')
  ) {
    return requested;
  }
  if (source === 'NOTIFICATION' && requested === 'NOTIFICATION_FAILURE') {
    return requested;
  }
  if (source === 'FINANCE' && requested === 'FINANCE_UNPAID') {
    return requested;
  }
  return 'ALL';
}

function adminOperationsHandoffActivityAge(
  value: string | null | undefined,
  review: AdminOperationsHandoffActivityReview,
): AdminOperationsHandoffActivityAge {
  if (review !== 'NEEDS_REVIEW') {
    return 'ALL';
  }
  switch (normalizeNullable(value)?.toLowerCase()) {
    case 'under-1h':
      return 'UNDER_1H';
    case '1-4h':
      return 'ONE_TO_4H';
    case '4-24h':
      return 'FOUR_TO_24H';
    case 'over-24h':
      return 'OVER_24H';
    default:
      return 'ALL';
  }
}

function adminOperationsHandoffActivitySort(
  value: string | null | undefined,
  review: AdminOperationsHandoffActivityReview,
): AdminOperationsHandoffActivitySort {
  if (review !== 'NEEDS_REVIEW') {
    return 'NEWEST';
  }
  return normalizeNullable(value)?.toLowerCase() === 'newest' ? 'NEWEST' : 'OLDEST';
}

function adminOperationsHandoffActivityAgeCondition(
  column: Prisma.Sql,
  age: AdminOperationsHandoffActivityAge,
  now: Date,
) {
  const nowMs = now.getTime();
  const oneHourAgo = new Date(nowMs - 60 * 60 * 1000);
  const fourHoursAgo = new Date(nowMs - 4 * 60 * 60 * 1000);
  const twentyFourHoursAgo = new Date(nowMs - 24 * 60 * 60 * 1000);
  switch (age) {
    case 'UNDER_1H':
      return Prisma.sql`${column} >= ${oneHourAgo}`;
    case 'ONE_TO_4H':
      return Prisma.sql`${column} < ${oneHourAgo} AND ${column} >= ${fourHoursAgo}`;
    case 'FOUR_TO_24H':
      return Prisma.sql`${column} < ${fourHoursAgo} AND ${column} >= ${twentyFourHoursAgo}`;
    case 'OVER_24H':
      return Prisma.sql`${column} < ${twentyFourHoursAgo}`;
    case 'ALL':
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminOperationsHandoffActivityReasonCondition(
  column: Prisma.Sql,
  reason: AdminOperationsHandoffActivityReason,
) {
  switch (reason) {
    case 'BOOKING_STATE':
      return Prisma.sql`${column} = 'BOOKING_STATE'`;
    case 'PAYMENT':
      return Prisma.sql`${column} = 'PAYMENT'`;
    case 'MISSING_SETTLEMENT':
      return Prisma.sql`${column} = 'MISSING_SETTLEMENT'`;
    case 'NOTIFICATION_FAILURE':
      return Prisma.sql`${column} = 'NOTIFICATION_FAILURE'`;
    case 'FINANCE_UNPAID':
      return Prisma.sql`${column} = 'FINANCE_UNPAID'`;
    case 'ALL':
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminOperationsHandoffBookingReasonExpression(now: Date) {
  return Prisma.sql`
    CASE
      WHEN ${adminOperationsHandoffBookingPaymentCondition(now)} THEN 'PAYMENT'
      WHEN ${adminOperationsHandoffBookingMissingSettlementCondition(now)} THEN 'MISSING_SETTLEMENT'
      WHEN ${adminOperationsHandoffBookingStateCondition(now)} THEN 'BOOKING_STATE'
      ELSE 'RECORD'
    END
  `;
}

function adminOperationsHandoffBookingNeedsReviewCondition(now: Date) {
  return Prisma.sql`
    (
      ${adminOperationsHandoffBookingStateCondition(now)}
      OR ${adminOperationsHandoffBookingPaymentCondition(now)}
      OR ${adminOperationsHandoffBookingMissingSettlementCondition(now)}
    )
  `;
}

function adminOperationsHandoffFinanceNeedsReviewCondition(now: Date) {
  const staleProcessingBoundary = new Date(now.getTime() - 24 * 60 * 60 * 1000);

  return Prisma.sql`
    (
      (
        earning."netAmount" < 0
        AND earning.status::text IN (${EarningStatus.PENDING}, ${EarningStatus.AVAILABLE})
      )
      OR (
        earning.status::text = ${EarningStatus.PENDING}
        AND (
          earning."availableAt" IS NULL
          OR earning."availableAt" <= ${now}
        )
      )
      OR payout_batch.status::text = ${PayoutBatchStatus.FAILED}
      OR (
        payout_batch.status::text = ${PayoutBatchStatus.PROCESSING}
        AND payout_batch."createdAt" <= ${staleProcessingBoundary}
      )
    )
  `;
}

function adminOperationsHandoffBookingStateCondition(now: Date) {
  const matchingDelaySla = adminOperationsHandoffPolicySlaInterval(
    START_SHIFT_ACTION_SLA_POLICY_KEYS.matchingDelays,
    DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.matchingDelays,
  );
  const operatorActionSla = adminOperationsHandoffPolicySlaInterval(
    START_SHIFT_ACTION_SLA_POLICY_KEYS.cancellationReview,
    DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.cancellationReview,
  );

  return Prisma.sql`
    (
      (
        booking.status::text = 'CREATED'
        AND booking."createdAt" <= ${now} - ${matchingDelaySla}
      )
      OR (
        booking.status::text = 'OPEN_MATCHING'
        AND COALESCE(booking."openedAt", booking."createdAt") <= ${now} - ${matchingDelaySla}
        AND (
          booking."expiresAt" IS NULL
          OR booking."expiresAt" <= ${now}
          OR NOT EXISTS (
            SELECT 1
            FROM "BookingParticipant" matching_participant
            WHERE matching_participant."bookingId" = booking.id
          )
        )
      )
      OR (
        booking.status::text IN ('MATCHED', 'PROVIDER_ON_THE_WAY', 'ARRIVED')
        AND booking."scheduledStartAt" <= ${now} - ${matchingDelaySla}
      )
      OR (
        booking.status::text = 'IN_SERVICE'
        AND booking."scheduledEndAt" <= ${now} - ${matchingDelaySla}
      )
      OR EXISTS (
        SELECT 1
        FROM "BookingOpsTask" ops_task
        WHERE ops_task."bookingId" = booking.id
          AND booking.status::text NOT IN ('COMPLETED', 'CANCELLED', 'EXPIRED', 'NO_SHOW')
          AND (
            ops_task.status::text = 'BLOCKED'
            OR (
              ops_task.status::text = 'PENDING'
              AND ops_task."updatedAt" <= ${now} - ${operatorActionSla}
            )
          )
      )
    )
  `;
}

function adminOperationsHandoffBookingPaymentCondition(now: Date) {
  const paymentHoldSla = adminOperationsHandoffPolicySlaInterval(
    START_SHIFT_ACTION_SLA_POLICY_KEYS.paymentHolds,
    DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.paymentHolds,
  );
  const refundReviewSla = adminOperationsHandoffPolicySlaInterval(
    START_SHIFT_ACTION_SLA_POLICY_KEYS.refundReview,
    DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.refundReview,
  );

  return Prisma.sql`
    (
      EXISTS (
        SELECT 1
        FROM "Payment" payment
        WHERE payment."bookingId" = booking.id
          AND payment.method::text <> 'CASH'
          AND payment.status::text = 'FAILED'
          AND booking.status::text IN (
            'OPEN_MATCHING',
            'MATCHED',
            'PROVIDER_ON_THE_WAY',
            'ARRIVED',
            'IN_SERVICE',
            'COMPLETED'
          )
      )
      OR (
        booking.status::text IN ('CANCELLED', 'EXPIRED', 'NO_SHOW')
        AND EXISTS (
          SELECT 1
          FROM "Payment" payment
          WHERE payment."bookingId" = booking.id
            AND payment.method::text <> 'CASH'
            AND (
              (
                payment.status::text IN ('PENDING', 'AUTHORIZED')
                AND booking."updatedAt" <= ${now} - ${paymentHoldSla}
              )
              OR (
                payment.status::text = 'CAPTURED'
                AND (
                  NOT EXISTS (
                    SELECT 1
                    FROM "Refund" any_refund
                    WHERE any_refund."paymentId" = payment.id
                  )
                  OR EXISTS (
                    SELECT 1
                    FROM "Refund" overdue_refund
                    WHERE overdue_refund."paymentId" = payment.id
                      AND UPPER(overdue_refund.status) NOT IN (
                        'COMPLETED',
                        'REFUNDED',
                        'CANCELLED',
                        'REJECTED'
                      )
                      AND overdue_refund."createdAt" <= ${now} - ${refundReviewSla}
                  )
                )
              )
            )
        )
      )
      OR EXISTS (
        SELECT 1
        FROM "Refund" overdue_refund
        INNER JOIN "Payment" refund_payment
          ON refund_payment.id = overdue_refund."paymentId"
        WHERE overdue_refund."bookingId" = booking.id
          AND refund_payment.method::text <> 'CASH'
          AND refund_payment.status::text NOT IN ('REFUNDED', 'RELEASED')
          AND UPPER(overdue_refund.status) NOT IN (
            'COMPLETED',
            'REFUNDED',
            'CANCELLED',
            'REJECTED'
          )
          AND overdue_refund."createdAt" <= ${now} - ${refundReviewSla}
      )
    )
  `;
}

function adminOperationsHandoffPolicySlaInterval(key: string, defaultMinutes: number) {
  return Prisma.sql`
    (
      COALESCE(
        (
          SELECT CASE
            WHEN JSONB_TYPEOF(setting.value) = 'number'
              AND (setting.value #>> '{}')::numeric BETWEEN 1 AND 10080
              THEN (setting.value #>> '{}')::integer
            ELSE NULL
          END
          FROM "OperationalPolicySetting" setting
          WHERE setting.key = ${key}
        ),
        ${defaultMinutes}
      ) * INTERVAL '1 minute'
    )
  `;
}

function adminOperationsHandoffBookingMissingSettlementCondition(now: Date) {
  return Prisma.sql`
    (
      booking.status::text = 'COMPLETED'
      AND booking."updatedAt" <= ${now}
        - (${ADMIN_OPERATIONS_HANDOFF_SETTLEMENT_GRACE_MINUTES} * INTERVAL '1 minute')
      AND LOWER(COALESCE(booking.metadata #>> '{smokeFixture}', 'false')) <> 'true'
      AND (
        NOT EXISTS (
          SELECT 1
          FROM "ProviderEarning" earning
          WHERE earning."bookingId" = booking.id
        )
        OR NOT EXISTS (
          SELECT 1
          FROM "BookingSettlementSnapshot" snapshot
          WHERE snapshot."bookingId" = booking.id
        )
      )
    )
  `;
}

function adminOperationsHandoffActivityDateCondition(
  column: Prisma.Sql,
  bounds: ReturnType<typeof adminBookingListDateBounds>,
) {
  const hasStart = Number.isFinite(bounds?.startMs);
  const hasEnd = Number.isFinite(bounds?.endMs);
  if (hasStart && hasEnd) {
    return Prisma.sql`${column} >= ${new Date(bounds!.startMs)} AND ${column} <= ${new Date(bounds!.endMs)}`;
  }
  if (hasStart) {
    return Prisma.sql`${column} >= ${new Date(bounds!.startMs)}`;
  }
  if (hasEnd) {
    return Prisma.sql`${column} <= ${new Date(bounds!.endMs)}`;
  }
  return Prisma.sql`TRUE`;
}

function normalizeBooleanQuery(value: boolean | string | null | undefined) {
  return value === true || normalizeNullable(typeof value === 'string' ? value : undefined) === 'true';
}

function adminOperationsHandoffProviderAttentionWhere(
  locationStaleBoundary: Date,
): Prisma.ProviderProfileWhereInput {
  return {
    OR: [
      { walletBalanceSummaries: { some: { balance: { lt: 0 }, currency: 'VND' } } },
      { kyc: { is: { status: ProviderKycStatus.PENDING } } },
      {
        bankAccounts: {
          some: {
            deletedAt: null,
            status: ProviderBankAccountStatus.PENDING_REVIEW,
          },
        },
      },
      { currentLocationUpdatedAt: null },
      { currentLocationUpdatedAt: { lt: locationStaleBoundary } },
    ],
  };
}

function operationsHandoffProviderAttentionSignals(
  provider: {
    bankAccounts: ReadonlyArray<{ status: ProviderBankAccountStatus }>;
    currentLocationUpdatedAt: Date | null;
    kyc: { status: ProviderKycStatus } | null;
  },
  walletBalance: number,
  locationStaleBoundary: Date | undefined,
) {
  return {
    cashDebt: walletBalance < 0,
    kycPending: provider.kyc?.status === ProviderKycStatus.PENDING,
    bankPending: provider.bankAccounts.some(
      (account) => account.status === ProviderBankAccountStatus.PENDING_REVIEW,
    ),
    locationStale: locationStaleBoundary
      ? !provider.currentLocationUpdatedAt || provider.currentLocationUpdatedAt < locationStaleBoundary
      : false,
  };
}

function adminFileReviewPrivateFileWhere(): Prisma.FileAssetWhereInput {
  return {
    providerVerificationId: { not: null },
  };
}

function adminFileReviewPublicMediaWhere(): Prisma.FileAssetWhereInput {
  return {
    purpose: { in: [FilePurpose.PROFILE_IMAGE, FilePurpose.PROVIDER_GALLERY] },
    visibility: FileVisibility.PUBLIC,
    uploadStatus: FileUploadStatus.UPLOADED,
  };
}

function adminFileReviewFileWhere(): Prisma.FileAssetWhereInput {
  return {
    OR: [adminFileReviewPrivateFileWhere(), adminFileReviewPublicMediaWhere()],
  };
}

function adminFileReviewItemWhere(options: AdminFileReviewItemListOptions): Prisma.FileAssetWhereInput {
  const kind = normalizeFileReviewKind(options.kind);
  const stateWhere = adminFileReviewStateWhere(options.review);
  const privateWhere = {
    AND: [adminFileReviewPrivateFileWhere(), stateWhere],
  } satisfies Prisma.FileAssetWhereInput;
  const publicWhere = {
    AND: [
      adminFileReviewPublicMediaWhere(),
      stateWhere,
      { owner: { is: { providerProfile: { isNot: null } } } },
    ],
  } satisfies Prisma.FileAssetWhereInput;
  const scopeWhere =
    kind === 'private-verification'
      ? privateWhere
      : kind === 'public-media'
        ? publicWhere
        : ({ OR: [privateWhere, publicWhere] } satisfies Prisma.FileAssetWhereInput);
  const query = normalizeNullable(options.q);
  if (!query) {
    return scopeWhere;
  }

  return {
    AND: [
      scopeWhere,
      {
        OR: [
          ...adminFileReviewFileSearchConditions(query),
          {
            owner: {
              is: {
                OR: [
                  { fullName: { contains: query, mode: Prisma.QueryMode.insensitive } },
                  { phone: { contains: query, mode: Prisma.QueryMode.insensitive } },
                  {
                    providerProfile: {
                      is: { displayName: { contains: query, mode: Prisma.QueryMode.insensitive } },
                    },
                  },
                ],
              },
            },
          },
          {
            providerVerification: {
              is: {
                providerProfile: {
                  is: {
                    OR: [
                      { displayName: { contains: query, mode: Prisma.QueryMode.insensitive } },
                      {
                        user: {
                          is: {
                            OR: [
                              { fullName: { contains: query, mode: Prisma.QueryMode.insensitive } },
                              { phone: { contains: query, mode: Prisma.QueryMode.insensitive } },
                            ],
                          },
                        },
                      },
                    ],
                  },
                },
              },
            },
          },
        ],
      },
    ],
  };
}

function adminFileReviewFileSearchConditions(query: string): Prisma.FileAssetWhereInput[] {
  const conditions: Prisma.FileAssetWhereInput[] = [
    { key: { contains: query, mode: Prisma.QueryMode.insensitive } },
    { contentType: { contains: query, mode: Prisma.QueryMode.insensitive } },
    { reviewReason: { contains: query, mode: Prisma.QueryMode.insensitive } },
  ];
  const matchingPurposes = adminFileReviewPurposeSearch(query);
  if (matchingPurposes.length > 0) {
    conditions.push({ purpose: { in: matchingPurposes } });
  }
  const matchingStatus = adminFileReviewStatusSearch(query);
  if (matchingStatus) {
    conditions.push(matchingStatus);
  }
  return conditions;
}

function adminFileReviewStateWhere(reviewValue: string | null | undefined): Prisma.FileAssetWhereInput {
  const review = normalizeNullable(reviewValue);
  if (review === 'needs-review') {
    return { reviewStatus: { in: [FileReviewStatus.PENDING_REVIEW, FileReviewStatus.REJECTED] } };
  }
  if (review === 'approved') {
    return { reviewStatus: FileReviewStatus.APPROVED };
  }
  if (review === 'rejected') {
    return { reviewStatus: FileReviewStatus.REJECTED };
  }
  if (review === 'upload-incomplete') {
    return { uploadStatus: { not: FileUploadStatus.UPLOADED } };
  }
  return {};
}

function normalizeFileReviewKind(value: string | null | undefined) {
  const kind = normalizeNullable(value);
  return kind === 'private-verification' || kind === 'public-media' ? kind : null;
}

function adminFileReviewPurposeSearch(query: string): FilePurpose[] {
  const normalized = query.toLowerCase();
  const purposes: FilePurpose[] = [];
  if (normalized.includes('verification')) {
    purposes.push(FilePurpose.PROVIDER_VERIFICATION);
  }
  if (normalized.includes('gallery')) {
    purposes.push(FilePurpose.PROVIDER_GALLERY);
  }
  if (normalized.includes('profile')) {
    purposes.push(FilePurpose.PROFILE_IMAGE);
  }
  return purposes;
}

function adminFileReviewStatusSearch(query: string): Prisma.FileAssetWhereInput | null {
  const normalized = query
    .trim()
    .toLowerCase()
    .replace(/[\s_-]+/g, '');
  if (normalized === 'approved') {
    return { reviewStatus: FileReviewStatus.APPROVED };
  }
  if (normalized === 'rejected') {
    return { reviewStatus: FileReviewStatus.REJECTED };
  }
  if (normalized === 'pendingreview') {
    return { reviewStatus: FileReviewStatus.PENDING_REVIEW };
  }
  if (normalized === 'uploaded') {
    return { uploadStatus: FileUploadStatus.UPLOADED };
  }
  if (normalized === 'uploadfailed' || normalized === 'failed') {
    return { uploadStatus: FileUploadStatus.FAILED };
  }
  if (normalized === 'uploadpending') {
    return { uploadStatus: FileUploadStatus.PENDING };
  }
  return null;
}

function normalizeMarketingSpendAmount(value: unknown) {
  const amount = numberValue(value);
  if (!Number.isInteger(amount) || amount < 0 || amount > ADMIN_MARKETING_SPEND_MAX_VND) {
    throw new BadRequestException({
      code: 'MARKETING_SPEND_AMOUNT_INVALID',
      message: `Marketing spend amount must be a whole VND amount from 0 to ${ADMIN_MARKETING_SPEND_MAX_VND}`,
    });
  }

  return amount;
}

function ensureVietnamOverviewRegion(regions: Map<string, AdminVietnamOverviewRegion>, regionCode: string) {
  const region = regions.get(regionCode) ?? regions.get('other-vietnam');
  if (region) return region;

  return {
    regionCode: 'other-vietnam',
    regionName: 'Other Vietnam',
    shortName: 'VN',
    customerCount: 0,
    activeCustomerCount: 0,
    customersSeenIn30DaysCount: 0,
    partnerCount: 0,
    onlinePartnerCount: 0,
    readyPartnerCount: 0,
    busyPartnerCount: 0,
    offlinePartnerCount: 0,
    stalePartnerCount: 0,
    activeBookingCount: 0,
    needsSupplyNowCount: 0,
    assignedOrInServiceCount: 0,
    staleActiveRecordCount: 0,
    supplyShortageCount: 0,
    completedBookingCount: 0,
    cancellationCount: 0,
    revenueAmount: 0,
    paidVolumeAvailable: false,
    currency: 'VND',
  };
}

function vietnamOverviewRegionTotals(
  regions: readonly AdminVietnamOverviewRegion[],
): AdminVietnamOverviewTotals {
  return {
    customerCount: regions.reduce((total, region) => total + region.customerCount, 0),
    activeCustomerCount: regions.reduce((total, region) => total + region.activeCustomerCount, 0),
    customersSeenIn30DaysCount: regions.reduce(
      (total, region) => total + region.customersSeenIn30DaysCount,
      0,
    ),
    partnerCount: regions.reduce((total, region) => total + region.partnerCount, 0),
    onlinePartnerCount: regions.reduce((total, region) => total + region.onlinePartnerCount, 0),
    readyPartnerCount: regions.reduce((total, region) => total + region.readyPartnerCount, 0),
    busyPartnerCount: regions.reduce((total, region) => total + region.busyPartnerCount, 0),
    offlinePartnerCount: regions.reduce((total, region) => total + region.offlinePartnerCount, 0),
    stalePartnerCount: regions.reduce((total, region) => total + region.stalePartnerCount, 0),
    activeBookingCount: regions.reduce((total, region) => total + region.activeBookingCount, 0),
    needsSupplyNowCount: regions.reduce((total, region) => total + region.needsSupplyNowCount, 0),
    assignedOrInServiceCount: regions.reduce((total, region) => total + region.assignedOrInServiceCount, 0),
    staleActiveRecordCount: regions.reduce((total, region) => total + region.staleActiveRecordCount, 0),
    supplyShortageCount: regions.reduce((total, region) => total + region.supplyShortageCount, 0),
    completedBookingCount: regions.reduce((total, region) => total + region.completedBookingCount, 0),
    cancellationCount: regions.reduce((total, region) => total + region.cancellationCount, 0),
    revenueAmount: regions.reduce((total, region) => total + region.revenueAmount, 0),
    paidVolumeAvailable: regions.every((region) => region.paidVolumeAvailable),
    currency: 'VND',
  };
}

function vietnamOverviewEventPoint<TKind extends AdminVietnamOverviewPointKind>(input: {
  id: string;
  kind: TKind;
  label: string;
  latitude: unknown;
  longitude: unknown;
  occurredAt: Date | string | null | undefined;
  activityAt?: Date | string | null;
  createdAt?: Date | string | null;
  locationOccurredAt?: Date | string | null;
  source: string;
  addressText?: string | null;
  bookingId?: string | null;
  customerProfileId?: string | null;
  providerProfileId?: string | null;
  status?: string | null;
}): (AdminVietnamOverviewPoint & { kind: TKind }) | null {
  const latitude = coordinateValue(input.latitude);
  const longitude = coordinateValue(input.longitude);
  const occurredAt =
    input.occurredAt instanceof Date
      ? input.occurredAt
      : input.occurredAt
        ? new Date(input.occurredAt)
        : null;

  if (
    latitude === null ||
    longitude === null ||
    !isStoredVietnamCoordinate(latitude, longitude) ||
    (occurredAt !== null && !Number.isFinite(occurredAt.getTime()))
  ) {
    return null;
  }

  const regionCode = vietnamRegionCodeFromValues([input.addressText, input.label], {
    latitude,
    longitude,
  });

  return {
    id: input.id,
    kind: input.kind,
    label: input.label,
    latitude,
    longitude,
    occurredAt: occurredAt?.toISOString() ?? null,
    activityAt: isoDateValue(input.activityAt),
    createdAt: isoDateValue(input.createdAt),
    locationOccurredAt: isoDateValue(input.locationOccurredAt),
    regionCode,
    source: input.source,
    addressText: input.addressText ?? null,
    bookingId: input.bookingId ?? null,
    customerProfileId: input.customerProfileId ?? null,
    providerProfileId: input.providerProfileId ?? null,
    status: input.status ?? null,
  };
}

function isoDateValue(value: Date | string | null | undefined) {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isFinite(date.getTime()) ? date.toISOString() : null;
}

function vietnamOverviewSampleSource(
  key: AdminVietnamOverviewSampleSource['key'],
  returnedCount: number,
  limit: number,
  points: readonly AdminVietnamOverviewRealtimePoint[],
): AdminVietnamOverviewSampleSource {
  const mappedPointCount = points.filter((point) => {
    if (key === 'customers') return Boolean(point.customerProfileId);
    if (key === 'partners') return Boolean(point.providerProfileId);
    if (key === 'active-bookings') return Boolean(point.bookingId);
    return false;
  }).length;

  return {
    key,
    mappedPointCount,
    returnedCount,
    total: null,
    totalUnavailable: true,
    truncated: returnedCount >= limit,
  };
}

function coordinateValue(value: unknown) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function isStoredVietnamCoordinate(latitude: number, longitude: number) {
  return latitude >= 8 && latitude <= 24 && longitude >= 102 && longitude <= 110;
}

type AdminCompletedBookingOperationsSummaryRow = {
  readonly cashDebt: bigint | number | null;
  readonly closeoutChecks: bigint | number | null;
  readonly expired: bigint | number | null;
  readonly oldestCloseoutAt: Date | null;
  readonly paymentChecks: bigint | number | null;
  readonly pricingChecks: bigint | number | null;
  readonly refundReview: bigint | number | null;
  readonly totalRecords: bigint | number | null;
};

type AdminBookingOperationPageCountRow = {
  readonly totalRows: bigint | number | null;
};

type AdminBookingOperationPageIdRow = {
  readonly id: string;
};

type AdminBookingOperationPageAgeRow = {
  readonly all: bigint | number | null;
  readonly underOneHour: bigint | number | null;
  readonly oneToFourHours: bigint | number | null;
  readonly fourToTwentyFourHours: bigint | number | null;
  readonly overTwentyFourHours: bigint | number | null;
};

type AdminBookingOperationPageOverdueRow = {
  readonly overdueCount: bigint | number | null;
};

type AdminBookingOperationPageQuery = {
  readonly condition: Prisma.Sql;
  readonly factsCte: Prisma.Sql;
  readonly factsTable: Prisma.Sql;
  readonly includePostMatchCancellationDecisionAt?: boolean;
  readonly occurredAt: Prisma.Sql;
  readonly slaPolicy?: AdminBookingQueueSlaPolicy;
  readonly sla: string | null | undefined;
  readonly sort: string | null | undefined;
};

type AdminBookingQueueSlaPolicy = {
  readonly defaultThresholdMinutes: number;
  readonly key: string;
};

type AdminPostMatchCancellationOperationsSummaryRow = {
  readonly adminApprovedCount: bigint | number | null;
  readonly adminHeldCount: bigint | number | null;
  readonly autoResolvedCount: bigint | number | null;
  readonly needsDecisionCount: bigint | number | null;
  readonly noShowReviewCount: bigint | number | null;
  readonly overdueOpenCount: bigint | number | null;
  readonly resolvedCount: bigint | number | null;
  readonly unknownLegacyCount: bigint | number | null;
};

function adminBookingOperationPageQuery(query: AdminBookingListQuery): AdminBookingOperationPageQuery | null {
  const statusGroup = query.statusGroup;
  if (statusGroup && COMPLETED_BOOKING_OPERATION_STATUS_GROUPS.has(statusGroup)) {
    return {
      condition: adminCompletedBookingOperationCondition(statusGroup),
      factsCte: adminCompletedBookingFactsCte(query),
      factsTable: Prisma.sql`"bookingFacts" facts`,
      occurredAt: Prisma.sql`facts."terminalAt"`,
      sla: query.sla,
      sort: query.sort ?? (statusGroup === 'completed' ? 'newest' : 'oldest'),
    };
  }
  if (statusGroup && POST_MATCH_CANCELLATION_OPERATION_STATUS_GROUPS.has(statusGroup)) {
    return {
      condition: adminPostMatchCancellationOperationCondition(statusGroup),
      factsCte: adminPostMatchCancellationFactsCte(query),
      factsTable: Prisma.sql`"cancellationFacts" facts`,
      includePostMatchCancellationDecisionAt: statusGroup === 'post-match-cancellations',
      occurredAt: Prisma.sql`facts."decisionAt"`,
      ...(statusGroup === 'post-match-cancellations-review' ||
      statusGroup === 'post-match-cancellations-no-show'
        ? { slaPolicy: adminBookingQueueSlaPolicy(statusGroup) ?? undefined }
        : {}),
      sla: query.sla,
      sort: query.sort,
    };
  }
  return null;
}

function adminBookingQueueSlaPolicy(
  statusGroup: string | null | undefined,
): AdminBookingQueueSlaPolicy | null {
  if (statusGroup === 'matching-delays' || statusGroup === 'no-supply') {
    return {
      defaultThresholdMinutes: DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.matchingDelays,
      key: START_SHIFT_ACTION_SLA_POLICY_KEYS.matchingDelays,
    };
  }
  if (statusGroup === 'post-match-cancellations-review') {
    return {
      defaultThresholdMinutes: DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.cancellationReview,
      key: START_SHIFT_ACTION_SLA_POLICY_KEYS.cancellationReview,
    };
  }
  if (statusGroup === 'post-match-cancellations-no-show') {
    return {
      defaultThresholdMinutes: DEFAULT_START_SHIFT_ACTION_SLA_MINUTES.cancellationReview,
      key: START_SHIFT_ACTION_SLA_POLICY_KEYS.cancellationReview,
    };
  }
  return null;
}

const COMPLETED_BOOKING_OPERATION_STATUS_GROUPS = new Set([
  'completed',
  'completed-payment',
  'completed-cash-debt',
  'completed-closeout',
  'completed-pricing',
  'completed-refund',
  'completed-expired',
]);

const POST_MATCH_CANCELLATION_OPERATION_STATUS_GROUPS = new Set([
  'post-match-cancellations',
  'post-match-cancellations-review',
  'post-match-cancellations-no-show',
]);

function adminCompletedBookingFactsCte(query: AdminBookingListQuery) {
  const terminalAt = adminCompletedBookingTerminalAtSql();
  return Prisma.sql`
    "filteredBookings" AS (
      SELECT booking.*
      FROM "Booking" booking
      ${adminBookingOperationsSummaryWhere(
        query,
        [BookingStatus.COMPLETED, BookingStatus.EXPIRED, BookingStatus.REFUNDED],
        false,
        terminalAt,
      )}
    ),
    "bookingFacts" AS (
      SELECT
        booking.*,
        ${terminalAt} AS "terminalAt",
        payment.id AS "paymentId",
        payment.status AS "paymentStatus",
        payment.method AS "paymentMethod",
        payment."providerRef" AS "paymentProviderRef",
        earning.id AS "earningId",
        earning.status AS "earningStatus",
        earning."netAmount" AS "earningNetAmount",
        pricing."serviceId",
        pricing.price AS "bookedPrice",
        pricing."basePrice",
        pricing."priceStep",
        pricing."providerPayoutAmount",
        (
          booking.status = ${BookingStatus.COMPLETED}::"BookingStatus"
          AND (
            payment.id IS NULL
            OR payment.status <> ${PaymentStatus.CAPTURED}::"PaymentStatus"
            OR earning.id IS NULL
            OR NOT EXISTS (
              SELECT 1 FROM "ProviderPlatformFeeLog" fee
              WHERE fee."earningId" = earning.id
            )
            OR NOT EXISTS (
              SELECT 1 FROM "ProviderTaxLog" tax
              WHERE tax."earningId" = earning.id
            )
            OR NOT EXISTS (
              SELECT 1 FROM "ProviderWalletLedgerEntry" wallet
              WHERE wallet."earningId" = earning.id
            )
          )
        ) AS "closeoutNeedsOps"
      FROM "filteredBookings" booking
      LEFT JOIN "Payment" payment ON payment."bookingId" = booking.id
      LEFT JOIN "ProviderEarning" earning ON earning."bookingId" = booking.id
      LEFT JOIN LATERAL (
        SELECT
          service.id AS "serviceId",
          booking_service.price,
          service."basePrice",
          service."priceStep",
          payout."providerPayoutAmount"
        FROM "BookingService" booking_service
        LEFT JOIN "MassageService" service ON service.id = booking_service."serviceId"
        LEFT JOIN LATERAL (
          SELECT payout_rule."providerPayoutAmount"
          FROM "ServicePayoutRule" payout_rule
          WHERE payout_rule."serviceId" = service.id
            AND payout_rule.active = TRUE
            AND payout_rule."customerPrice" = booking_service.price
          ORDER BY payout_rule.id
          LIMIT 1
        ) payout ON TRUE
        WHERE booking_service."bookingId" = booking.id
        ORDER BY booking_service.id
        LIMIT 1
      ) pricing ON TRUE
    )
  `;
}

function adminPostMatchCancellationFactsCte(query: AdminBookingListQuery) {
  const decisionAt = Prisma.sql`COALESCE(booking."closedAt", booking."updatedAt", booking."createdAt")`;
  return Prisma.sql`
    "filteredBookings" AS (
      SELECT booking.*
      FROM "Booking" booking
      ${adminBookingOperationsSummaryWhere(
        query,
        [BookingStatus.CANCELLED, BookingStatus.NO_SHOW],
        true,
        decisionAt,
      )}
    ),
    "cancellationSourceFacts" AS (
      SELECT
        booking.*,
        ${decisionAt} AS "decisionAt",
        earning.id AS "earningId",
        earning.status AS "earningStatus",
        earning."netAmount" AS "earningNetAmount",
        CASE
          WHEN LOWER(COALESCE(booking.metadata #>> '{postMatchCancellation,autoApproved}', 'false')) = 'true'
            THEN 'auto-resolved'
          WHEN booking."closedByRole" = ${Role.ADMIN}::"Role"
            AND booking."closedReason" = ${POST_MATCH_CANCELLATION_APPROVED_REASON}
            THEN 'admin-approved'
          WHEN booking."closedByRole" = ${Role.ADMIN}::"Role"
            AND booking."closedReason" = ${POST_MATCH_CANCELLATION_HELD_REASON}
            THEN 'admin-held'
          WHEN booking."closedReason" IN (
              ${POST_MATCH_CANCELLATION_APPROVED_REASON},
              ${POST_MATCH_CANCELLATION_HELD_REASON}
            )
            OR earning.status = ${EarningStatus.CANCELLED}::"EarningStatus"
            OR earning."netAmount" = 0
            THEN 'legacy'
          ELSE 'open'
        END AS "decisionSource"
      FROM "filteredBookings" booking
      LEFT JOIN "ProviderEarning" earning ON earning."bookingId" = booking.id
    ),
    "cancellationFacts" AS (
      SELECT
        source_facts.*,
        CASE
          WHEN source_facts."decisionSource" IN ('auto-resolved', 'admin-approved') THEN 'approved'
          WHEN source_facts."decisionSource" = 'admin-held' THEN 'held'
          WHEN source_facts."decisionSource" = 'legacy' THEN 'legacy'
          ELSE 'pending'
        END AS resolution
      FROM "cancellationSourceFacts" source_facts
    )
  `;
}

function adminCompletedBookingOperationCondition(statusGroup: string): Prisma.Sql {
  switch (statusGroup) {
    case 'completed-payment':
      return Prisma.sql`
        facts."paymentId" IS NOT NULL
        AND (
          (
            facts.status = ${BookingStatus.EXPIRED}::"BookingStatus"
            AND facts."paymentStatus" NOT IN (
              ${PaymentStatus.RELEASED}::"PaymentStatus",
              ${PaymentStatus.REFUNDED}::"PaymentStatus"
            )
          )
          OR (
            facts.status = ${BookingStatus.COMPLETED}::"BookingStatus"
            AND (
              facts."paymentStatus" = ${PaymentStatus.AUTHORIZED}::"PaymentStatus"
              OR facts."closeoutNeedsOps"
            )
          )
          OR (
            facts."paymentStatus" = ${PaymentStatus.AUTHORIZED}::"PaymentStatus"
            AND facts."paymentProviderRef" IS NULL
          )
          OR (
            facts."paymentMethod" = ${PaymentMethod.CASH}::"PaymentMethod"
            AND facts."paymentStatus" = ${PaymentStatus.PENDING}::"PaymentStatus"
          )
          OR (${adminCompletedBookingOperationCondition('completed-cash-debt')})
        )
      `;
    case 'completed-cash-debt':
      return Prisma.sql`
        facts."paymentMethod" = ${PaymentMethod.CASH}::"PaymentMethod"
        AND facts."earningId" IS NOT NULL
        AND facts."earningNetAmount" < 0
        AND facts."earningStatus" <> ${EarningStatus.PAID}::"EarningStatus"
      `;
    case 'completed-closeout':
      return Prisma.sql`facts."closeoutNeedsOps"`;
    case 'completed-pricing':
      return Prisma.sql`
        facts.status = ${BookingStatus.COMPLETED}::"BookingStatus"
        AND (
          facts."serviceId" IS NULL
          OR facts."bookedPrice" IS NULL
          OR facts."bookedPrice" < facts."basePrice"
          OR facts."priceStep" <= 0
          OR MOD(facts."bookedPrice", NULLIF(facts."priceStep", 0)) <> 0
          OR facts."providerPayoutAmount" IS NULL
          OR facts."providerPayoutAmount" >= facts."bookedPrice"
        )
      `;
    case 'completed-refund':
      return Prisma.sql`
        (
          EXISTS (
            SELECT 1 FROM "Refund" refund
            WHERE refund."bookingId" = facts.id
          )
          AND facts."paymentStatus" IS DISTINCT FROM ${PaymentStatus.REFUNDED}::"PaymentStatus"
        )
        OR (
          facts.status = ${BookingStatus.EXPIRED}::"BookingStatus"
          AND facts."paymentId" IS NOT NULL
          AND facts."paymentStatus" NOT IN (
            ${PaymentStatus.RELEASED}::"PaymentStatus",
            ${PaymentStatus.REFUNDED}::"PaymentStatus"
          )
        )
      `;
    case 'completed-expired':
      return Prisma.sql`facts.status = ${BookingStatus.EXPIRED}::"BookingStatus"`;
    case 'completed':
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminPostMatchCancellationOperationCondition(statusGroup: string) {
  switch (statusGroup) {
    case 'post-match-cancellations-review':
      return Prisma.sql`facts."decisionSource" = 'open'`;
    case 'post-match-cancellations-no-show':
      return Prisma.sql`
        facts.status = ${BookingStatus.NO_SHOW}::"BookingStatus"
        AND facts."decisionSource" = 'open'
      `;
    case 'post-match-cancellations':
    default:
      return Prisma.sql`facts."decisionSource" <> 'open'`;
  }
}

function adminBookingOperationsSummaryWhere(
  query: AdminBookingListQuery,
  statuses: readonly BookingStatus[],
  requirePostMatchEvidence = false,
  occurredAt?: Prisma.Sql,
) {
  const statusValues = statuses.map((status) => Prisma.sql`${status}::"BookingStatus"`);
  const filters: Prisma.Sql[] = [
    Prisma.sql`booking.status IN (${Prisma.join(statusValues)})`,
    adminBookingProductionDataSql(),
  ];
  const dateCondition = occurredAt
    ? adminBookingOperationsSummaryDateColumnCondition(query, occurredAt)
    : adminBookingOperationsSummaryDateCondition(query);
  if (dateCondition) {
    filters.push(dateCondition);
  }
  const searchCondition = adminBookingOperationsSummarySearchCondition(query.q);
  if (searchCondition) {
    filters.push(searchCondition);
  }
  const ageWhere = adminQueueAgeDateWhere(query.age);
  const ageAt = occurredAt ?? Prisma.sql`booking."createdAt"`;
  if (ageWhere?.gte) {
    filters.push(Prisma.sql`${ageAt} >= ${ageWhere.gte}`);
  }
  if (ageWhere?.gt) {
    filters.push(Prisma.sql`${ageAt} > ${ageWhere.gt}`);
  }
  if (ageWhere?.lte) {
    filters.push(Prisma.sql`${ageAt} <= ${ageWhere.lte}`);
  }
  if (ageWhere?.lt) {
    filters.push(Prisma.sql`${ageAt} < ${ageWhere.lt}`);
  }
  if (requirePostMatchEvidence) {
    filters.push(Prisma.sql`(booking."matchedAt" IS NOT NULL OR booking."selectedProviderId" IS NOT NULL)`);
  }
  const cancellationReason = normalizeAdminPostMatchCancellationReason(query.cancellationReason);
  if (cancellationReason) {
    filters.push(
      cancellationReason === 'LEGACY'
        ? Prisma.sql`COALESCE(booking.metadata #>> '{postMatchCancellation,reasonCode}', '') NOT IN (${Prisma.join(
            ADMIN_POST_MATCH_CANCELLATION_REASON_CODES.map((code) => Prisma.sql`${code}`),
          )})`
        : Prisma.sql`booking.metadata #>> '{postMatchCancellation,reasonCode}' = ${cancellationReason}`,
    );
  }

  return Prisma.sql`WHERE ${Prisma.join(filters, ' AND ')}`;
}

function adminIdentifierProductionDataSql(identifier: Prisma.Sql) {
  return Prisma.sql`
    LOWER(${identifier}) NOT LIKE 'smoke%'
    AND LOWER(${identifier}) NOT LIKE 'seed-%'
    AND LOWER(${identifier}) NOT LIKE 'audit\\_%' ESCAPE '\\'
  `;
}

function operationsHandoffSerializationConflict(error: unknown) {
  return (
    error instanceof Prisma.PrismaClientKnownRequestError &&
    (error.code === 'P2034' || (error.code === 'P2010' && error.meta?.code === '40001'))
  );
}

function adminCustomerProductionDataWhere(): Prisma.CustomerProfileWhereInput {
  return {
    NOT: {
      OR: ['smoke', 'seed-', 'audit_'].flatMap((prefix) => [
        { id: { startsWith: prefix, mode: Prisma.QueryMode.insensitive } },
        { userId: { startsWith: prefix, mode: Prisma.QueryMode.insensitive } },
      ]),
    },
    user: {
      is: {
        fixtureExpiresAt: null,
        fixtureKind: null,
        fixtureRunId: null,
        OR: [
          { fullName: null },
          {
            NOT: {
              OR: ['smoke', 'demo'].map((prefix) => ({
                fullName: { startsWith: prefix, mode: Prisma.QueryMode.insensitive },
              })),
            },
          },
        ],
      },
    },
  };
}

function adminProviderProductionDataWhere(): Prisma.ProviderProfileWhereInput {
  return {
    NOT: {
      OR: [
        ...['smoke', 'seed-', 'audit_'].flatMap((prefix) => [
          { id: { startsWith: prefix, mode: Prisma.QueryMode.insensitive } },
          { userId: { startsWith: prefix, mode: Prisma.QueryMode.insensitive } },
        ]),
        ...['smoke', 'demo'].map((prefix) => ({
          displayName: { startsWith: prefix, mode: Prisma.QueryMode.insensitive },
        })),
      ],
    },
    user: {
      is: {
        fixtureExpiresAt: null,
        fixtureKind: null,
        fixtureRunId: null,
        OR: [
          { fullName: null },
          {
            NOT: {
              OR: ['smoke', 'demo'].map((prefix) => ({
                fullName: { startsWith: prefix, mode: Prisma.QueryMode.insensitive },
              })),
            },
          },
        ],
      },
    },
  };
}

function adminVietnamOverviewOperatingProviderWhere(): Prisma.ProviderProfileWhereInput {
  return {
    AND: [adminProviderProductionDataWhere(), { blockedAt: null, deletedAt: null }],
  };
}

function adminCustomerProductionDataSql(customer = Prisma.sql`customer`) {
  return adminProfileProductionDataSql(customer);
}

function adminProviderProductionDataSql(provider = Prisma.sql`provider`) {
  return Prisma.sql`
    ${adminProfileProductionDataSql(provider)}
    AND LOWER(COALESCE(${provider}."displayName", '')) NOT LIKE 'smoke%'
    AND LOWER(COALESCE(${provider}."displayName", '')) NOT LIKE 'demo%'
  `;
}

function adminProfileProductionDataSql(profile: Prisma.Sql) {
  return Prisma.sql`
    ${adminIdentifierProductionDataSql(Prisma.sql`${profile}.id`)}
    AND ${adminIdentifierProductionDataSql(Prisma.sql`${profile}."userId"`)}
    AND NOT EXISTS (
      SELECT 1
      FROM "User" profile_user
      WHERE profile_user.id = ${profile}."userId"
        AND (
          profile_user."fixtureKind" IS NOT NULL
          OR profile_user."fixtureRunId" IS NOT NULL
          OR profile_user."fixtureExpiresAt" IS NOT NULL
          OR LOWER(COALESCE(profile_user."fullName", '')) LIKE 'smoke%'
          OR LOWER(COALESCE(profile_user."fullName", '')) LIKE 'demo%'
        )
    )
  `;
}

function adminBookingOperationsSummaryDateCondition(query: AdminBookingListQuery) {
  const bounds = adminBookingListDateBounds(query);
  if (!bounds) {
    return null;
  }
  const columns = [
    Prisma.sql`booking."openedAt"`,
    Prisma.sql`booking."createdAt"`,
    Prisma.sql`booking."updatedAt"`,
    Prisma.sql`booking."matchedAt"`,
    Prisma.sql`booking."closedAt"`,
    Prisma.sql`booking."expiresAt"`,
  ];
  const conditions = columns.map((column) => {
    const hasStart = Number.isFinite(bounds.startMs);
    const hasEnd = Number.isFinite(bounds.endMs);
    if (hasStart && hasEnd) {
      return Prisma.sql`${column} BETWEEN ${new Date(bounds.startMs)} AND ${new Date(bounds.endMs)}`;
    }
    if (hasStart) {
      return Prisma.sql`${column} >= ${new Date(bounds.startMs)}`;
    }
    return Prisma.sql`${column} <= ${new Date(bounds.endMs)}`;
  });

  return Prisma.sql`(${Prisma.join(conditions, ' OR ')})`;
}

function adminBookingOperationsSummaryDateColumnCondition(query: AdminBookingListQuery, column: Prisma.Sql) {
  const bounds = adminBookingListDateBounds(query);
  if (!bounds) return null;
  if (Number.isFinite(bounds.startMs) && Number.isFinite(bounds.endMs)) {
    return Prisma.sql`${column} BETWEEN ${new Date(bounds.startMs)} AND ${new Date(bounds.endMs)}`;
  }
  return Number.isFinite(bounds.startMs)
    ? Prisma.sql`${column} >= ${new Date(bounds.startMs)}`
    : Prisma.sql`${column} <= ${new Date(bounds.endMs)}`;
}

function adminCompletedBookingTerminalAtSql(booking = Prisma.sql`booking`) {
  return Prisma.sql`
    CASE
      WHEN ${booking}.status = ${BookingStatus.EXPIRED}::"BookingStatus"
        THEN COALESCE(${booking}."closedAt", ${booking}."expiresAt", ${booking}."updatedAt", ${booking}."createdAt")
      ELSE COALESCE(${booking}."closedAt", ${booking}."updatedAt", ${booking}."createdAt")
    END
  `;
}

function adminBookingOperationsSummarySearchCondition(value?: string | null) {
  const query = value?.trim();
  if (!query) {
    return null;
  }

  return Prisma.sql`(
    POSITION(LOWER(${query}) IN LOWER(booking.id)) > 0
    OR POSITION(LOWER(${query}) IN LOWER(booking."customerProfileId")) > 0
    OR POSITION(LOWER(${query}) IN LOWER(COALESCE(booking."preferredProviderId", ''))) > 0
    OR POSITION(LOWER(${query}) IN LOWER(COALESCE(booking."selectedProviderId", ''))) > 0
    OR EXISTS (
      SELECT 1
      FROM "CustomerProfile" customer
      JOIN "User" customer_user ON customer_user.id = customer."userId"
      WHERE customer.id = booking."customerProfileId"
        AND (
          POSITION(LOWER(${query}) IN LOWER(COALESCE(customer_user."fullName", ''))) > 0
          OR POSITION(LOWER(${query}) IN LOWER(customer_user.phone)) > 0
        )
    )
    OR EXISTS (
      SELECT 1
      FROM "ProviderProfile" provider
      JOIN "User" provider_user ON provider_user.id = provider."userId"
      WHERE provider.id IN (booking."preferredProviderId", booking."selectedProviderId")
        AND (
          POSITION(LOWER(${query}) IN LOWER(COALESCE(provider."displayName", ''))) > 0
          OR POSITION(LOWER(${query}) IN LOWER(COALESCE(provider_user."fullName", ''))) > 0
          OR POSITION(LOWER(${query}) IN LOWER(provider_user.phone)) > 0
        )
    )
    OR EXISTS (
      SELECT 1
      FROM "BookingAddressSnapshot" address
      WHERE address."bookingId" = booking.id
        AND POSITION(LOWER(${query}) IN LOWER(COALESCE(address."addressText", ''))) > 0
    )
  )`;
}

function integerValue(value: unknown) {
  return Math.trunc(numberValue(value));
}

const MANUAL_WALLET_ADJUSTMENT_TYPES = new Set<ManualWalletAdjustmentType>([
  'PROMOTION_CREDIT',
  'CUSTOMER_COMPENSATION',
  'PARTNER_BONUS',
  'REFERRAL_CORRECTION',
  'ERROR_CORRECTION',
  'PENALTY',
  'CASH_BOOKING_DEDUCTION',
  'RECEIVABLE_WRITE_OFF',
  'MANUAL_REVERSAL',
]);

function manualWalletAdjustmentOwnerType(value: string): ManualWalletAdjustmentOwnerType {
  if (value === 'CUSTOMER' || value === 'PARTNER') {
    return value;
  }
  throw new BadRequestException('Manual wallet adjustment owner type is invalid');
}

function manualWalletAdjustmentDirection(value: string): ManualWalletAdjustmentDirection {
  if (value === 'CREDIT' || value === 'DEBIT') {
    return value;
  }
  throw new BadRequestException('Manual wallet adjustment direction is invalid');
}

function manualWalletAdjustmentType(value: string): ManualWalletAdjustmentType {
  if (MANUAL_WALLET_ADJUSTMENT_TYPES.has(value as ManualWalletAdjustmentType)) {
    return value as ManualWalletAdjustmentType;
  }
  throw new BadRequestException('Manual wallet adjustment type is invalid');
}

function manualWalletAdjustmentBadRequest(error: unknown) {
  if (error instanceof ManualWalletAdjustmentPolicyError) {
    return new BadRequestException({ code: error.code, message: error.message });
  }
  if (error instanceof BadRequestException) return error;
  return new BadRequestException(
    error instanceof Error ? error.message : 'Manual wallet adjustment is invalid',
  );
}

function normalizeManualWalletOwnerId(value: string) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    throw new BadRequestException('Wallet owner id is required');
  }
  return normalized;
}

function normalizeManualWalletAdjustmentIdempotencyKey(value: string) {
  const normalized = normalizeNullable(value);
  if (!normalized || normalized.length > 128) {
    throw new BadRequestException('Manual wallet adjustment idempotency key is invalid');
  }
  return normalized;
}

function normalizeManualWalletCurrency(value?: string | null) {
  const normalized = normalizeNullable(value) ?? 'VND';
  if (normalized !== 'VND') {
    throw new BadRequestException('Manual wallet adjustments currently support VND only');
  }
  return normalized;
}

function normalizeManualWalletMonthlyPeriod(value?: string | null) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return null;
  }
  const match = /^(\d{4})-(\d{2})$/.exec(normalized);
  if (!match) {
    throw new BadRequestException('Monthly period must use YYYY-MM with month 01-12');
  }
  const month = Number(match[2]);
  if (month < 1 || month > 12) {
    throw new BadRequestException('Monthly period must use YYYY-MM with month 01-12');
  }
  return normalized;
}

function normalizeManualWalletAdjustmentReason(value: string) {
  const reason = normalizeAuditReason(value);
  if (reason.length < 12) {
    throw new BadRequestException('Manual wallet adjustment reason must be at least 12 characters.');
  }
  return reason;
}

function normalizeManualWalletApprovalId(value: string | undefined, requireApproval: boolean) {
  const normalized = normalizeNullable(value);
  if (requireApproval && !normalized) {
    throw new BadRequestException('Approval id is required for manual wallet adjustment');
  }
  return normalized ?? 'PREVIEW_ONLY';
}

function normalizeManualWalletApprovalAdminId(
  value: string | undefined,
  actorId: string,
  requireApproval: boolean,
) {
  const normalized = normalizeNullable(value);
  if (requireApproval && !normalized) {
    throw new BadRequestException('Approving admin id is required for manual wallet adjustment');
  }
  if (normalized && normalized === actorId) {
    throw new BadRequestException('Manual wallet adjustment requires approval from a different admin');
  }
  return normalized;
}

function assertLegacyManualWalletAdjustmentRequestMatches(
  request: {
    ownerType: string;
    ownerId: string;
    direction: string;
    adjustmentType: string;
    amount: number;
    currency: string;
    reason: string;
    operationalCause: string | null;
    expectedCorrection: string | null;
    caseReference: string | null;
    monthlyPeriod: string | null;
    attachmentFileId: string | null;
    attachmentUrl: string | null;
  },
  input: CreateManualWalletAdjustmentDto,
) {
  if (!manualWalletAdjustmentRequestPayloadMatches(request, input)) {
    throw new ConflictException(
      'Legacy manual wallet adjustment payload does not match the persisted approval request',
    );
  }
}

function manualWalletAdjustmentRequestPayloadMatches(
  request: {
    ownerType: string;
    ownerId: string;
    direction: string;
    adjustmentType: string;
    amount: number;
    currency: string;
    reason: string;
    operationalCause: string | null;
    expectedCorrection: string | null;
    caseReference: string | null;
    monthlyPeriod: string | null;
    attachmentFileId: string | null;
    attachmentUrl: string | null;
  },
  input: CreateManualWalletAdjustmentDto | CreateManualWalletAdjustmentRequestDto,
) {
  return (
    request.ownerType === manualWalletAdjustmentOwnerType(input.ownerType) &&
    request.ownerId === normalizeManualWalletOwnerId(input.ownerId) &&
    request.direction === manualWalletAdjustmentDirection(input.direction) &&
    request.adjustmentType === manualWalletAdjustmentType(input.adjustmentType) &&
    request.amount === integerValue(input.amount) &&
    request.currency === normalizeManualWalletCurrency(input.currency) &&
    request.reason === normalizeManualWalletAdjustmentReason(input.reason) &&
    request.operationalCause === normalizeNullable(input.operationalCause) &&
    request.expectedCorrection === normalizeNullable(input.expectedCorrection) &&
    request.caseReference === normalizeNullable(input.caseReference) &&
    request.monthlyPeriod === normalizeManualWalletMonthlyPeriod(input.monthlyPeriod) &&
    request.attachmentFileId === normalizeNullable(input.attachmentFileId) &&
    request.attachmentUrl === normalizeManualWalletAttachmentUrl(input.attachmentUrl)
  );
}

function assertIdempotentManualWalletAdjustmentRequestMatches(
  request: Parameters<typeof manualWalletAdjustmentRequestPayloadMatches>[0] & {
    requestedByAdminId: string;
  },
  actorId: string,
  input: CreateManualWalletAdjustmentRequestDto,
) {
  if (
    request.requestedByAdminId !== actorId ||
    !manualWalletAdjustmentRequestPayloadMatches(request, input)
  ) {
    throw new ConflictException(
      'Manual wallet adjustment idempotency key was already used for another request',
    );
  }
}

function partnerBankDepositLedgerSourceKey(providerProfileId: string, bankTransactionId: string) {
  return `partner-bank-deposit:${providerProfileId}:${bankTransactionId}`;
}

function partnerBankDepositAccountingPreview(allocation: ReturnType<typeof allocatePartnerBankDeposit>) {
  return [
    {
      side: AccountingJournalEntrySide.DEBIT,
      accountCode: 'company_bank_cash',
      accountName: 'Company bank cash',
      amount: allocation.depositAmount,
    },
    ...(allocation.amountAppliedToNegativeWallet > 0
      ? [
          {
            side: AccountingJournalEntrySide.CREDIT,
            accountCode: 'partner_receivable',
            accountName: 'Partner receivable',
            amount: allocation.amountAppliedToNegativeWallet,
          },
        ]
      : []),
    ...(allocation.amountCreditedToWalletLiability > 0
      ? [
          {
            side: AccountingJournalEntrySide.CREDIT,
            accountCode: 'partner_wallet_liability',
            accountName: 'Partner wallet liability',
            amount: allocation.amountCreditedToWalletLiability,
          },
        ]
      : []),
  ];
}

function assertLegacyPartnerBankDepositRequestMatches(
  request: {
    providerProfileId: string;
    amount: number;
    bankTransactionId: string;
    depositDate: Date;
    bankAccount: string | null;
    attachmentFileId: string | null;
    attachmentUrl: string | null;
    notes: string | null;
  },
  input: RecordPartnerBankDepositDto,
  actorId: string,
) {
  const deposit = normalizePartnerBankDepositInput({ ...input, adminId: actorId });
  const matches =
    request.providerProfileId === deposit.providerProfileId &&
    request.amount === deposit.amount &&
    request.bankTransactionId === deposit.bankTransactionId &&
    request.depositDate.getTime() === deposit.depositDate.getTime() &&
    request.bankAccount === (deposit.bankAccount ?? null) &&
    request.attachmentFileId === (deposit.attachmentFileId ?? null) &&
    request.attachmentUrl === (deposit.attachmentUrl ?? null) &&
    request.notes === (deposit.notes ?? null);

  if (!matches) {
    throw new ConflictException(
      'Legacy partner bank deposit payload does not match the persisted approval request',
    );
  }
}

function normalizePartnerBankDepositRequestStatus(value?: string | null) {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) {
    return null;
  }
  if (
    Object.values(PartnerBankDepositRequestStatus).includes(normalized as PartnerBankDepositRequestStatus)
  ) {
    return normalized as PartnerBankDepositRequestStatus;
  }
  throw new BadRequestException('Partner bank deposit request status is invalid');
}

function normalizePartnerBankDepositReview(value?: string | null) {
  const normalized = normalizeNullable(value)?.toLowerCase();
  if (!normalized || normalized === 'all') {
    return 'all' as const;
  }
  if (normalized === 'needs-reconciliation') {
    return normalized;
  }
  throw new BadRequestException('Partner bank deposit review filter is invalid');
}

function normalizePartnerBankDepositReconciliationOwner(value?: string | null): 'all' | 'unassigned' {
  const normalized = normalizeNullable(value)?.toLowerCase();
  if (!normalized || normalized === 'all') return 'all' as const;
  if (normalized === 'unassigned') return normalized;
  throw new BadRequestException('Partner bank deposit reconciliation owner filter is invalid');
}

function normalizePartnerBankDepositReconciliationSla(
  value?: string | null,
): 'all' | 'within-24h' | 'over-24h' | 'escalate' {
  const normalized = normalizeNullable(value)?.toLowerCase();
  if (!normalized || normalized === 'all') return 'all' as const;
  if (normalized === 'within-24h' || normalized === 'over-24h' || normalized === 'escalate') {
    return normalized;
  }
  throw new BadRequestException('Partner bank deposit reconciliation SLA filter is invalid');
}

function normalizePartnerBankDepositReconciliationPeriod(value?: string | null) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return null;
  }
  if (/^\d{4}-(0[1-9]|1[0-2])$/.test(normalized)) {
    return normalized;
  }
  throw new BadRequestException('Partner bank deposit reconciliation period must use YYYY-MM');
}

function partnerBankDepositReconciliationState(
  request: Pick<
    AdminPartnerBankDepositHistoryRow,
    'amount' | 'createdAt' | 'executedAt' | 'journalBatchId' | 'status'
  >,
  reconciliationByBatchId: ReadonlyMap<string, { matchedAmount: number; remainingAmount: number }>,
) {
  if (request.status !== PartnerBankDepositRequestStatus.EXECUTED) {
    return {
      reconciliationMatchedAmount: 0,
      reconciliationRemainingAmount: 0,
      reconciliationSlaStatus: 'NOT_APPLICABLE' as const,
      reconciliationStatus: 'NOT_APPLICABLE' as const,
      reconciliationWaitingHours: null,
    };
  }

  const evidence = request.journalBatchId ? reconciliationByBatchId.get(request.journalBatchId) : null;
  const matchedAmount = evidence?.matchedAmount ?? 0;
  const remainingAmount = evidence?.remainingAmount ?? request.amount;
  const waitingSince = request.executedAt ?? request.createdAt;
  const reconciliationWaitingHours =
    remainingAmount > 0 ? Math.max(0, Math.floor((Date.now() - waitingSince.getTime()) / 3_600_000)) : null;
  return {
    reconciliationMatchedAmount: matchedAmount,
    reconciliationRemainingAmount: remainingAmount,
    reconciliationSlaStatus:
      remainingAmount === 0
        ? ('RECONCILED' as const)
        : (reconciliationWaitingHours ?? 0) >= 48
          ? ('ESCALATE' as const)
          : (reconciliationWaitingHours ?? 0) >= 24
            ? ('OVER_24H' as const)
            : ('WITHIN_24H' as const),
    reconciliationStatus:
      remainingAmount === 0
        ? ('MATCHED' as const)
        : matchedAmount > 0
          ? ('PARTIALLY_MATCHED' as const)
          : ('UNMATCHED' as const),
    reconciliationWaitingHours,
  };
}

function assertPartnerBankDepositRequestPending(status: PartnerBankDepositRequestStatus) {
  if (status !== PartnerBankDepositRequestStatus.REQUESTED) {
    throw new ConflictException('Partner bank deposit request is no longer pending');
  }
}

function partnerBankDepositAllocationFromLedger(
  metadata: Prisma.JsonValue | null,
  depositAmount: number,
): ReturnType<typeof allocatePartnerBankDeposit> {
  const allocation = adminJsonObject(adminJsonObject(metadata)?.allocation);
  const currentWalletBalance = integerJsonValue(allocation?.currentWalletBalance);
  const currentNegativeWalletAmount = integerJsonValue(allocation?.currentNegativeWalletAmount);
  const amountAppliedToNegativeWallet = integerJsonValue(allocation?.amountAppliedToNegativeWallet);
  const amountCreditedToWalletLiability = integerJsonValue(allocation?.amountCreditedToWalletLiability);
  const resultingWalletBalance = integerJsonValue(allocation?.resultingWalletBalance);
  const recordedDepositAmount = integerJsonValue(allocation?.depositAmount);

  if (
    recordedDepositAmount !== depositAmount ||
    currentWalletBalance === null ||
    currentNegativeWalletAmount === null ||
    amountAppliedToNegativeWallet === null ||
    amountCreditedToWalletLiability === null ||
    resultingWalletBalance === null ||
    amountAppliedToNegativeWallet + amountCreditedToWalletLiability !== depositAmount ||
    currentWalletBalance + depositAmount !== resultingWalletBalance
  ) {
    throw new ConflictException('Partner bank deposit allocation evidence is incomplete');
  }

  return {
    depositAmount: recordedDepositAmount,
    currentWalletBalance,
    currentNegativeWalletAmount,
    amountAppliedToNegativeWallet,
    amountCreditedToWalletLiability,
    resultingWalletBalance,
  };
}

function integerJsonValue(value: unknown) {
  return typeof value === 'number' && Number.isInteger(value) ? value : null;
}

async function upsertPartnerBankDepositJournal(
  tx: Pick<Prisma.TransactionClient, 'accountingJournalBatch'>,
  input: {
    actorId: string;
    allocation: ReturnType<typeof allocatePartnerBankDeposit>;
    approvalChannel: 'LEGACY_COMPAT' | 'REQUEST_APPROVAL';
    bankTransactionId: string;
    currency: string;
    depositDate: Date;
    ledgerId: string;
    providerProfileId: string;
    requestId: string;
    requestedByAdminId: string;
  },
) {
  const sourceKey = `accounting-journal:provider-bank-deposit:${input.providerProfileId}:${input.bankTransactionId}`;
  const sourceType = AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT;
  const metadata = toJson({
    partnerBankDeposit: true,
    partnerBankDepositRequestId: input.requestId,
    providerProfileId: input.providerProfileId,
    bankTransactionId: input.bankTransactionId,
    requestedByAdminId: input.requestedByAdminId,
    approvedByAdminId: input.actorId,
    approvalChannel: input.approvalChannel,
    ledgerId: input.ledgerId,
    allocation: input.allocation,
  });
  const entries = partnerBankDepositAccountingPreview(input.allocation).map((entry) => ({
    ...entry,
    currency: input.currency,
    memo: `Partner bank deposit ${input.bankTransactionId}`,
    metadata,
    sourceId: input.ledgerId,
    sourceType,
  }));
  const batchData = {
    createdById: input.actorId,
    currency: input.currency,
    entries: { create: entries },
    metadata,
    monthlyPeriod: settlementMonthlyPeriod(input.depositDate),
    providerProfileId: input.providerProfileId,
    sourceId: input.ledgerId,
    sourceType,
    status: AccountingJournalBatchStatus.POSTED,
    totalCredit: input.allocation.depositAmount,
    totalDebit: input.allocation.depositAmount,
  };

  return tx.accountingJournalBatch.upsert({
    where: { sourceKey },
    update: {},
    create: { ...batchData, sourceKey },
  });
}

function normalizeFinanceActionApprovalAdminId(
  value: string | null | undefined,
  actorId: string,
  actionLabel: string,
) {
  const normalized = normalizeNullable(value);
  if (!normalized || normalized === actorId) {
    throw new BadRequestException(`${actionLabel} requires approval from a different admin`);
  }
  return normalized;
}

function adminPaymentFeePolicyListTake(value: number | string | null | undefined) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return ADMIN_PAYMENT_FEE_POLICY_DEFAULT_LIMIT;
  }
  return Math.min(Math.trunc(parsed), ADMIN_PAYMENT_FEE_POLICY_MAX_LIMIT);
}

function adminPaymentFeePolicySampleAmount(value: number | string | null | undefined) {
  if (value === undefined || value === null || value === '') {
    return ADMIN_PAYMENT_FEE_POLICY_DEFAULT_SAMPLE_AMOUNT;
  }
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed <= 0 || parsed > ADMIN_PAYMENT_FEE_POLICY_MAX_SAMPLE_AMOUNT) {
    throw new BadRequestException(
      `Payment fee sample amount must be an integer between 1 and ${ADMIN_PAYMENT_FEE_POLICY_MAX_SAMPLE_AMOUNT}`,
    );
  }
  return parsed;
}

function normalizePaymentFeePolicyInput(input: {
  name: string;
  effectiveFrom: string;
  effectiveTo?: string | null;
  notes?: string | null;
}) {
  const name = input.name.trim();
  if (!name) {
    throw new BadRequestException('Payment fee policy name is required');
  }
  const effectiveFrom = new Date(input.effectiveFrom);
  const effectiveTo = input.effectiveTo ? new Date(input.effectiveTo) : null;
  if (Number.isNaN(effectiveFrom.getTime())) {
    throw new BadRequestException('Payment fee policy effective from is invalid');
  }
  if (effectiveTo && Number.isNaN(effectiveTo.getTime())) {
    throw new BadRequestException('Payment fee policy effective to is invalid');
  }
  if (effectiveTo && effectiveTo <= effectiveFrom) {
    throw new BadRequestException('Payment fee policy effective to must be after effective from');
  }
  return {
    name,
    effectiveFrom,
    effectiveTo,
    notes: normalizeNullable(input.notes),
  };
}

function paymentFeePolicyAuditSnapshot(policy: {
  effectiveFrom: Date;
  effectiveTo: Date | null;
  id: string;
  name: string;
  notes?: string | null;
  status: TaxPolicyStatus;
}) {
  return {
    effectiveFrom: policy.effectiveFrom.toISOString(),
    effectiveTo: policy.effectiveTo?.toISOString() ?? null,
    id: policy.id,
    name: policy.name,
    notes: policy.notes ?? null,
    status: policy.status,
  };
}

function paymentFeeRuleInput(input: {
  feeType: PaymentFeeRuleType;
  fixedAmount: number;
  method: PaymentMethod;
  payer: PaymentFeePayer;
  rateBps: number;
  treatment: PaymentFeeTreatment;
}) {
  return {
    feeType: input.feeType,
    fixedAmount: input.fixedAmount,
    method: input.method,
    payer: input.payer,
    rateBps: input.rateBps,
    treatment: input.treatment,
  };
}

function paymentFeeRuleAuditSnapshot(
  rule: ReturnType<typeof paymentFeeRuleInput> & { active: boolean; id: string },
) {
  return {
    active: rule.active,
    ...paymentFeeRuleInput(rule),
    id: rule.id,
  };
}

function assertPaymentFeeDraft(
  policy: { id: string; status: TaxPolicyStatus } | null,
  policyId: string,
): asserts policy is { id: string; status: 'DRAFT' } {
  if (!policy) {
    throw new NotFoundException(`Payment fee policy ${policyId} was not found`);
  }
  if (policy.status !== TaxPolicyStatus.DRAFT) {
    throw new BadRequestException('Only DRAFT payment fee policies can be changed');
  }
}

