export function adminFinanceApprovalRefundReview({
  actorCanApprove,
  actorId,
  paymentStatus,
  requestedByAdminId,
}: {
  readonly actorCanApprove: boolean;
  readonly actorId?: string;
  readonly paymentStatus: PaymentStatus;
  readonly requestedByAdminId: string | null;
}) {
  const stateMismatch = paymentStatus !== PaymentStatus.CAPTURED;
  const blockers: AdminFinanceApprovalPreflightBlocker[] = [];
  if (stateMismatch) {
    blockers.push({
      code: 'PAYMENT_STATE_MISMATCH',
      message: `Payment is ${paymentStatus}; only CAPTURED payments can be refunded. Open the payment timeline before taking action.`,
    });
  }
  if (!actorCanApprove) {
    blockers.push({
      code: 'FINANCE_APPROVER_REQUIRED',
      message: 'The signed-in operator does not have the FINANCE_APPROVER role.',
    });
  }
  if (requestedByAdminId === actorId) {
    blockers.push({
      code: 'MAKER_CANNOT_APPROVE',
      message: 'The operator who created this refund request cannot approve or reject it.',
    });
  }
  const reviewState = stateMismatch ? 'STATE_MISMATCH' : blockers.length ? 'BLOCKED' : 'READY';
  return {
    blockers,
    canApprove: reviewState === 'READY',
    canReject: reviewState !== 'STATE_MISMATCH' && actorCanApprove && requestedByAdminId !== actorId,
    reviewState,
  } as const;
}

