export function adminFinanceApprovalPayoutPage<
  T extends {
    readonly createdAt: Date | string;
    readonly id: string;
    readonly reviewState: 'BLOCKED' | 'READY';
  },
>(
  requests: readonly T[],
  review: AdminFinanceApprovalPayoutReview,
  skip: number,
  take: number,
  independentPriorityBuckets = false,
) {
  const oldestFirst = (rows: readonly T[]) =>
    [...rows].sort((left, right) => {
      const ageOrder = new Date(left.createdAt).getTime() - new Date(right.createdAt).getTime();
      return ageOrder || left.id.localeCompare(right.id);
    });
  const ready = oldestFirst(requests.filter((request) => request.reviewState === 'READY'));
  const blocked = oldestFirst(requests.filter((request) => request.reviewState === 'BLOCKED'));
  if (independentPriorityBuckets) return [...ready.slice(0, take), ...blocked.slice(0, take)];
  const filtered = review === 'ready' ? ready : review === 'blocked' ? blocked : [...ready, ...blocked];
  return filtered.slice(skip, skip + take);
}

function adminFinanceApprovalPage(value: number | string | null | undefined) {
  return adminBoundedPositiveInteger(value, 1, 400);
}

function adminFinanceApprovalRefundWhere(
  review: Exclude<AdminFinanceApprovalRefundReview, 'all'>,
  actorCanApprove: boolean,
  actorId?: string,
): Prisma.RefundWhereInput {
  const requestedByCurrentActor = actorId
    ? ({
        OR: [
          { metadata: { path: ['requestedByAdminId'], equals: actorId } },
          { metadata: { path: ['actorId'], equals: actorId } },
        ],
      } satisfies Prisma.RefundWhereInput)
    : null;
  const capturedPayment = { payment: { status: PaymentStatus.CAPTURED } } satisfies Prisma.RefundWhereInput;

  if (review === 'state-mismatch') {
    return { status: 'REQUESTED', payment: { status: { not: PaymentStatus.CAPTURED } } };
  }
  if (review === 'ready') {
    if (!actorCanApprove) return { id: { in: [] } };
    return {
      status: 'REQUESTED',
      AND: [capturedPayment, ...(requestedByCurrentActor ? [{ NOT: requestedByCurrentActor }] : [])],
    };
  }
  if (!actorCanApprove || !requestedByCurrentActor) {
    return { status: 'REQUESTED', ...capturedPayment };
  }
  return { status: 'REQUESTED', AND: [capturedPayment, requestedByCurrentActor] };
}

function adminFinanceApprovalQueueView(value: string | null | undefined): AdminFinanceApprovalQueueView {
  const normalized = normalizeNullable(value)?.toLowerCase();
  return normalized === 'bank-accounts' ||
    normalized === 'deposits' ||
    normalized === 'payouts' ||
    normalized === 'policies' ||
    normalized === 'refunds' ||
    normalized === 'wallet' ||
    normalized === 'withdrawals'
    ? normalized
    : 'priority';
}

function financeApprovalWalletReviewState(
  preflight: AdminFinanceApprovalRequestPreflight | undefined,
  fallback: AdminFinanceApprovalWalletReviewState,
): AdminFinanceApprovalWalletReviewState {
  if (!preflight) return fallback;
  if (preflight.blockers.some((blocker) => blocker.code === 'WALLET_BALANCE_CHANGED')) {
    return 'STALE';
  }
  return preflight.canApprove ? 'READY' : 'BLOCKED';
}

function adminFinanceApprovalPreflightErrorMessage(error: unknown) {
  if (error instanceof BadRequestException) {
    const response = error.getResponse();
    if (typeof response === 'string') return response;
    if (response && typeof response === 'object' && 'message' in response) {
      const message = response.message;
      if (typeof message === 'string') return message;
      if (Array.isArray(message))
        return message.filter((item): item is string => typeof item === 'string').join(' ');
    }
  }
  return error instanceof Error ? error.message : 'The persisted request no longer passes validation.';
}

