function normalizeManualWalletAdjustmentOwnerTypeFilter(value?: string | null) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return null;
  }
  return manualWalletAdjustmentOwnerType(normalized);
}

function normalizeManualWalletAdjustmentRequestStatus(value?: string | null) {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) {
    return null;
  }
  if (
    Object.values(ManualWalletAdjustmentRequestStatus).includes(
      normalized as ManualWalletAdjustmentRequestStatus,
    )
  ) {
    return normalized as ManualWalletAdjustmentRequestStatus;
  }
  throw new BadRequestException('Manual wallet adjustment request status is invalid');
}

function normalizeManualWalletAdjustmentRequestReview(value?: string | null) {
  const normalized = normalizeNullable(value)?.toLowerCase();
  return normalized === 'blocked' || normalized === 'recreation' || normalized === 'history'
    ? normalized
    : 'awaiting';
}

function normalizeManualWalletAdjustmentRequestSort(value?: string | null) {
  return normalizeNullable(value)?.toLowerCase() === 'newest' ? 'newest' : 'oldest';
}

function manualWalletAdjustmentRequestDecisionTime(request: {
  readonly createdAt: Date;
  readonly executedAt: Date | null;
  readonly rejectedAt: Date | null;
  readonly status: ManualWalletAdjustmentRequestStatus;
  readonly updatedAt: Date;
}) {
  const decidedAt =
    request.status === ManualWalletAdjustmentRequestStatus.EXECUTED
      ? request.executedAt
      : request.status === ManualWalletAdjustmentRequestStatus.REJECTED
        ? request.rejectedAt
        : request.updatedAt;
  return (decidedAt ?? request.updatedAt ?? request.createdAt).getTime();
}

function normalizeBooleanFilter(value?: string | null) {
  const normalized = normalizeNullable(value)?.toLowerCase();
  return normalized === '1' || normalized === 'true' || normalized === 'yes';
}

function normalizeEvidenceFilter(value?: string | null): 'attached' | 'missing' | null {
  const normalized = normalizeNullable(value)?.toLowerCase();
  return normalized === 'attached' || normalized === 'missing' ? normalized : null;
}

function manualWalletAdjustmentAmountRange(
  minimum?: number | string | null,
  maximum?: number | string | null,
): Prisma.IntFilter | undefined {
  const min = normalizeManualWalletAdjustmentFilterAmount(minimum, 'minimum');
  const max = normalizeManualWalletAdjustmentFilterAmount(maximum, 'maximum');
  if (min !== null && max !== null && min > max) {
    throw new BadRequestException('Minimum amount cannot exceed maximum amount');
  }
  return min === null && max === null
    ? undefined
    : { ...(min !== null ? { gte: min } : {}), ...(max !== null ? { lte: max } : {}) };
}

function normalizeManualWalletAdjustmentFilterAmount(
  value: number | string | null | undefined,
  label: string,
) {
  const normalized = normalizeNullable(value === null || value === undefined ? null : String(value));
  if (!normalized) return null;
  const parsed = Number(normalized);
  if (!Number.isSafeInteger(parsed) || parsed < 0) {
    throw new BadRequestException(`Wallet adjustment ${label} amount must be a non-negative integer`);
  }
  return parsed;
}

function manualWalletAdjustmentDateRange(
  from?: string | null,
  to?: string | null,
): Prisma.DateTimeFilter | undefined {
  const start = normalizeManualWalletAdjustmentFilterDate(from, 'from');
  const endDay = normalizeManualWalletAdjustmentFilterDate(to, 'to');
  const end = endDay ? new Date(endDay.getTime() + 86_400_000) : null;
  if (start && end && start >= end) {
    throw new BadRequestException('Wallet adjustment date range is invalid');
  }
  return start || end ? { ...(start ? { gte: start } : {}), ...(end ? { lt: end } : {}) } : undefined;
}

function normalizeManualWalletAdjustmentFilterDate(value: string | null | undefined, label: string) {
  const normalized = normalizeNullable(value);
  if (!normalized) return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
    throw new BadRequestException(`Wallet adjustment ${label} date must use YYYY-MM-DD`);
  }
  const parsed = new Date(`${normalized}T00:00:00.000Z`);
  if (!Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== normalized) {
    throw new BadRequestException(`Wallet adjustment ${label} date is invalid`);
  }
  return parsed;
}

const MANUAL_WALLET_ADJUSTMENT_RECREATION_BLOCKERS = new Set([
  'POLICY_MIGRATION_REQUIRED',
  'WALLET_ADJUSTMENT_PERIOD_NOT_FOUND',
  'WALLET_ADJUSTMENT_PERIOD_NOT_OPEN',
  'WALLET_ADJUSTMENT_PERIOD_REQUIRED',
  'WALLET_BALANCE_CHANGED',
]);

function manualWalletAdjustmentRequestNeedsRecreation(preflight?: AdminFinanceApprovalRequestPreflight) {
  return Boolean(
    preflight?.blockers.some((blocker) => MANUAL_WALLET_ADJUSTMENT_RECREATION_BLOCKERS.has(blocker.code)),
  );
}

function manualWalletAdjustmentRequestHasOperationalBlocker(
  preflight?: AdminFinanceApprovalRequestPreflight,
) {
  return Boolean(
    preflight?.blockers.some(
      (blocker) => blocker.code !== 'FINANCE_APPROVER_REQUIRED' && blocker.code !== 'MAKER_CANNOT_APPROVE',
    ),
  );
}

function assertManualWalletAdjustmentRequestPending(status: ManualWalletAdjustmentRequestStatus) {
  if (status !== ManualWalletAdjustmentRequestStatus.REQUESTED) {
    throw new ConflictException('Manual wallet adjustment request is no longer pending');
  }
}

