function compareOptionalIsoDateDesc(left: string | null, right: string | null) {
  return Date.parse(right ?? '1970-01-01T00:00:00.000Z') - Date.parse(left ?? '1970-01-01T00:00:00.000Z');
}

function compareOptionalIsoDateAsc(left: string | null, right: string | null) {
  return Date.parse(left ?? '1970-01-01T00:00:00.000Z') - Date.parse(right ?? '1970-01-01T00:00:00.000Z');
}

