function adminBookingSettlementAuditProjectionCteSql(
  options: AdminPaymentOperationsQuery,
  checkedAt: string,
) {
  return Prisma.sql`
    WITH "settlementAuditBase" AS NOT MATERIALIZED (
      SELECT
        snapshot.*,
        CASE
          WHEN COALESCE(snapshot."metadata"->>'companyCouponExpense', '') ~ '^-?[0-9]+$'
          THEN GREATEST(0, (snapshot."metadata"->>'companyCouponExpense')::bigint)
          ELSE 0::bigint
        END AS "companyCouponExpense",
        COALESCE(snapshot."metadata"->>'taxDueAt', snapshot."metadata"->>'taxDueDate') AS "taxDueText"
      FROM "BookingSettlementSnapshot" snapshot
      WHERE ${adminBookingSettlementAuditBaseWhereSql(options)}
    ),
    "settlementAuditFacts" AS NOT MATERIALIZED (
      SELECT
        base.*,
        (base."customerPaymentAmount"::bigint + base."companyCouponExpense"
          - base."partnerPayoutAmount"::bigint
          - base."partnerWithholdingTotal"::bigint
          - base."platformFeeGross"::bigint) AS "allocationDelta",
        CASE
          WHEN base."taxDueText" ~ '^\\d{4}-\\d{2}-\\d{2}(T.*(Z|[+-]\\d{2}:?\\d{2}))?$'
          THEN base."taxDueText"::timestamptz
          ELSE NULL
        END AS "taxDueAt",
        canonical_journal."count" AS "canonicalJournalCount",
        canonical_journal."issue" AS "canonicalJournalIssue",
        reversal_journal."count" AS "reversalJournalCount",
        reversal_journal."issue" AS "reversalJournalIssue",
        reversal_journal."hasCashLedger" AS "reversalHasCashLedger",
        reversal_journal."hasCustomerWalletLedger" AS "reversalHasCustomerWalletLedger",
        canonical_clearing."count" AS "canonicalClearingCount",
        canonical_clearing."issue" AS "canonicalClearingIssueRaw",
        canonical_clearing."matchedAmount" AS "canonicalMatchedAmount",
        reversal_clearing."count" AS "reversalClearingCount",
        reversal_clearing."issue" AS "reversalClearingIssueRaw",
        reversal_entry."count" AS "reversalEntryCount",
        wallet_refund."present" AS "walletRefundPresent"
      FROM "settlementAuditBase" base
      LEFT JOIN LATERAL (
        SELECT
          COUNT(*)::bigint AS "count",
          COALESCE(BOOL_OR(
            batch."status"::text <> 'POSTED'
            OR batch."totalDebit" <> batch."totalCredit"
            OR entries."entryCount" = 0
            OR entries."debit" <> batch."totalDebit"
            OR entries."credit" <> batch."totalCredit"
            OR entries."hasDelta"
          ), FALSE) AS "issue"
        FROM "AccountingJournalBatch" batch
        LEFT JOIN LATERAL (
          SELECT
            COUNT(*)::bigint AS "entryCount",
            COALESCE(SUM(entry."amount") FILTER (WHERE entry."side"::text = 'DEBIT'), 0)::bigint AS "debit",
            COALESCE(SUM(entry."amount") FILTER (WHERE entry."side"::text = 'CREDIT'), 0)::bigint AS "credit",
            COALESCE(BOOL_OR(entry."accountCode" = 'settlement_reconciliation_delta'), FALSE) AS "hasDelta"
          FROM "AccountingJournalEntry" entry
          WHERE entry."batchId" = batch."id"
        ) entries ON TRUE
        WHERE batch."settlementSnapshotId" = base."id"
          AND batch."sourceType"::text = 'BOOKING_SETTLEMENT'
      ) canonical_journal ON TRUE
      LEFT JOIN LATERAL (
        SELECT
          COUNT(*)::bigint AS "count",
          COALESCE(BOOL_OR(
            batch."status"::text <> 'POSTED'
            OR batch."totalDebit" <> batch."totalCredit"
            OR entries."entryCount" = 0
            OR entries."debit" <> batch."totalDebit"
            OR entries."credit" <> batch."totalCredit"
          ), FALSE) AS "issue",
          COALESCE(BOOL_OR(entries."hasCashLedger"), FALSE) AS "hasCashLedger",
          COALESCE(BOOL_OR(entries."hasCustomerWalletLedger"), FALSE) AS "hasCustomerWalletLedger"
        FROM "AccountingJournalBatch" batch
        LEFT JOIN LATERAL (
          SELECT
            COUNT(*)::bigint AS "entryCount",
            COALESCE(SUM(entry."amount") FILTER (WHERE entry."side"::text = 'DEBIT'), 0)::bigint AS "debit",
            COALESCE(SUM(entry."amount") FILTER (WHERE entry."side"::text = 'CREDIT'), 0)::bigint AS "credit",
            COALESCE(BOOL_OR(entry."accountCode" IN ('partner_receivable_negative_wallet', 'partner_wallet_liability')), FALSE) AS "hasCashLedger",
            COALESCE(BOOL_OR(entry."accountCode" = 'customer_wallet_liability'), FALSE) AS "hasCustomerWalletLedger"
          FROM "AccountingJournalEntry" entry
          WHERE entry."batchId" = batch."id"
        ) entries ON TRUE
        WHERE batch."settlementSnapshotId" = base."id"
          AND batch."sourceType"::text = 'BOOKING_SETTLEMENT_REVERSAL'
      ) reversal_journal ON TRUE
      LEFT JOIN LATERAL (
        SELECT
          COUNT(*)::bigint AS "count",
          COALESCE(BOOL_OR(clearing."amount" <> base."customerPaymentAmount" OR clearing."status"::text <> 'CLEARED'), FALSE) AS "issue",
          COALESCE(SUM(matches."matchedAmount"), 0)::bigint AS "matchedAmount"
        FROM "BookingPaymentClearingEntry" clearing
        LEFT JOIN LATERAL (
          SELECT COALESCE(SUM(ABS(match."amount")) FILTER (WHERE match."status"::text = 'MATCHED'), 0)::bigint AS "matchedAmount"
          FROM "BankReconciliationMatch" match
          WHERE match."paymentClearingEntryId" = clearing."id"
        ) matches ON TRUE
        WHERE clearing."settlementSnapshotId" = base."id"
          AND clearing."type"::text IN ('SETTLEMENT_POSTED', 'CUSTOMER_PAYMENT_CAPTURED')
      ) canonical_clearing ON TRUE
      LEFT JOIN LATERAL (
        SELECT
          COUNT(*)::bigint AS "count",
          COALESCE(BOOL_OR(clearing."amount" <> -base."customerPaymentAmount" OR clearing."status"::text <> 'REVERSED'), FALSE) AS "issue"
        FROM "BookingPaymentClearingEntry" clearing
        WHERE clearing."settlementSnapshotId" = base."id"
          AND clearing."type"::text = 'REFUND_REVERSAL'
      ) reversal_clearing ON TRUE
      LEFT JOIN LATERAL (
        SELECT COUNT(*)::bigint AS "count"
        FROM "BookingSettlementReversalEntry" reversal
        WHERE reversal."originalSettlementSnapshotId" = base."id"
      ) reversal_entry ON TRUE
      LEFT JOIN LATERAL (
        SELECT EXISTS (
          SELECT 1
          FROM "CustomerWalletLedgerEntry" ledger
          WHERE ledger."bookingId" = base."bookingId"
            AND ledger."type"::text = 'REFUND'
            AND ledger."amount" > 0
        ) AS "present"
      ) wallet_refund ON TRUE
    ),
    "settlementAuditClassified" AS NOT MATERIALIZED (
      SELECT
        facts.*,
        (facts."allocationDelta" <> 0) AS "allocationIssue",
        (facts."canonicalJournalCount" <> 1 OR facts."canonicalJournalIssue") AS "journalIssue",
        (
          facts."paymentMethod"::text IN ('BANK_TRANSFER', 'CARD', 'MANUAL', 'MOMO', 'VNPAY')
          AND (facts."canonicalClearingCount" <> 1 OR facts."canonicalClearingIssueRaw")
        ) AS "clearingIssue",
        (
          facts."paymentMethod"::text IN ('BANK_TRANSFER', 'CARD', 'MANUAL', 'MOMO', 'VNPAY')
          AND facts."canonicalMatchedAmount" < facts."customerPaymentAmount"
        ) AS "bankIssue",
        ${adminPlatformVatEvidenceStatusSql({
          companyOutputVat: Prisma.sql`facts."companyOutputVat"`,
          platformFeePolicyVersionId: Prisma.sql`facts."platformFeePolicyVersionId"`,
          platformFeeRuleSnapshot: Prisma.sql`facts."platformFeeRuleSnapshot"`,
          platformVatRateBps: Prisma.sql`facts."platformVatRateBps"`,
        })} AS "vatEvidenceStatus",
        ${adminPaymentFeeEvidenceSqlCondition({
          paymentFeePolicyVersionId: Prisma.sql`facts."paymentFeePolicyVersionId"`,
          paymentFeeRuleSnapshot: Prisma.sql`facts."paymentFeeRuleSnapshot"`,
          paymentMethod: Prisma.sql`facts."paymentMethod"`,
          reversalExists: Prisma.sql`facts."reversalEntryCount" > 0`,
          settlementStatus: Prisma.sql`facts."settlementStatus"`,
          taxStatus: Prisma.sql`facts."taxStatus"`,
        })} AS "feeIssue",
        (
          facts."companyCouponExpense" > 0
          AND (
            COALESCE(facts."metadata"->>'couponId', facts."metadata"->>'couponCodeSnapshot', '') = ''
            OR COALESCE(facts."metadata"->>'couponFundingSourceSnapshot', '') <> 'COMPANY'
            OR COALESCE(facts."metadata"->>'couponAccountingTreatmentSnapshot', '') = ''
            OR COALESCE(facts."metadata"->>'settlementBasePolicySnapshot', '') = ''
            OR CASE
              WHEN COALESCE(facts."metadata"->>'settlementBaseAmount', '') ~ '^[0-9]+$'
              THEN (facts."metadata"->>'settlementBaseAmount')::bigint <= 0
              ELSE TRUE
            END
            OR COALESCE(facts."metadata"->>'couponReviewFlag', '') <> ''
          )
        ) AS "couponIssue",
        (facts."monthlyPeriod" !~ '^\\d{4}-(0[1-9]|1[0-2])$') AS "taxPeriodIssue",
        (
          facts."settlementStatus"::text = 'REVERSED'
          OR facts."taxStatus"::text = 'REVERSED'
          OR facts."reversalEntryCount" > 0
          OR facts."reversalJournalCount" > 0
          OR facts."reversalClearingCount" > 0
          OR COALESCE(facts."reversalReason", '') <> ''
          OR facts."reversedById" IS NOT NULL
        ) AS "reversalSignal",
        (
          facts."settlementStatus"::text = 'REVERSED'
          OR facts."taxStatus"::text = 'REVERSED'
          OR facts."reversalEntryCount" > 0
          OR facts."reversalJournalCount" > 0
          OR facts."reversalClearingCount" > 0
          OR COALESCE(facts."reversalReason", '') <> ''
          OR facts."reversedById" IS NOT NULL
        ) AND (
          facts."reversalJournalCount" <> 1
          OR facts."reversalJournalIssue"
          OR facts."reversalEntryCount" > 1
          OR (
            facts."paymentMethod"::text IN ('BANK_TRANSFER', 'CARD', 'MANUAL', 'MOMO', 'VNPAY')
            AND (facts."reversalClearingCount" <> 1 OR facts."reversalClearingIssueRaw")
          )
          OR (facts."paymentMethod"::text = 'CASH' AND NOT facts."reversalHasCashLedger")
          OR (
            facts."paymentMethod"::text = 'CUSTOMER_WALLET'
            AND (NOT facts."reversalHasCustomerWalletLedger" OR NOT facts."walletRefundPresent")
          )
        ) AS "reversalIssue",
        (facts."taxStatus"::text NOT IN ('OPEN', 'DECLARED', 'PAID', 'CLOSED', 'REVERSED')) AS "integrityUnknown",
        CASE
          WHEN facts."taxStatus"::text = 'REVERSED' OR facts."settlementStatus"::text = 'REVERSED' THEN 'REVERSED'
          WHEN facts."taxStatus"::text = 'OPEN' THEN 'TAX_OPEN'
          WHEN facts."taxStatus"::text = 'DECLARED' THEN 'TAX_DECLARED'
          WHEN facts."taxStatus"::text = 'PAID' THEN 'TAX_PAID'
          WHEN facts."taxStatus"::text = 'CLOSED' THEN 'TAX_CLOSED'
          ELSE 'UNKNOWN'
        END AS "workflowState"
      FROM "settlementAuditFacts" facts
    ),
    "settlementAuditProjection" AS NOT MATERIALIZED (
      SELECT
        classified.*,
        (classified."vatEvidenceStatus" IN ('ZERO_UNEXPLAINED', 'EVIDENCE_UNAVAILABLE'))
          AS "vatEvidenceIssue",
        (
          classified."allocationIssue"
          OR classified."journalIssue"
          OR classified."clearingIssue"
          OR classified."bankIssue"
          OR classified."feeIssue"
          OR classified."couponIssue"
          OR classified."taxPeriodIssue"
          OR classified."reversalIssue"
        ) AS "integrityAction",
        (
          classified."allocationIssue"
          OR classified."journalIssue"
          OR classified."clearingIssue"
          OR classified."bankIssue"
          OR classified."feeIssue"
          OR classified."couponIssue"
          OR classified."taxPeriodIssue"
        ) AS "otherIntegrityIssue",
        CASE
          WHEN classified."taxPeriodIssue" THEN 'BLOCKED'
          WHEN classified."workflowState" NOT IN ('TAX_OPEN', 'TAX_DECLARED') THEN 'NORMAL'
          WHEN classified."taxDueAt" IS NULL THEN 'UNKNOWN'
          WHEN classified."taxDueAt" <= ${checkedAt}::timestamptz THEN 'OVERDUE'
          WHEN classified."taxDueAt" <= ${checkedAt}::timestamptz + INTERVAL '72 hours' THEN 'DUE_SOON'
          ELSE 'NORMAL'
        END AS "workflowUrgency",
        GREATEST(
          ABS(classified."allocationDelta"),
          CASE WHEN classified."clearingIssue" THEN classified."customerPaymentAmount" ELSE 0 END,
          CASE WHEN classified."bankIssue" THEN GREATEST(0, classified."customerPaymentAmount" - classified."canonicalMatchedAmount") ELSE 0 END,
          CASE WHEN classified."couponIssue" THEN classified."companyCouponExpense" ELSE 0 END,
          CASE WHEN classified."reversalIssue" THEN classified."customerPaymentAmount" ELSE 0 END
        )::bigint AS "amountAtRisk"
      FROM "settlementAuditClassified" classified
    )
  `;
}

function adminBookingSettlementAuditBaseWhereSql(options: AdminPaymentOperationsQuery) {
  const conditions: Prisma.Sql[] = [];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const period = normalizeNullable(options.period);
  const review = normalizeNullable(options.review ?? options.queue)?.toLowerCase();
  const paymentMethod = normalizeNullable(options.paymentMethod)?.toUpperCase();
  const query = normalizeNullable(options.q);
  if (dateRange?.gte instanceof Date) conditions.push(Prisma.sql`snapshot."postedAt" >= ${dateRange.gte}`);
  if (dateRange?.lte instanceof Date) conditions.push(Prisma.sql`snapshot."postedAt" <= ${dateRange.lte}`);
  if (/^\d{4}-(0[1-9]|1[0-2])$/.test(period ?? '')) {
    conditions.push(
      review === 'platform-vat-evidence'
        ? Prisma.sql`(
            snapshot."monthlyPeriod" = ${period}
            OR EXISTS (
              SELECT 1
              FROM "BookingSettlementReversalEntry" vat_reversal
              WHERE vat_reversal."originalSettlementSnapshotId" = snapshot."id"
                AND vat_reversal."monthlyPeriod" = ${period}
            )
          )`
        : Prisma.sql`snapshot."monthlyPeriod" = ${period}`,
    );
  }
  if (paymentMethod && Object.values(PaymentMethod).includes(paymentMethod as PaymentMethod)) {
    conditions.push(Prisma.sql`snapshot."paymentMethod" = ${paymentMethod}::"PaymentMethod"`);
  }
  if (query) {
    const contains = `%${query}%`;
    conditions.push(Prisma.sql`(
      CONCAT_WS(
        ' ', snapshot."id", snapshot."sourceKey", snapshot."bookingId", snapshot."paymentId",
        snapshot."customerProfileId", snapshot."providerProfileId"
      ) ILIKE ${contains}
      OR EXISTS (
        SELECT 1
        FROM "CustomerProfile" customer
        JOIN "User" customer_user ON customer_user."id" = customer."userId"
        WHERE customer."id" = snapshot."customerProfileId" AND customer_user."fullName" ILIKE ${contains}
      )
      OR EXISTS (
        SELECT 1
        FROM "ProviderProfile" provider
        JOIN "User" provider_user ON provider_user."id" = provider."userId"
        WHERE provider."id" = snapshot."providerProfileId"
          AND (provider."displayName" ILIKE ${contains} OR provider_user."fullName" ILIKE ${contains})
      )
    )`);
  }
  return conditions.length > 0 ? Prisma.join(conditions, ' AND ') : Prisma.sql`TRUE`;
}

function adminBookingSettlementAuditFilterSql(options: AdminPaymentOperationsQuery) {
  const conditions: Prisma.Sql[] = [adminBookingSettlementAuditReviewSql(options.review ?? options.queue)];
  const reason = normalizeNullable(options.reason)?.toLowerCase();
  const owner = normalizeNullable(options.owner)?.toLowerCase();
  const status = normalizeNullable(options.status)?.toLowerCase();
  const reasonSql: Record<string, Prisma.Sql> = {
    allocation: Prisma.sql`audit."allocationIssue"`,
    journal: Prisma.sql`audit."journalIssue"`,
    clearing: Prisma.sql`audit."clearingIssue"`,
    'bank-match': Prisma.sql`audit."bankIssue"`,
    'fee-policy': Prisma.sql`audit."feeIssue"`,
    'platform-vat': Prisma.sql`audit."vatEvidenceIssue"`,
    coupon: Prisma.sql`audit."couponIssue"`,
    'tax-period': Prisma.sql`audit."taxPeriodIssue"`,
    reversal: Prisma.sql`audit."reversalIssue"`,
    unknown: Prisma.sql`audit."integrityUnknown"`,
  };
  if (reason && reasonSql[reason]) conditions.push(reasonSql[reason]);
  if (owner === 'accounting') {
    conditions.push(
      Prisma.sql`(audit."allocationIssue" OR audit."journalIssue" OR audit."couponIssue" OR audit."reversalIssue")`,
    );
  } else if (owner === 'finance-operations') {
    conditions.push(
      Prisma.sql`(audit."clearingIssue" OR audit."bankIssue" OR audit."feeIssue" OR audit."reversalIssue")`,
    );
  } else if (owner === 'tax-period-close') {
    conditions.push(
      Prisma.sql`(audit."taxPeriodIssue" OR audit."vatEvidenceIssue" OR audit."workflowState" IN ('TAX_OPEN', 'TAX_DECLARED'))`,
    );
  }
  if (status === 'open') conditions.push(Prisma.sql`audit."workflowState" = 'TAX_OPEN'`);
  if (status === 'declared') conditions.push(Prisma.sql`audit."workflowState" = 'TAX_DECLARED'`);
  if (status === 'paid') conditions.push(Prisma.sql`audit."workflowState" = 'TAX_PAID'`);
  if (status === 'closed') conditions.push(Prisma.sql`audit."workflowState" = 'TAX_CLOSED'`);
  if (status === 'reversed') conditions.push(Prisma.sql`audit."workflowState" = 'REVERSED'`);
  return Prisma.join(conditions, ' AND ');
}

function adminBookingSettlementAuditReviewSql(review: string | null | undefined) {
  switch (normalizeNullable(review)?.toLowerCase()) {
    case 'integrity-exceptions':
      return Prisma.sql`audit."integrityAction"`;
    case 'payment-evidence':
      return Prisma.sql`(audit."clearingIssue" OR audit."bankIssue" OR audit."feeIssue")`;
    case 'tax-workflow':
      return Prisma.sql`(audit."taxPeriodIssue" OR audit."workflowState" IN ('TAX_OPEN', 'TAX_DECLARED'))`;
    case 'reversals':
    case 'reversed':
      return Prisma.sql`audit."reversalSignal"`;
    case 'needs-action':
    case 'open':
      return Prisma.sql`(audit."integrityAction" OR audit."integrityUnknown" OR audit."workflowUrgency" = 'OVERDUE')`;
    case 'allocation-mismatch':
      return Prisma.sql`audit."allocationIssue"`;
    case 'journal-evidence':
      return Prisma.sql`audit."journalIssue"`;
    case 'clearing-evidence':
      return Prisma.sql`(audit."clearingIssue" OR audit."bankIssue")`;
    case 'payment-fee-evidence':
      return Prisma.sql`audit."feeIssue"`;
    case 'platform-vat-evidence':
      return Prisma.sql`audit."vatEvidenceIssue"`;
    case 'coupon-evidence':
      return Prisma.sql`audit."couponIssue"`;
    case 'reversal-incomplete':
      return Prisma.sql`(audit."reversalSignal" AND audit."reversalIssue")`;
    case 'tax-evidence':
      return Prisma.sql`(audit."taxPeriodIssue" OR audit."workflowState" IN ('TAX_OPEN', 'TAX_DECLARED'))`;
    case 'unknown':
      return Prisma.sql`(audit."integrityUnknown" OR audit."workflowUrgency" = 'UNKNOWN')`;
    case 'resolved':
      return Prisma.sql`(NOT audit."integrityAction" AND NOT audit."integrityUnknown" AND (NOT audit."reversalSignal" OR NOT audit."reversalIssue"))`;
    case 'tax-open':
      return Prisma.sql`audit."workflowState" = 'TAX_OPEN'`;
    case 'declared':
      return Prisma.sql`audit."workflowState" = 'TAX_DECLARED'`;
    case 'paid':
      return Prisma.sql`audit."workflowState" = 'TAX_PAID'`;
    case 'closed':
      return Prisma.sql`audit."workflowState" = 'TAX_CLOSED'`;
    case 'posted':
      return Prisma.sql`audit."settlementStatus"::text = 'POSTED'`;
    case 'cash':
      return Prisma.sql`audit."paymentMethod"::text = 'CASH'`;
    case 'non-cash':
      return Prisma.sql`audit."paymentMethod"::text <> 'CASH'`;
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminBookingSettlementAuditOrderSql(options: AdminPaymentOperationsQuery) {
  const sort = adminBookingSettlementAuditEffectiveSort(options);
  if (sort === 'largest-discrepancy') {
    return Prisma.sql`audit."amountAtRisk" DESC, audit."postedAt" ASC, audit."id" ASC`;
  }
  if (sort === 'oldest') return Prisma.sql`audit."postedAt" ASC, audit."id" ASC`;
  return Prisma.sql`audit."postedAt" DESC, audit."id" DESC`;
}

function adminBookingSettlementAuditEffectiveSort(
  options: AdminPaymentOperationsQuery,
): AdminBookingSettlementAuditCursor['sort'] {
  const sort = normalizeNullable(options.sort)?.toLowerCase();
  if (sort === 'largest-discrepancy' || sort === 'newest' || sort === 'oldest') return sort;
  const review = normalizeNullable(options.review ?? options.queue)?.toLowerCase();
  return !review ||
    ['needs-action', 'open', 'integrity-exceptions', 'payment-evidence', 'tax-workflow'].includes(review)
    ? 'oldest'
    : 'newest';
}

function adminBookingSettlementAuditCursor(value: string | null | undefined) {
  const encoded = normalizeNullable(value);
  if (!encoded) return null;
  try {
    const parsed = JSON.parse(Buffer.from(encoded, 'base64url').toString('utf8')) as Record<string, unknown>;
    const amountAtRisk = typeof parsed.amountAtRisk === 'string' ? parsed.amountAtRisk : '';
    const id = typeof parsed.id === 'string' ? parsed.id : '';
    const postedAt = typeof parsed.postedAt === 'string' ? new Date(parsed.postedAt) : new Date(Number.NaN);
    const sort = parsed.sort;
    if (
      !/^\d+$/.test(amountAtRisk) ||
      !id ||
      Number.isNaN(postedAt.getTime()) ||
      (sort !== 'largest-discrepancy' && sort !== 'newest' && sort !== 'oldest')
    ) {
      throw new Error('invalid cursor payload');
    }
    return {
      amountAtRisk: BigInt(amountAtRisk),
      id,
      postedAt,
      sort,
    } satisfies AdminBookingSettlementAuditCursor;
  } catch {
    throw new BadRequestException('Invalid booking settlement audit cursor');
  }
}

function adminBookingSettlementAuditCursorSql(
  cursor: AdminBookingSettlementAuditCursor | null,
  options: AdminPaymentOperationsQuery,
) {
  if (!cursor) return Prisma.sql`TRUE`;
  const sort = adminBookingSettlementAuditEffectiveSort(options);
  if (cursor.sort !== sort) {
    throw new BadRequestException('Booking settlement audit cursor sort does not match the requested sort');
  }
  if (sort === 'largest-discrepancy') {
    return Prisma.sql`(
      audit."amountAtRisk" < ${cursor.amountAtRisk}
      OR (audit."amountAtRisk" = ${cursor.amountAtRisk} AND audit."postedAt" > ${cursor.postedAt})
      OR (
        audit."amountAtRisk" = ${cursor.amountAtRisk}
        AND audit."postedAt" = ${cursor.postedAt}
        AND audit."id" > ${cursor.id}
      )
    )`;
  }
  if (sort === 'oldest') {
    return Prisma.sql`(
      audit."postedAt" > ${cursor.postedAt}
      OR (audit."postedAt" = ${cursor.postedAt} AND audit."id" > ${cursor.id})
    )`;
  }
  return Prisma.sql`(
    audit."postedAt" < ${cursor.postedAt}
    OR (audit."postedAt" = ${cursor.postedAt} AND audit."id" < ${cursor.id})
  )`;
}

function adminBookingSettlementAuditCursorValue(
  row: AdminBookingSettlementAuditIdRow | undefined,
  options: AdminPaymentOperationsQuery,
) {
  if (!row) return undefined;
  return Buffer.from(
    JSON.stringify({
      amountAtRisk: String(row.amountAtRisk),
      id: row.id,
      postedAt: row.postedAt.toISOString(),
      sort: adminBookingSettlementAuditEffectiveSort(options),
    }),
  ).toString('base64url');
}

function adminBookingSettlementReversalWhere(
  options: AdminPaymentOperationsQuery,
): Prisma.BookingSettlementReversalEntryWhereInput | undefined {
  const filters: Prisma.BookingSettlementReversalEntryWhereInput[] = [];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const reviewWhere = adminBookingSettlementReversalReviewWhere(options.review);

  if (dateRange) {
    filters.push({ occurredAt: dateRange });
  }
  if (reviewWhere) {
    filters.push(reviewWhere);
  }

  if (filters.length === 0) {
    return undefined;
  }
  return filters.length === 1 ? filters[0] : { AND: filters };
}

function adminMergeBookingSettlementReversalWhere(
  base: Prisma.BookingSettlementReversalEntryWhereInput | undefined,
  next: Prisma.BookingSettlementReversalEntryWhereInput,
): Prisma.BookingSettlementReversalEntryWhereInput {
  return base ? { AND: [base, next] } : next;
}

function adminBookingSettlementReversalCountArgs(
  where: Prisma.BookingSettlementReversalEntryWhereInput | undefined,
): Prisma.BookingSettlementReversalEntryCountArgs {
  return where ? { where } : {};
}

function adminBookingSettlementReversalReviewWhere(
  review: string | null | undefined,
): Prisma.BookingSettlementReversalEntryWhereInput | undefined {
  switch (normalizeNullable(review)) {
    case 'cash':
      return { paymentMethod: PaymentMethod.CASH };
    case 'non-cash':
      return { paymentMethod: { not: PaymentMethod.CASH } };
    case 'reversed':
    case 'refund':
    case 'closed-period':
      return {
        OR: [
          { settlementStatus: BookingSettlementStatus.REVERSED },
          { taxStatus: BookingSettlementTaxStatus.REVERSED },
        ],
      };
    default:
      return undefined;
  }
}

type AdminAccountingJournalIntegrityRow = {
  discrepancyAmount: bigint | number;
  entryCount: bigint | number;
  entryCredit: bigint | number;
  entryDebit: bigint | number;
  formulaDelta: bigint | number | null;
  formulaEvidenceAvailable: boolean;
  headerCredit: bigint | number;
  headerDebit: bigint | number;
  hasCashLedger: boolean;
  hasCustomerWalletLedger: boolean;
  id: string;
  linkedMonthlyPeriod: string | null;
  monthlyPeriod: string | null;
  sourceType: AccountingJournalSourceType;
  status: AccountingJournalBatchStatus;
};

type AdminAccountingJournalExportRow = AdminAccountingJournalIntegrityRow & {
  bookingId: string | null;
  createdAt: Date | string;
  currency: string;
  customerProfileId: string | null;
  paymentId: string | null;
  postedAt: Date | string;
  providerProfileId: string | null;
  reversedAt: Date | string | null;
  settlementReversalEntryId: string | null;
  settlementSnapshotId: string | null;
  sourceId: string;
  sourceKey: string;
  totalRows: bigint | number;
  updatedAt: Date | string;
};

const ADMIN_ACCOUNTING_JOURNAL_MONTHLY_PERIOD_REQUIRED_SOURCE_TYPES =
  ACCOUNTING_JOURNAL_MONTHLY_PERIOD_REQUIRED_SOURCE_TYPES.map(
    (sourceType) => sourceType as AccountingJournalSourceType,
  );

function adminAccountingJournalMonthlyPeriodRequiredSourceSql(column: Prisma.Sql) {
  return Prisma.sql`${column} IN (${Prisma.join(
    ADMIN_ACCOUNTING_JOURNAL_MONTHLY_PERIOD_REQUIRED_SOURCE_TYPES.map(
      (sourceType) => Prisma.sql`${sourceType}::"AccountingJournalSourceType"`,
    ),
  )})`;
}

function adminAccountingJournalIntegrityFromRow(
  row: AdminAccountingJournalIntegrityRow,
  checkedAt: string,
): AccountingJournalIntegrity {
  return buildAccountingJournalIntegrity({
    checkedAt,
    entryCount: numberValue(row.entryCount),
    entryCredit: numberValue(row.entryCredit),
    entryDebit: numberValue(row.entryDebit),
    formulaDelta: row.formulaDelta === null ? null : numberValue(row.formulaDelta),
    formulaEvidenceAvailable: row.formulaEvidenceAvailable,
    headerCredit: numberValue(row.headerCredit),
    headerDebit: numberValue(row.headerDebit),
    linkedMonthlyPeriod: row.linkedMonthlyPeriod,
    monthlyPeriod: row.monthlyPeriod,
    sourceType: row.sourceType,
    status: row.status,
  });
}

function adminAccountingJournalIntegrityCte(
  options: AdminPaymentOperationsQuery,
  id?: string,
  includeTargetLinkedPeriodless = false,
  ids?: readonly string[],
) {
  const baseWhere = adminAccountingJournalBatchBaseSqlWhere(options, id, includeTargetLinkedPeriodless, ids);
  const filteredBatchesMaterialization = normalizeNullable(options.q)
    ? Prisma.sql`MATERIALIZED`
    : Prisma.sql`NOT MATERIALIZED`;
  return Prisma.sql`
    WITH filtered_batches AS ${filteredBatchesMaterialization} (
      SELECT batch.*
      FROM "AccountingJournalBatch" batch
      WHERE ${baseWhere}
    ),
    entry_totals AS (
      SELECT
        entry."batchId",
        COUNT(*)::bigint AS "entryCount",
        COALESCE(SUM(entry."amount") FILTER (
          WHERE entry."side" = ${AccountingJournalEntrySide.DEBIT}::"AccountingJournalEntrySide"
        ), 0)::bigint AS "entryDebit",
        COALESCE(SUM(entry."amount") FILTER (
          WHERE entry."side" = ${AccountingJournalEntrySide.CREDIT}::"AccountingJournalEntrySide"
        ), 0)::bigint AS "entryCredit",
        COALESCE(BOOL_OR(
          entry."accountCode" IN ('partner_receivable_negative_wallet', 'partner_wallet_liability')
        ), FALSE) AS "hasCashLedger",
        COALESCE(BOOL_OR(
          entry."accountCode" = 'customer_wallet_liability'
        ), FALSE) AS "hasCustomerWalletLedger"
      FROM "AccountingJournalEntry" entry
      INNER JOIN filtered_batches batch ON batch."id" = entry."batchId"
      GROUP BY entry."batchId"
    ),
    journal_facts AS (
      SELECT
        batch.*,
        COALESCE(entries."entryCount", 0)::bigint AS "entryCount",
        COALESCE(entries."entryDebit", 0)::bigint AS "entryDebit",
        COALESCE(entries."entryCredit", 0)::bigint AS "entryCredit",
        COALESCE(entries."hasCashLedger", FALSE) AS "hasCashLedger",
        COALESCE(entries."hasCustomerWalletLedger", FALSE) AS "hasCustomerWalletLedger",
        CASE
          WHEN batch."sourceType" IN (
            ${AccountingJournalSourceType.BOOKING_SETTLEMENT}::"AccountingJournalSourceType",
            ${AccountingJournalSourceType.BOOKING_SETTLEMENT_REVERSAL}::"AccountingJournalSourceType"
          ) THEN COALESCE(
            CASE
              WHEN jsonb_typeof(batch."metadata"->'reconciliationDelta') = 'number'
              THEN (batch."metadata"->>'reconciliationDelta')::numeric::bigint
              ELSE NULL
            END,
            CASE WHEN settlement."id" IS NOT NULL THEN (
              settlement."customerPaymentAmount"
              - settlement."partnerPayoutAmount"
              - settlement."partnerWithholdingTotal"
              - settlement."paymentProcessingFee"
              - settlement."platformFeeNetRevenue"
              - settlement."companyOutputVat"
            )::bigint ELSE NULL END,
            CASE WHEN reversal."id" IS NOT NULL THEN (
              reversal."customerPaymentAmount"
              - reversal."partnerPayoutAmount"
              - reversal."partnerWithholdingTotal"
              - reversal."paymentProcessingFee"
              - reversal."platformFeeNetRevenue"
              - reversal."companyOutputVat"
            )::bigint ELSE NULL END
          )
          ELSE NULL
        END AS "formulaDelta",
        (
          COALESCE(jsonb_typeof(batch."metadata"->'reconciliationDelta') = 'number', FALSE)
          OR settlement."id" IS NOT NULL
          OR reversal."id" IS NOT NULL
        ) AS "formulaEvidenceAvailable",
        CASE
          WHEN batch."sourceType" = ${AccountingJournalSourceType.BOOKING_SETTLEMENT}::"AccountingJournalSourceType"
          THEN settlement."monthlyPeriod"
          WHEN batch."sourceType" = ${AccountingJournalSourceType.BOOKING_SETTLEMENT_REVERSAL}::"AccountingJournalSourceType"
          THEN reversal."monthlyPeriod"
          ELSE NULL
        END AS "linkedMonthlyPeriod"
      FROM filtered_batches batch
      LEFT JOIN entry_totals entries ON entries."batchId" = batch."id"
      LEFT JOIN "BookingSettlementSnapshot" settlement
        ON settlement."id" = batch."settlementSnapshotId"
      LEFT JOIN "BookingSettlementReversalEntry" reversal
        ON reversal."id" = batch."settlementReversalEntryId"
    ),
    journal_integrity AS (
      SELECT
        facts.*,
        GREATEST(
          ABS(facts."totalDebit" - facts."totalCredit"),
          ABS(facts."entryDebit" - facts."entryCredit"),
          ABS(facts."totalDebit" - facts."entryDebit"),
          ABS(facts."totalCredit" - facts."entryCredit"),
          ABS(COALESCE(facts."formulaDelta", 0))
        )::bigint AS "discrepancyAmount",
        CASE
          WHEN facts."totalDebit" <> facts."totalCredit"
            OR facts."entryDebit" <> facts."entryCredit"
            OR facts."totalDebit" <> facts."entryDebit"
            OR facts."totalCredit" <> facts."entryCredit"
            OR (
              facts."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
              AND facts."entryCount" = 0
            )
            OR (
              facts."sourceType" IN (
                ${AccountingJournalSourceType.BOOKING_SETTLEMENT}::"AccountingJournalSourceType",
                ${AccountingJournalSourceType.BOOKING_SETTLEMENT_REVERSAL}::"AccountingJournalSourceType"
              )
              AND facts."formulaEvidenceAvailable"
              AND ABS(COALESCE(facts."formulaDelta", 0)) > 0
            )
            OR (
              facts."sourceType" IN (
                ${AccountingJournalSourceType.BOOKING_SETTLEMENT}::"AccountingJournalSourceType",
                ${AccountingJournalSourceType.BOOKING_SETTLEMENT_REVERSAL}::"AccountingJournalSourceType"
              )
              AND facts."monthlyPeriod" IS NOT NULL
              AND facts."linkedMonthlyPeriod" IS NOT NULL
              AND facts."monthlyPeriod" <> facts."linkedMonthlyPeriod"
            )
          THEN 'BLOCKED'
          WHEN (
            facts."sourceType" IN (
            ${AccountingJournalSourceType.BOOKING_SETTLEMENT}::"AccountingJournalSourceType",
            ${AccountingJournalSourceType.BOOKING_SETTLEMENT_REVERSAL}::"AccountingJournalSourceType"
          ) AND (
            NOT facts."formulaEvidenceAvailable"
            OR facts."monthlyPeriod" IS NULL
            OR facts."linkedMonthlyPeriod" IS NULL
          )
          ) OR (
            facts."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
            AND ${adminAccountingJournalMonthlyPeriodRequiredSourceSql(Prisma.sql`facts."sourceType"`)}
            AND facts."monthlyPeriod" IS NULL
          )
          THEN 'UNKNOWN'
          ELSE 'CLEAR'
        END AS "integrityState"
      FROM journal_facts facts
    )
  `;
}

function adminAccountingJournalIntegrityPageSql(
  options: AdminPaymentOperationsQuery,
  take: number,
  skip: number,
  id?: string,
  ids?: readonly string[],
) {
  return Prisma.sql`
    ${adminAccountingJournalIntegrityCte(options, id, false, ids)}
    SELECT
      integrity."id",
      integrity."sourceType",
      integrity."status",
      integrity."totalDebit" AS "headerDebit",
      integrity."totalCredit" AS "headerCredit",
      integrity."entryCount",
      integrity."entryDebit",
      integrity."entryCredit",
      integrity."hasCashLedger",
      integrity."hasCustomerWalletLedger",
      integrity."formulaDelta",
      integrity."formulaEvidenceAvailable",
      integrity."monthlyPeriod",
      integrity."linkedMonthlyPeriod",
      integrity."discrepancyAmount"
    FROM journal_integrity integrity
    WHERE ${adminAccountingJournalIntegrityReviewSql(options)}
    ORDER BY ${adminAccountingJournalIntegrityOrderSql(options)}
    OFFSET ${skip}
    LIMIT ${take}
  `;
}

function adminAccountingJournalIntegritySummarySql(options: AdminPaymentOperationsQuery) {
  return Prisma.sql`
    ${adminAccountingJournalIntegrityCte(options)}
    SELECT
      COUNT(*)::bigint AS "count",
      COUNT(*) FILTER (
        WHERE integrity."integrityState" = 'CLEAR'
      )::bigint AS "balancedCount",
      COUNT(*) FILTER (WHERE integrity."integrityState" = 'CLEAR')::bigint AS "clearCount",
      COUNT(*) FILTER (WHERE integrity."integrityState" = 'BLOCKED')::bigint AS "blockedCount",
      COUNT(*) FILTER (WHERE integrity."integrityState" = 'UNKNOWN')::bigint AS "unknownCount",
      COUNT(*) FILTER (
        WHERE integrity."status" = ${AccountingJournalBatchStatus.DRAFT}::"AccountingJournalBatchStatus"
           OR integrity."integrityState" IN ('BLOCKED', 'UNKNOWN')
      )::bigint AS "needsActionCount",
      COUNT(*) FILTER (
        WHERE integrity."status" = ${AccountingJournalBatchStatus.DRAFT}::"AccountingJournalBatchStatus"
      )::bigint AS "draftCount",
      COUNT(*) FILTER (
        WHERE integrity."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
      )::bigint AS "postedCount",
      COUNT(*) FILTER (
        WHERE integrity."status" = ${AccountingJournalBatchStatus.REVERSED}::"AccountingJournalBatchStatus"
      )::bigint AS "reversedCount",
      COUNT(*) FILTER (
        WHERE integrity."integrityState" = 'BLOCKED'
      )::bigint AS "unbalancedCount",
      COUNT(*) FILTER (WHERE ABS(COALESCE(integrity."formulaDelta", 0)) > 0)::bigint AS "formulaDeltaCount",
      COUNT(*) FILTER (
        WHERE integrity."totalDebit" <> integrity."totalCredit"
      )::bigint AS "headerMismatchCount",
      COUNT(*) FILTER (
        WHERE integrity."entryDebit" <> integrity."entryCredit"
      )::bigint AS "entryMismatchCount",
      COUNT(*) FILTER (
        WHERE integrity."totalDebit" <> integrity."entryDebit"
           OR integrity."totalCredit" <> integrity."entryCredit"
      )::bigint AS "headerEntryMismatchCount",
      COUNT(*) FILTER (
        WHERE integrity."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
          AND integrity."entryCount" = 0
      )::bigint AS "postedWithoutEntryCount",
      COALESCE(SUM(integrity."totalDebit"), 0)::bigint AS "totalDebit",
      COALESCE(SUM(integrity."totalCredit"), 0)::bigint AS "totalCredit",
      COALESCE(SUM(integrity."discrepancyAmount") FILTER (
        WHERE integrity."integrityState" = 'BLOCKED'
      ), 0)::bigint AS "blockedAmount",
      COALESCE(SUM(integrity."discrepancyAmount") FILTER (
        WHERE integrity."integrityState" = 'BLOCKED'
      ), 0)::bigint AS "unbalancedAmount",
      MIN(integrity."postedAt") FILTER (
        WHERE integrity."status" = ${AccountingJournalBatchStatus.DRAFT}::"AccountingJournalBatchStatus"
      ) AS "oldestDraftAt",
      MIN(integrity."postedAt") FILTER (
        WHERE integrity."integrityState" IN ('BLOCKED', 'UNKNOWN')
      ) AS "oldestUnbalancedAt",
      MIN(integrity."postedAt") FILTER (
        WHERE integrity."integrityState" IN ('BLOCKED', 'UNKNOWN')
      ) AS "oldestBlockerAt"
    FROM journal_integrity integrity
    WHERE ${adminAccountingJournalIntegrityReviewSql(options)}
  `;
}

export function adminAccountingJournalPerformanceQueries(
  options: AdminPaymentOperationsQuery = {},
  take = 10,
  skip = 0,
) {
  return [
    { name: 'list-page', sql: adminAccountingJournalIntegrityPageSql(options, take, skip) },
    { name: 'summary-aggregate', sql: adminAccountingJournalIntegritySummarySql(options) },
  ] as const;
}

function adminAccountingJournalIntegrityExportSql(options: AdminPaymentOperationsQuery, take: number) {
  return Prisma.sql`
    ${adminAccountingJournalIntegrityCte(options)}
    SELECT
      integrity."id",
      integrity."sourceKey",
      integrity."sourceType",
      integrity."sourceId",
      integrity."bookingId",
      integrity."customerProfileId",
      integrity."providerProfileId",
      integrity."paymentId",
      integrity."settlementSnapshotId",
      integrity."settlementReversalEntryId",
      integrity."monthlyPeriod",
      integrity."currency",
      integrity."status",
      integrity."totalDebit" AS "headerDebit",
      integrity."totalCredit" AS "headerCredit",
      integrity."postedAt",
      integrity."reversedAt",
      integrity."createdAt",
      integrity."updatedAt",
      integrity."entryCount",
      integrity."entryDebit",
      integrity."entryCredit",
      integrity."formulaDelta",
      integrity."formulaEvidenceAvailable",
      integrity."linkedMonthlyPeriod",
      integrity."discrepancyAmount",
      COUNT(*) OVER()::bigint AS "totalRows"
    FROM journal_integrity integrity
    WHERE ${adminAccountingJournalIntegrityReviewSql(options)}
    ORDER BY ${adminAccountingJournalIntegrityOrderSql(options)}
    LIMIT ${take}
  `;
}

function adminAccountingJournalBatchBaseSqlWhere(
  options: AdminPaymentOperationsQuery,
  id?: string,
  includeTargetLinkedPeriodless = false,
  ids?: readonly string[],
) {
  const filters: Prisma.Sql[] = [];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const query = normalizeNullable(options.q);
  const period = normalizeNullable(options.period);
  const source = normalizeAccountingJournalSourceType(options.source);

  if (id) filters.push(Prisma.sql`batch."id" = ${id}`);
  if (ids?.length) filters.push(Prisma.sql`batch."id" IN (${Prisma.join(ids)})`);

  if (dateRange) {
    filters.push(
      Prisma.sql`batch."postedAt" >= ${dateRange.gte as Date} AND batch."postedAt" <= ${dateRange.lte as Date}`,
    );
  }
  if (period) {
    filters.push(
      includeTargetLinkedPeriodless
        ? Prisma.sql`(
            batch."monthlyPeriod" = ${period}
            OR (
              batch."monthlyPeriod" IS NULL
              AND batch."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
              AND ${adminAccountingJournalMonthlyPeriodRequiredSourceSql(Prisma.sql`batch."sourceType"`)}
              AND (
                (
                  batch."sourceType" = ${AccountingJournalSourceType.BOOKING_SETTLEMENT}::"AccountingJournalSourceType"
                  AND EXISTS (
                    SELECT 1
                    FROM "BookingSettlementSnapshot" target_settlement
                    WHERE target_settlement."id" = batch."settlementSnapshotId"
                      AND target_settlement."monthlyPeriod" = ${period}
                  )
                )
                OR (
                  batch."sourceType" = ${AccountingJournalSourceType.BOOKING_SETTLEMENT_REVERSAL}::"AccountingJournalSourceType"
                  AND EXISTS (
                    SELECT 1
                    FROM "BookingSettlementReversalEntry" target_reversal
                    WHERE target_reversal."id" = batch."settlementReversalEntryId"
                      AND target_reversal."monthlyPeriod" = ${period}
                  )
                )
                OR batch."metadata"->>'monthlyPeriod' = ${period}
                OR EXISTS (
                  SELECT 1
                  FROM (
                    SELECT provider_ledger."metadata"
                    FROM "ProviderWalletLedgerEntry" provider_ledger
                    WHERE provider_ledger."id" = batch."sourceId"
                    UNION ALL
                    SELECT customer_ledger."metadata"
                    FROM "CustomerWalletLedgerEntry" customer_ledger
                    WHERE customer_ledger."id" = batch."sourceId"
                  ) ledger
                  WHERE ledger."metadata"->>'monthlyPeriod' = ${period}
                )
                OR (
                  batch."sourceType" = ${AccountingJournalSourceType.REFERRAL_REWARD}::"AccountingJournalSourceType"
                  AND EXISTS (
                    SELECT 1
                    FROM (
                      SELECT provider_ledger."createdAt"
                      FROM "ProviderWalletLedgerEntry" provider_ledger
                      WHERE provider_ledger."id" = batch."metadata"->>'ledgerId'
                      UNION ALL
                      SELECT customer_ledger."createdAt"
                      FROM "CustomerWalletLedgerEntry" customer_ledger
                      WHERE customer_ledger."id" = batch."metadata"->>'ledgerId'
                    ) referral_ledger
                    WHERE TO_CHAR(
                      referral_ledger."createdAt" AT TIME ZONE 'UTC' AT TIME ZONE ${VIETNAM_TIME_ZONE},
                      'YYYY-MM'
                    ) = ${period}
                  )
                )
              )
            )
          )`
        : Prisma.sql`batch."monthlyPeriod" = ${period}`,
    );
  }
  if (source) {
    filters.push(Prisma.sql`batch."sourceType" = ${source}::"AccountingJournalSourceType"`);
  }
  if (query) {
    const contains = `%${query}%`;
    filters.push(Prisma.sql`(
      CONCAT_WS(
        ' ',
        batch."id",
        batch."sourceKey",
        batch."sourceId",
        batch."bookingId",
        batch."paymentId",
        batch."monthlyPeriod"
      ) ILIKE ${contains}
      OR EXISTS (
        SELECT 1
        FROM "AccountingJournalEntry" searched_entry
        WHERE searched_entry."batchId" = batch."id"
          AND (
            searched_entry."accountCode" ILIKE ${contains}
            OR searched_entry."accountName" ILIKE ${contains}
          )
      )
    )`);
  }
  return filters.length > 0 ? Prisma.join(filters, ' AND ') : Prisma.sql`TRUE`;
}

function adminAccountingJournalIntegrityReviewSql(options: AdminPaymentOperationsQuery) {
  const review = normalizeNullable(options.review ?? options.status)?.toLowerCase();
  switch (review) {
    case 'needs-action':
      return Prisma.sql`(
        integrity."status" = ${AccountingJournalBatchStatus.DRAFT}::"AccountingJournalBatchStatus"
        OR integrity."integrityState" IN ('BLOCKED', 'UNKNOWN')
      )`;
    case 'unbalanced':
      return Prisma.sql`integrity."integrityState" = 'BLOCKED'`;
    case 'unknown':
      return Prisma.sql`integrity."integrityState" = 'UNKNOWN'`;
    case 'unassigned-period':
      return Prisma.sql`(
        integrity."integrityState" = 'UNKNOWN'
        AND integrity."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
        AND ${adminAccountingJournalMonthlyPeriodRequiredSourceSql(Prisma.sql`integrity."sourceType"`)}
        AND integrity."monthlyPeriod" IS NULL
      )`;
    case 'draft':
      return Prisma.sql`integrity."status" = ${AccountingJournalBatchStatus.DRAFT}::"AccountingJournalBatchStatus"`;
    case 'posted':
    case 'open':
      return Prisma.sql`integrity."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"`;
    case 'reversed':
      return Prisma.sql`integrity."status" = ${AccountingJournalBatchStatus.REVERSED}::"AccountingJournalBatchStatus"`;
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminAccountingJournalIntegrityOrderSql(options: AdminPaymentOperationsQuery) {
  const sort = normalizeNullable(options.sort)?.toLowerCase();
  if (sort === 'largest-discrepancy') {
    return Prisma.sql`integrity."discrepancyAmount" DESC, integrity."postedAt" ASC, integrity."id" ASC`;
  }
  if (sort === 'oldest') {
    return Prisma.sql`integrity."postedAt" ASC, integrity."id" ASC`;
  }
  if (sort === 'newest' || sort === 'recent') {
    return Prisma.sql`integrity."postedAt" DESC, integrity."id" DESC`;
  }
  const review = normalizeNullable(options.review ?? options.status)?.toLowerCase();
  return review === 'needs-action' || review === 'unbalanced' || review === 'unknown' || review === 'draft'
    ? Prisma.sql`integrity."postedAt" ASC, integrity."id" ASC`
    : Prisma.sql`integrity."postedAt" DESC, integrity."id" DESC`;
}

function normalizeAccountingJournalSourceType(value: string | null | undefined) {
  const normalized = normalizeNullable(value)?.toUpperCase();
  return Object.values(AccountingJournalSourceType).includes(normalized as AccountingJournalSourceType)
    ? (normalized as AccountingJournalSourceType)
    : null;
}

function adminBookingPaymentClearingReviewStatus(
  review: string | null | undefined,
): BookingPaymentClearingStatus | undefined {
  switch (normalizeNullable(review)?.toLowerCase()) {
    case 'needs-action':
    case 'open':
      return BookingPaymentClearingStatus.OPEN;
    case 'partial':
    case 'partially-cleared':
      return BookingPaymentClearingStatus.PARTIALLY_CLEARED;
    case 'cleared':
      return BookingPaymentClearingStatus.CLEARED;
    case 'reversed':
      return BookingPaymentClearingStatus.REVERSED;
    default:
      return undefined;
  }
}

function bookingPaymentClearingExpectedBankDirection(
  type: BookingPaymentClearingEntryType,
  amount: number,
): CompanyBankTransactionType | null {
  if (
    type === BookingPaymentClearingEntryType.CUSTOMER_PAYMENT_CAPTURED ||
    type === BookingPaymentClearingEntryType.SETTLEMENT_POSTED
  ) {
    return amount > 0 ? CompanyBankTransactionType.INFLOW : null;
  }
  if (type === BookingPaymentClearingEntryType.REFUND_REVERSAL) {
    return amount < 0 ? CompanyBankTransactionType.OUTFLOW : null;
  }
  return null;
}

function adminBookingPaymentClearingSort(
  value: string | null | undefined,
  review: string | null | undefined,
) {
  const normalized = normalizeNullable(value)?.toLowerCase();
  if (normalized === 'highest-remaining') return 'highest-remaining' as const;
  if (normalized === 'recent') return 'recent' as const;
  if (normalized === 'oldest') return 'oldest' as const;
  const status = adminBookingPaymentClearingReviewStatus(review);
  return status === BookingPaymentClearingStatus.OPEN ||
    status === BookingPaymentClearingStatus.PARTIALLY_CLEARED ||
    normalizeNullable(review)?.toLowerCase() === 'unresolved'
    ? ('oldest' as const)
    : ('recent' as const);
}

function adminBookingPaymentClearingSqlWhere(options: AdminPaymentOperationsQuery) {
  const filters: Prisma.Sql[] = [];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const review = normalizeNullable(options.review ?? options.status)?.toLowerCase();
  const status = adminBookingPaymentClearingReviewStatus(review);
  const query = normalizeNullable(options.q);
  if (dateRange) {
    filters.push(
      Prisma.sql`clearing."occurredAt" >= ${dateRange.gte as Date} AND clearing."occurredAt" <= ${dateRange.lte as Date}`,
    );
  }
  if (review === 'unresolved') {
    filters.push(
      Prisma.sql`clearing."status" IN (
        ${BookingPaymentClearingStatus.OPEN}::"BookingPaymentClearingStatus",
        ${BookingPaymentClearingStatus.PARTIALLY_CLEARED}::"BookingPaymentClearingStatus"
      )`,
    );
  } else if (review === 'terminal') {
    filters.push(
      Prisma.sql`clearing."status" IN (
        ${BookingPaymentClearingStatus.CLEARED}::"BookingPaymentClearingStatus",
        ${BookingPaymentClearingStatus.REVERSED}::"BookingPaymentClearingStatus"
      )`,
    );
  } else if (status) {
    filters.push(Prisma.sql`clearing."status" = ${status}::"BookingPaymentClearingStatus"`);
  }
  if (adminPaymentClearingAge(options.age) === '48h') {
    filters.push(Prisma.sql`clearing."occurredAt" <= CURRENT_TIMESTAMP - INTERVAL '48 hours'`);
  }
  if (query) {
    const contains = `%${query}%`;
    filters.push(Prisma.sql`(
      clearing."id" ILIKE ${contains}
      OR clearing."bookingId" ILIKE ${contains}
      OR clearing."paymentId" ILIKE ${contains}
      OR clearing."sourceKey" ILIKE ${contains}
    )`);
  }
  return filters.length > 0 ? Prisma.join(filters, ' AND ') : Prisma.sql`TRUE`;
}

function adminPaymentClearingAge(value: string | null | undefined) {
  const normalized = normalizeNullable(value)?.toLowerCase();
  if (!normalized) return undefined;
  if (normalized === '48h') return '48h' as const;
  throw new BadRequestException('Valid payment clearing age is required');
}

function adminBookingPaymentClearingLatestReviewAssignmentJoinSql() {
  return Prisma.sql`
    LEFT JOIN LATERAL (
      SELECT assignment_log."metadata", assignment_log."createdAt"
      FROM "AdminAuditLog" assignment_log
      WHERE assignment_log."action" = ${BOOKING_PAYMENT_CLEARING_REVIEW_ASSIGNMENT_ACTION}
        AND assignment_log."target" = 'booking_payment_clearing_entry:' || clearing."id"
      ORDER BY assignment_log."createdAt" DESC, assignment_log."id" DESC
      LIMIT 1
    ) assignment ON TRUE
  `;
}

function adminBookingPaymentClearingReviewAssignmentWhere(options: AdminPaymentOperationsQuery) {
  const assigneeAdminId = normalizeNullable(options.assigneeAdminId);
  if (assigneeAdminId) {
    return Prisma.sql`assignment."metadata"->>'assigneeAdminId' = ${assigneeAdminId}`;
  }
  switch (normalizeNullable(options.assignment)?.toLowerCase()) {
    case 'assigned':
      return Prisma.sql`assignment."metadata"->>'assigneeAdminId' IS NOT NULL`;
    case 'unassigned':
      return Prisma.sql`assignment."metadata"->>'assigneeAdminId' IS NULL`;
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminBankReconciliationWhere(
  options: AdminPaymentOperationsQuery,
): Prisma.CompanyBankTransactionWhereInput | undefined {
  const filters: Prisma.CompanyBankTransactionWhereInput[] = [];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const periodRange = adminAccountingPeriodDateRange(options.period);
  const reviewWhere = adminBankReconciliationReviewWhere(options.review ?? options.status);
  const transactionType = adminBankReconciliationTransactionType(options.type);
  const evidenceSource = adminBankReconciliationEvidenceSource(options.source);
  const age = adminBankReconciliationAge(options.age);
  const query = normalizeNullable(options.q);

  if (dateRange) {
    filters.push({ occurredAt: dateRange });
  }
  if (periodRange) {
    filters.push({ occurredAt: periodRange });
  }
  if (reviewWhere) {
    filters.push(reviewWhere);
  }
  if (transactionType) {
    filters.push({ type: transactionType });
  }
  if (evidenceSource) {
    filters.push(adminBankReconciliationEvidenceSourceWhere(evidenceSource));
  }
  if (age === '48h') {
    filters.push({ occurredAt: { lte: new Date(Date.now() - 48 * 60 * 60_000) } });
  }
  if (query) {
    filters.push({
      OR: [
        { transferRef: { contains: query, mode: 'insensitive' } },
        { counterpartyName: { contains: query, mode: 'insensitive' } },
        { description: { contains: query, mode: 'insensitive' } },
        { sourceKey: { contains: query, mode: 'insensitive' } },
      ],
    });
  }

  if (filters.length === 0) {
    return undefined;
  }
  return filters.length === 1 ? filters[0] : { AND: filters };
}

function adminBankReconciliationSqlWhere(options: AdminPaymentOperationsQuery) {
  const filters: Prisma.Sql[] = [];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const periodRange = adminAccountingPeriodDateRange(options.period);
  const transactionType = adminBankReconciliationTransactionType(options.type);
  const evidenceSource = adminBankReconciliationEvidenceSource(options.source);
  const age = adminBankReconciliationAge(options.age);
  const query = normalizeNullable(options.q);
  const review = normalizeNullable(options.review ?? options.status)?.toLowerCase();
  if (dateRange) {
    filters.push(
      Prisma.sql`bank."occurredAt" >= ${dateRange.gte as Date} AND bank."occurredAt" <= ${dateRange.lte as Date}`,
    );
  }
  if (periodRange) {
    filters.push(
      Prisma.sql`bank."occurredAt" >= ${periodRange.gte} AND bank."occurredAt" < ${periodRange.lt}`,
    );
  }
  switch (review) {
    case 'needs-action':
    case 'unmatched':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.UNMATCHED}::"BankReconciliationStatus"`,
      );
      break;
    case 'matched':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.MATCHED}::"BankReconciliationStatus"`,
      );
      break;
    case 'partial':
    case 'partially-matched':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"`,
      );
      break;
    case 'ignored':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.IGNORED}::"BankReconciliationStatus"`,
      );
      break;
    case 'reversed':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.REVERSED}::"BankReconciliationStatus"`,
      );
      break;
    case 'inflow':
      filters.push(
        Prisma.sql`bank."type" = ${CompanyBankTransactionType.INFLOW}::"CompanyBankTransactionType"`,
      );
      break;
    case 'outflow':
      filters.push(
        Prisma.sql`bank."type" = ${CompanyBankTransactionType.OUTFLOW}::"CompanyBankTransactionType"`,
      );
      break;
  }
  if (transactionType) {
    filters.push(Prisma.sql`bank."type" = ${transactionType}::"CompanyBankTransactionType"`);
  }
  if (evidenceSource) {
    filters.push(adminBankReconciliationEvidenceSourceSql(evidenceSource));
  }
  if (age === '48h') {
    filters.push(Prisma.sql`bank."occurredAt" <= CURRENT_TIMESTAMP - INTERVAL '48 hours'`);
  }
  if (query) {
    const contains = `%${query}%`;
    filters.push(Prisma.sql`(
      bank."transferRef" ILIKE ${contains}
      OR bank."counterpartyName" ILIKE ${contains}
      OR bank."description" ILIKE ${contains}
      OR bank."sourceKey" ILIKE ${contains}
    )`);
  }
  return filters.length > 0 ? Prisma.join(filters, ' AND ') : Prisma.sql`TRUE`;
}

function adminBankReconciliationReviewOwnerWorkloadSet(options: AdminPaymentOperationsQuery) {
  const withdrawalCandidate = adminBankReconciliationWithdrawalCandidate(options.candidate);
  if (withdrawalCandidate) {
    const candidateSet = adminBankReconciliationWithdrawalCandidateSet(options);
    const candidateWhere = adminBankReconciliationWithdrawalCandidateResultWhere(withdrawalCandidate);
    return Prisma.sql`
      WITH withdrawal_candidates AS (${candidateSet})
      SELECT
        candidates."bankTransactionId" AS "id",
        candidates."amount",
        candidates."occurredAt"
      FROM withdrawal_candidates candidates
      WHERE ${candidateWhere}
    `;
  }

  return Prisma.sql`
    SELECT bank."id", bank."amount", bank."occurredAt"
    FROM "CompanyBankTransaction" bank
    WHERE ${adminBankReconciliationSqlWhere(options)}
      AND bank."status" IN (
        ${BankReconciliationStatus.UNMATCHED}::"BankReconciliationStatus",
        ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
      )
  `;
}

function adminBankReconciliationEvidenceSourceFilteredBankSql(options: AdminPaymentOperationsQuery) {
  const sourceNeutralOptions: AdminPaymentOperationsQuery = {
    ...options,
    source: undefined,
  };
  const withdrawalCandidate = adminBankReconciliationWithdrawalCandidate(options.candidate);
  if (withdrawalCandidate) {
    const candidateSet = adminBankReconciliationWithdrawalCandidateSet(sourceNeutralOptions);
    const candidateWhere = adminBankReconciliationWithdrawalCandidateResultWhere(withdrawalCandidate);
    const assignmentWhere = adminBankReconciliationReviewAssignmentWhere(sourceNeutralOptions);
    return Prisma.sql`
      WITH withdrawal_candidates AS (${candidateSet}),
      filtered_bank AS (
        SELECT bank."id", bank."amount"
        FROM withdrawal_candidates candidates
        INNER JOIN "CompanyBankTransaction" bank
          ON bank."id" = candidates."bankTransactionId"
        ${adminBankReconciliationLatestReviewAssignmentJoinSql()}
        WHERE ${candidateWhere}
          AND ${assignmentWhere}
      )
    `;
  }

  return Prisma.sql`
    WITH filtered_bank AS (
      SELECT bank."id", bank."amount"
      FROM "CompanyBankTransaction" bank
      ${adminBankReconciliationLatestReviewAssignmentForBankJoinSql()}
      WHERE ${adminBankReconciliationSqlWhere(sourceNeutralOptions)}
        AND ${adminBankReconciliationReviewAssignmentWhere(sourceNeutralOptions)}
    )
  `;
}

function adminBankReconciliationQueueRow<
  T extends {
    amount: unknown;
    reconciliationMatches?: ReadonlyArray<{
      accountingJournalEntryId?: string | null;
      amount: unknown;
      paymentClearingEntryId?: string | null;
      payoutBatchId?: string | null;
      status?: BankReconciliationStatus;
      withdrawalRequestId?: string | null;
      accountingJournalEntry?: {
        batch?: {
          sourceType?: AccountingJournalSourceType | null;
        } | null;
      } | null;
    }>;
  },
>(transaction: T) {
  const { reconciliationMatches = [], ...row } = transaction;
  const activeMatches = reconciliationMatches.filter(
    (match) =>
      match.status === undefined ||
      match.status === BankReconciliationStatus.MATCHED ||
      match.status === BankReconciliationStatus.PARTIALLY_MATCHED,
  );
  const reconciliationMatchedAmount = activeMatches.reduce(
    (total, match) => total + numberValue(match.amount),
    0,
  );
  return {
    ...row,
    reconciliationActiveMatchCount: activeMatches.length,
    reconciliationMatchedAmount,
    reconciliationRemainingAmount: numberValue(transaction.amount) - reconciliationMatchedAmount,
    reconciliationReversedMatchCount: reconciliationMatches.filter(
      (match) => match.status === BankReconciliationStatus.REVERSED,
    ).length,
    reconciliationSources: bankReconciliationEvidenceSources(activeMatches),
  };
}

function bankReconciliationEvidenceSources(
  matches: ReadonlyArray<{
    accountingJournalEntryId?: string | null;
    paymentClearingEntryId?: string | null;
    payoutBatchId?: string | null;
    withdrawalRequestId?: string | null;
    accountingJournalEntry?: {
      batch?: {
        sourceType?: AccountingJournalSourceType | null;
      } | null;
    } | null;
  }>,
): AdminBankReconciliationEvidenceSource[] {
  const sources = new Set<AdminBankReconciliationEvidenceSource>();
  for (const match of matches) {
    const journalSourceType = match.accountingJournalEntry?.batch?.sourceType;
    if (match.paymentClearingEntryId) sources.add('PAYMENT_CLEARING');
    if (match.withdrawalRequestId) sources.add('WITHDRAWAL');
    if (match.payoutBatchId || journalSourceType === AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH) {
      sources.add('PAYOUT');
    }
    if (journalSourceType === AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT) {
      sources.add('PARTNER_DEPOSIT');
    }
    if (journalSourceType === AccountingJournalSourceType.REFUND) {
      sources.add('REFUND');
    }
    if (
      match.accountingJournalEntryId &&
      !match.paymentClearingEntryId &&
      !match.withdrawalRequestId &&
      !match.payoutBatchId &&
      journalSourceType !== AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT &&
      journalSourceType !== AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH &&
      journalSourceType !== AccountingJournalSourceType.REFUND
    ) {
      sources.add('OTHER_JOURNAL');
    }
  }
  return sources.size > 0 ? [...sources] : ['UNCLASSIFIED'];
}

function adminBankReconciliationLatestReviewAssignmentForBankJoinSql() {
  return Prisma.sql`
    LEFT JOIN LATERAL (
      SELECT assignment_log."metadata", assignment_log."createdAt"
      FROM "AdminAuditLog" assignment_log
      WHERE assignment_log."action" = ${COMPANY_BANK_TRANSACTION_REVIEW_ASSIGNMENT_ACTION}
        AND assignment_log."target" = 'bank_transaction:' || bank."id"
      ORDER BY assignment_log."createdAt" DESC, assignment_log."id" DESC
      LIMIT 1
    ) assignment ON TRUE
  `;
}

function adminBankReconciliationWithdrawalCandidate(
  value: string | null | undefined,
): AdminBankReconciliationWithdrawalCandidate | undefined {
  switch (normalizeNullable(value)?.toLowerCase()) {
    case 'eligible':
      return 'eligible';
    case 'none':
      return 'none';
    case 'review':
      return 'review';
    case 'strong':
      return 'strong';
    default:
      return undefined;
  }
}

function adminBankReconciliationWithdrawalCandidateSet(options: AdminPaymentOperationsQuery) {
  const filters: Prisma.Sql[] = [
    Prisma.sql`bank."type" = ${CompanyBankTransactionType.OUTFLOW}::"CompanyBankTransactionType"`,
    Prisma.sql`bank."status" IN (
      ${BankReconciliationStatus.UNMATCHED}::"BankReconciliationStatus",
      ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
    )`,
  ];
  const bounds = adminPaymentDateRangeBounds(options.range);
  if (bounds) {
    filters.push(
      Prisma.sql`bank."occurredAt" BETWEEN ${new Date(bounds.startMs)} AND ${new Date(bounds.endMs)}`,
    );
  }
  const review = normalizeNullable(options.review ?? options.status)?.toLowerCase();
  switch (review) {
    case 'needs-action':
    case 'unmatched':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.UNMATCHED}::"BankReconciliationStatus"`,
      );
      break;
    case 'partial':
    case 'partially-matched':
      filters.push(
        Prisma.sql`bank."status" = ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"`,
      );
      break;
    case 'matched':
    case 'ignored':
    case 'reversed':
    case 'inflow':
      filters.push(Prisma.sql`FALSE`);
      break;
    default:
      break;
  }
  const transactionType = adminBankReconciliationTransactionType(options.type);
  if (transactionType === CompanyBankTransactionType.INFLOW) {
    filters.push(Prisma.sql`FALSE`);
  }
  const evidenceSource = adminBankReconciliationEvidenceSource(options.source);
  if (evidenceSource) {
    filters.push(adminBankReconciliationEvidenceSourceSql(evidenceSource));
  }
  if (adminBankReconciliationAge(options.age) === '48h') {
    filters.push(Prisma.sql`bank."occurredAt" <= CURRENT_TIMESTAMP - INTERVAL '48 hours'`);
  }
  const query = normalizeNullable(options.q);
  if (query) {
    const queryPattern = `%${query.replace(/[!%_]/g, '!$&')}%`;
    filters.push(Prisma.sql`(
      bank."transferRef" ILIKE ${queryPattern} ESCAPE '!'
      OR bank."counterpartyName" ILIKE ${queryPattern} ESCAPE '!'
      OR bank."description" ILIKE ${queryPattern} ESCAPE '!'
      OR bank."sourceKey" ILIKE ${queryPattern} ESCAPE '!'
    )`);
  }

  return Prisma.sql`
    SELECT
      bank."id" AS "bankTransactionId",
      bank."amount",
      bank."occurredAt",
      bank."status",
      COUNT(withdrawal."id")::bigint AS "candidateCount",
      COUNT(withdrawal."id") FILTER (
        WHERE (
          bank."transferRef" IS NOT NULL
          AND withdrawal."transferRef" IS NOT NULL
          AND UPPER(TRIM(bank."transferRef")) = UPPER(TRIM(withdrawal."transferRef"))
        ) OR (
          withdrawal."amount" = bank."amount"
          AND ABS(EXTRACT(EPOCH FROM (
            COALESCE(withdrawal."paidAt", withdrawal."createdAt") - bank."occurredAt"
          ))) <= ${3 * 24 * 60 * 60}
        )
      )::bigint AS "strongCount"
    FROM "CompanyBankTransaction" bank
    LEFT JOIN "ProviderWalletWithdrawalRequest" withdrawal
      ON withdrawal."status" = ${ProviderWalletWithdrawalRequestStatus.PAID}::"ProviderWalletWithdrawalRequestStatus"
      AND withdrawal."currency" = bank."currency"
      AND COALESCE(withdrawal."paidAt", withdrawal."createdAt") BETWEEN
        bank."occurredAt" - INTERVAL '30 days'
        AND bank."occurredAt" + INTERVAL '30 days'
      AND (
        ABS(withdrawal."amount" - bank."amount") <= GREATEST(
          10000,
          LEAST(100000, ROUND(bank."amount" * 0.1))
        )
        OR (
          bank."transferRef" IS NOT NULL
          AND withdrawal."transferRef" IS NOT NULL
          AND UPPER(TRIM(bank."transferRef")) = UPPER(TRIM(withdrawal."transferRef"))
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM "BankReconciliationMatch" active_match
        WHERE active_match."withdrawalRequestId" = withdrawal."id"
          AND active_match."status" IN (
            ${BankReconciliationStatus.MATCHED}::"BankReconciliationStatus",
            ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
          )
      )
    WHERE ${Prisma.join(filters, ' AND ')}
    GROUP BY bank."id"
  `;
}

function adminBankReconciliationWithdrawalCandidateResultWhere(
  candidate: AdminBankReconciliationWithdrawalCandidate,
) {
  switch (candidate) {
    case 'eligible':
      return Prisma.sql`TRUE`;
    case 'strong':
      return Prisma.sql`candidates."strongCount" > 0`;
    case 'review':
      return Prisma.sql`candidates."candidateCount" > 0 AND candidates."strongCount" = 0`;
    case 'none':
      return Prisma.sql`candidates."candidateCount" = 0`;
  }
}

function adminBankReconciliationLatestReviewAssignmentJoinSql() {
  return Prisma.sql`
    LEFT JOIN LATERAL (
      SELECT assignment_log."metadata", assignment_log."createdAt"
      FROM "AdminAuditLog" assignment_log
      WHERE assignment_log."action" = ${COMPANY_BANK_TRANSACTION_REVIEW_ASSIGNMENT_ACTION}
        AND assignment_log."target" = 'bank_transaction:' || candidates."bankTransactionId"
      ORDER BY assignment_log."createdAt" DESC, assignment_log."id" DESC
      LIMIT 1
    ) assignment ON TRUE
  `;
}

function adminBankReconciliationReviewAssignmentWhere(options: AdminPaymentOperationsQuery) {
  const assigneeAdminId = normalizeNullable(options.assigneeAdminId);
  if (assigneeAdminId) {
    return Prisma.sql`assignment."metadata"->>'assigneeAdminId' = ${assigneeAdminId}`;
  }
  switch (normalizeNullable(options.assignment)?.toLowerCase()) {
    case 'assigned':
      return Prisma.sql`assignment."metadata"->>'assigneeAdminId' IS NOT NULL`;
    case 'unassigned':
      return Prisma.sql`assignment."metadata"->>'assigneeAdminId' IS NULL`;
    default:
      return Prisma.sql`TRUE`;
  }
}

function adminBankReconciliationAssignmentSummaryRows(value: Prisma.JsonValue | null | undefined) {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item) => {
    const record = jsonObject(item);
    const assigneeAdminId = jsonString(record.assigneeAdminId);
    if (!assigneeAdminId) return [];
    return [
      {
        assigneeAdminId,
        count: jsonNonNegativeInteger(record.count),
        over24hCount: jsonNonNegativeInteger(record.over24hCount),
        over48hCount: jsonNonNegativeInteger(record.over48hCount),
      },
    ];
  });
}

function bankReconciliationWithdrawalRecommendationEvidence(
  bankTransaction: {
    readonly amount: number;
    readonly occurredAt: Date;
    readonly transferRef: string | null;
  },
  withdrawal: {
    readonly amount: number;
    readonly createdAt: Date;
    readonly paidAt: Date | null;
    readonly transferRef: string | null;
  },
) {
  const withdrawalEvidenceAt = withdrawal.paidAt ?? withdrawal.createdAt;
  const amountDelta = Math.abs(withdrawal.amount - bankTransaction.amount);
  const dateDeltaDays =
    Math.round(
      (Math.abs(withdrawalEvidenceAt.getTime() - bankTransaction.occurredAt.getTime()) / (24 * 60 * 60_000)) *
        10,
    ) / 10;
  const bankTransferRef = normalizeNullable(bankTransaction.transferRef)?.toUpperCase() ?? null;
  const withdrawalTransferRef = normalizeNullable(withdrawal.transferRef)?.toUpperCase() ?? null;
  const transferRefMatch = Boolean(
    bankTransferRef && withdrawalTransferRef && bankTransferRef === withdrawalTransferRef,
  );
  const exactAmount = amountDelta === 0;

  return {
    amountDelta,
    bankOccurredAt: bankTransaction.occurredAt.toISOString(),
    bankTransferRef,
    confidence: transferRefMatch || (exactAmount && dateDeltaDays <= 3) ? 'STRONG' : 'REVIEW',
    dateDeltaDays,
    exactAmount,
    rankingVersion: 'withdrawal-candidate-v1',
    source: 'SERVER_RECOMPUTED',
    transferRefMatch,
    withdrawalEvidenceAt: withdrawalEvidenceAt.toISOString(),
    withdrawalTransferRef,
  };
}

function adminBankReconciliationReviewWhere(
  review: string | null | undefined,
): Prisma.CompanyBankTransactionWhereInput | undefined {
  switch (normalizeNullable(review)?.toLowerCase()) {
    case 'needs-action':
    case 'unmatched':
      return { status: BankReconciliationStatus.UNMATCHED };
    case 'matched':
      return { status: BankReconciliationStatus.MATCHED };
    case 'partial':
    case 'partially-matched':
      return { status: BankReconciliationStatus.PARTIALLY_MATCHED };
    case 'ignored':
      return { status: BankReconciliationStatus.IGNORED };
    case 'reversed':
      return { status: BankReconciliationStatus.REVERSED };
    case 'inflow':
      return { type: CompanyBankTransactionType.INFLOW };
    case 'outflow':
      return { type: CompanyBankTransactionType.OUTFLOW };
    default:
      return undefined;
  }
}

function adminBankReconciliationQueueOldestFirst(review: string | null | undefined) {
  switch (normalizeNullable(review)?.toLowerCase()) {
    case 'needs-action':
    case 'unmatched':
    case 'partial':
    case 'partially-matched':
      return true;
    default:
      return false;
  }
}

function adminBankReconciliationTransactionType(
  value: string | null | undefined,
): CompanyBankTransactionType | undefined {
  const normalized = normalizeNullable(value)?.toUpperCase();
  if (!normalized) return undefined;
  return companyBankTransactionType(normalized);
}

function adminBankReconciliationAge(value: string | null | undefined) {
  const normalized = normalizeNullable(value)?.toLowerCase();
  if (!normalized) return undefined;
  if (normalized === '48h') return '48h' as const;
  throw new BadRequestException('Valid bank reconciliation age is required');
}

function adminBankReconciliationEvidenceSource(
  value: string | null | undefined,
): AdminBankReconciliationEvidenceSource | undefined {
  const normalized = normalizeNullable(value)?.toUpperCase().replaceAll('-', '_');
  if (!normalized) return undefined;
  if (
    ADMIN_BANK_RECONCILIATION_EVIDENCE_SOURCES.includes(normalized as AdminBankReconciliationEvidenceSource)
  ) {
    return normalized as AdminBankReconciliationEvidenceSource;
  }
  throw new BadRequestException('Valid bank reconciliation evidence source is required');
}

function adminBankReconciliationEvidenceSourceWhere(
  source: AdminBankReconciliationEvidenceSource,
): Prisma.CompanyBankTransactionWhereInput {
  const activeStatus = {
    in: [BankReconciliationStatus.MATCHED, BankReconciliationStatus.PARTIALLY_MATCHED],
  };
  const journalSourceType = (sourceType: AccountingJournalSourceType) => ({
    accountingJournalEntry: {
      is: {
        batch: {
          is: { sourceType },
        },
      },
    },
  });

  switch (source) {
    case 'PAYMENT_CLEARING':
      return {
        reconciliationMatches: {
          some: { paymentClearingEntryId: { not: null }, status: activeStatus },
        },
      };
    case 'PARTNER_DEPOSIT':
      return {
        reconciliationMatches: {
          some: {
            ...journalSourceType(AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT),
            status: activeStatus,
          },
        },
      };
    case 'WITHDRAWAL':
      return {
        reconciliationMatches: {
          some: { withdrawalRequestId: { not: null }, status: activeStatus },
        },
      };
    case 'PAYOUT':
      return {
        reconciliationMatches: {
          some: {
            status: activeStatus,
            OR: [
              { payoutBatchId: { not: null } },
              journalSourceType(AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH),
            ],
          },
        },
      };
    case 'REFUND':
      return {
        reconciliationMatches: {
          some: {
            ...journalSourceType(AccountingJournalSourceType.REFUND),
            status: activeStatus,
          },
        },
      };
    case 'OTHER_JOURNAL':
      return {
        reconciliationMatches: {
          some: {
            accountingJournalEntryId: { not: null },
            paymentClearingEntryId: null,
            payoutBatchId: null,
            withdrawalRequestId: null,
            status: activeStatus,
            accountingJournalEntry: {
              is: {
                batch: {
                  is: {
                    sourceType: {
                      notIn: [
                        AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT,
                        AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH,
                        AccountingJournalSourceType.REFUND,
                      ],
                    },
                  },
                },
              },
            },
          },
        },
      };
    case 'UNCLASSIFIED':
      return {
        reconciliationMatches: {
          none: { status: activeStatus },
        },
      };
  }
}

function adminBankReconciliationEvidenceSourceSql(source: AdminBankReconciliationEvidenceSource): Prisma.Sql {
  const activeMatch = Prisma.sql`match."status" IN (
    ${BankReconciliationStatus.MATCHED}::"BankReconciliationStatus",
    ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
  )`;
  const journalSource = (sourceType: AccountingJournalSourceType) => Prisma.sql`
    EXISTS (
      SELECT 1
      FROM "BankReconciliationMatch" match
      INNER JOIN "AccountingJournalEntry" entry ON entry."id" = match."accountingJournalEntryId"
      INNER JOIN "AccountingJournalBatch" batch ON batch."id" = entry."batchId"
      WHERE match."bankTransactionId" = bank."id"
        AND ${activeMatch}
        AND batch."sourceType" = ${sourceType}::"AccountingJournalSourceType"
    )
  `;

  switch (source) {
    case 'PAYMENT_CLEARING':
      return Prisma.sql`EXISTS (
        SELECT 1
        FROM "BankReconciliationMatch" match
        WHERE match."bankTransactionId" = bank."id"
          AND ${activeMatch}
          AND match."paymentClearingEntryId" IS NOT NULL
      )`;
    case 'PARTNER_DEPOSIT':
      return journalSource(AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT);
    case 'WITHDRAWAL':
      return Prisma.sql`EXISTS (
        SELECT 1
        FROM "BankReconciliationMatch" match
        WHERE match."bankTransactionId" = bank."id"
          AND ${activeMatch}
          AND match."withdrawalRequestId" IS NOT NULL
      )`;
    case 'PAYOUT':
      return Prisma.sql`EXISTS (
        SELECT 1
        FROM "BankReconciliationMatch" match
        LEFT JOIN "AccountingJournalEntry" entry ON entry."id" = match."accountingJournalEntryId"
        LEFT JOIN "AccountingJournalBatch" batch ON batch."id" = entry."batchId"
        WHERE match."bankTransactionId" = bank."id"
          AND ${activeMatch}
          AND (
            match."payoutBatchId" IS NOT NULL
            OR batch."sourceType" = ${AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH}::"AccountingJournalSourceType"
          )
      )`;
    case 'REFUND':
      return journalSource(AccountingJournalSourceType.REFUND);
    case 'OTHER_JOURNAL':
      return Prisma.sql`EXISTS (
        SELECT 1
        FROM "BankReconciliationMatch" match
        INNER JOIN "AccountingJournalEntry" entry ON entry."id" = match."accountingJournalEntryId"
        INNER JOIN "AccountingJournalBatch" batch ON batch."id" = entry."batchId"
        WHERE match."bankTransactionId" = bank."id"
          AND ${activeMatch}
          AND match."paymentClearingEntryId" IS NULL
          AND match."withdrawalRequestId" IS NULL
          AND match."payoutBatchId" IS NULL
          AND batch."sourceType" NOT IN (
            ${AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT}::"AccountingJournalSourceType",
            ${AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH}::"AccountingJournalSourceType",
            ${AccountingJournalSourceType.REFUND}::"AccountingJournalSourceType"
          )
      )`;
    case 'UNCLASSIFIED':
      return Prisma.sql`NOT EXISTS (
        SELECT 1
        FROM "BankReconciliationMatch" match
        WHERE match."bankTransactionId" = bank."id"
          AND ${activeMatch}
      )`;
  }
}

function companyBankTransactionType(value: string | CompanyBankTransactionType) {
  if (Object.values(CompanyBankTransactionType).includes(value as CompanyBankTransactionType)) {
    return value as CompanyBankTransactionType;
  }
  throw new BadRequestException('Valid bank transaction type is required');
}

function normalizeCompanyBankAccountIdentity(input: {
  accountNumberLast4: string;
  accountNumberMasked?: string | null;
  bankName: string;
  currency: string;
  name: string;
}) {
  const name = normalizeNullable(input.name);
  const bankName = normalizeNullable(input.bankName);
  const accountNumberLast4 = typeof input.accountNumberLast4 === 'string' ? input.accountNumberLast4 : '';
  const currency = normalizeNullable(input.currency)?.toUpperCase();
  if (!name || !bankName) {
    throw new BadRequestException('Company bank account name and bank name are required');
  }
  if (!/^[0-9]{4}$/u.test(accountNumberLast4)) {
    throw new BadRequestException({
      code: 'COMPANY_BANK_ACCOUNT_INVALID_LAST4',
      field: 'accountNumberLast4',
      message: 'Enter exactly four ASCII digits',
    });
  }
  if (!currency || !/^[A-Z]{3}$/u.test(currency)) {
    throw new BadRequestException('Company bank account currency must be a three-letter code');
  }
  if (input.accountNumberMasked !== undefined && input.accountNumberMasked !== null) {
    throw new BadRequestException({
      code: 'COMPANY_BANK_ACCOUNT_RAW_NUMBER_REJECTED',
      field: 'accountNumberMasked',
      message: 'Masked account numbers are server-managed; send only the last four digits',
    });
  }
  return {
    accountNumberLast4,
    accountNumberMasked: `•••• ${accountNumberLast4}`,
    bankName,
    currency,
    name,
  };
}

function normalizeCompanyBankAccountIdempotencyKey(value: string | null | undefined) {
  const normalized = normalizeNullable(value);
  if (!normalized || !/^[A-Za-z0-9:_-]{8,128}$/u.test(normalized)) {
    throw new BadRequestException({
      code: 'COMPANY_BANK_ACCOUNT_INVALID_IDEMPOTENCY_KEY',
      field: 'idempotencyKey',
      message: 'A stable idempotency key is required',
    });
  }
  return normalized;
}

function normalizeCompanyBankAccountOperatorReason(value: string) {
  const normalized = value.trim();
  if (/[0-9]{6,}/u.test(normalized)) {
    throw new BadRequestException({
      code: 'COMPANY_BANK_ACCOUNT_RAW_NUMBER_REJECTED',
      field: 'operatorReason',
      message: 'Do not include a full account number in Finance evidence text',
    });
  }
  return normalized;
}

function companyBankAccountMutationHash(input: {
  operation: 'CREATE' | 'UPDATE';
  operatorReason: string;
  proposed: CompanyBankAccountApprovalSnapshot;
  replacementAccountId: string | null;
}) {
  return createHash('sha256').update(adminCanonicalJson(input)).digest('hex');
}

function companyBankAccountEvidenceHash(input: {
  accountId: string;
  contentSha256: string;
  evidenceId: string;
  fileAssetId: string;
  kind: CompanyBankAccountEvidenceKind;
  version: number;
}) {
  return createHash('sha256').update(adminCanonicalJson(input)).digest('hex');
}

function assertCompanyBankAccountIdempotencyHash(existingHash: string | null, requestedHash: string) {
  if (existingHash === requestedHash) return;
  throw new ConflictException({
    code: 'COMPANY_BANK_ACCOUNT_IDEMPOTENCY_CONFLICT',
    message: 'The idempotency key was already used with a different company bank account request',
  });
}

function assertControlledCompanyBankAccountIdentity(bankCode: string, bankName: string) {
  const names: Record<string, string> = {
    ACB: 'ACB',
    BIDV: 'BIDV',
    MBB: 'MB Bank',
    TCB: 'Techcombank',
    VCB: 'Vietcombank',
  };
  const expected = names[bankCode];
  if (
    expected &&
    (expected.toLocaleLowerCase('en') === bankName.toLocaleLowerCase('en') ||
      bankCode.toLocaleLowerCase('en') === bankName.toLocaleLowerCase('en'))
  )
    return;
  throw new BadRequestException({
    code: 'COMPANY_BANK_ACCOUNT_BANK_IDENTITY_MISMATCH',
    field: 'bankName',
    message: 'Bank name must match the selected controlled bank code',
  });
}

function normalizeCompanyBankTransactionCurrency(
  value: string | null | undefined,
  fallback: string | null | undefined,
) {
  return (normalizeNullable(value) ?? fallback ?? 'VND').toUpperCase();
}

function companyBankTransactionSourceKey(input: {
  amount: number;
  bankAccountId: string;
  occurredAt: Date;
  sourceKey?: string | null;
  transferRef?: string | null;
  type: CompanyBankTransactionType;
}) {
  const sourceKey = normalizeNullable(input.sourceKey);
  if (sourceKey) {
    return sourceKey;
  }
  const transferRef = normalizeNullable(input.transferRef);
  const uniquePart = transferRef ?? `${input.occurredAt.toISOString()}:${input.amount}`;
  return `manual-bank-transaction:${input.bankAccountId}:${input.type}:${uniquePart}`;
}

function companyBankTransactionDuplicateCandidateWhere(input: {
  amount: number;
  bankAccountId: string;
  counterpartyName: string | null;
  currency: string;
  occurredAt: Date;
  transferRef: string | null;
  type: CompanyBankTransactionType;
}): Prisma.CompanyBankTransactionWhereInput {
  const oneDayMs = 24 * 60 * 60 * 1000;
  const sameEconomicEvent: Prisma.CompanyBankTransactionWhereInput = {
    amount: input.amount,
    occurredAt: {
      gte: new Date(input.occurredAt.getTime() - oneDayMs),
      lte: new Date(input.occurredAt.getTime() + oneDayMs),
    },
    ...(input.counterpartyName
      ? { counterpartyName: { equals: input.counterpartyName, mode: Prisma.QueryMode.insensitive } }
      : {}),
  };
  const candidateSignals: Prisma.CompanyBankTransactionWhereInput[] = [sameEconomicEvent];
  if (input.transferRef) {
    candidateSignals.unshift({
      transferRef: { equals: input.transferRef, mode: Prisma.QueryMode.insensitive },
    });
  }

  return {
    bankAccountId: input.bankAccountId,
    currency: input.currency,
    type: input.type,
    OR: candidateSignals,
  };
}

function batchCompanyBankTransactionType(value: string) {
  const normalized = value.trim().toUpperCase();
  return Object.values(CompanyBankTransactionType).includes(normalized as CompanyBankTransactionType)
    ? (normalized as CompanyBankTransactionType)
    : null;
}

function parseCompanyBankTransactionBatchAmount(value: string) {
  const unsigned = value.trim().replace(/VND/giu, '').replace(/[₫\s]/gu, '').replace(/^\+/u, '');
  let normalized = unsigned;
  if (/^\d{1,3}(?:[.,]\d{3})+$/u.test(unsigned)) {
    normalized = unsigned.replace(/[.,]/gu, '');
  } else if (/^\d+[.,]00$/u.test(unsigned)) {
    normalized = unsigned.slice(0, -3);
  }
  if (!/^\d+$/u.test(normalized)) {
    return null;
  }
  const amount = Number(normalized);
  return Number.isSafeInteger(amount) && amount > 0 && amount <= 10_000_000_000 ? amount : null;
}

function parseCompanyBankTransactionBatchDate(value: string) {
  const normalized = value.trim();
  if (!normalized) {
    return null;
  }
  if (/T.*(?:Z|[+-]\d{2}:?\d{2})$/u.test(normalized)) {
    const date = new Date(normalized);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  const dayFirst = normalized.match(
    /^(\d{1,2})[/-](\d{1,2})[/-](\d{4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?$/u,
  );
  if (dayFirst) {
    return vietnamLocalDate({
      day: Number(dayFirst[1]),
      hour: Number(dayFirst[4] ?? 0),
      minute: Number(dayFirst[5] ?? 0),
      month: Number(dayFirst[2]),
      second: Number(dayFirst[6] ?? 0),
      year: Number(dayFirst[3]),
    });
  }
  const yearFirst = normalized.match(
    /^(\d{4})[/-](\d{1,2})[/-](\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d{1,3})?)?)?$/u,
  );
  if (!yearFirst) {
    return null;
  }
  return vietnamLocalDate({
    day: Number(yearFirst[3]),
    hour: Number(yearFirst[4] ?? 0),
    minute: Number(yearFirst[5] ?? 0),
    month: Number(yearFirst[2]),
    second: Number(yearFirst[6] ?? 0),
    year: Number(yearFirst[1]),
  });
}

