function jsonString(value: Prisma.JsonValue | undefined) {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function jsonNonNegativeInteger(value: Prisma.JsonValue | undefined) {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : 0;
}

function jsonPositiveInteger(value: Prisma.JsonValue | undefined) {
  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0 ? value : null;
}

function jsonSha256(value: Prisma.JsonValue | undefined) {
  const normalized = jsonString(value)?.toLowerCase() ?? null;
  return normalized && /^[a-f0-9]{64}$/u.test(normalized) ? normalized : null;
}

function normalizeRequiredId(value: string | null | undefined, label: string) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    throw new BadRequestException(`${label} is required`);
  }
  return normalized;
}

function requiredAdminDate(value: string | Date | null | undefined, label: string) {
  const date = optionalAdminDate(value, label);
  if (!date) {
    throw new BadRequestException(`${label} is required`);
  }
  return date;
}

function optionalAdminDate(value: string | Date | null | undefined, label: string) {
  if (!value) {
    return null;
  }
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new BadRequestException(`${label} must be a valid date`);
  }
  return date;
}

type AdminBankReconciliationMatchSource = {
  readonly field:
    | 'accountingJournalEntryId'
    | 'paymentClearingEntryId'
    | 'withdrawalRequestId'
    | 'payoutBatchId';
  readonly id: string;
  readonly key: string;
  readonly type:
    | 'accounting-journal'
    | 'partner-bank-deposit'
    | 'payment-clearing'
    | 'withdrawal'
    | 'payout-batch';
  readonly accountingJournalEntryId?: string;
  readonly partnerBankDepositRequestId?: string;
  readonly payoutBatchId?: string;
};

function adminBankReconciliationMatchSource(
  input: CreateBankReconciliationMatchDto,
): AdminBankReconciliationMatchSource {
  const candidates: AdminBankReconciliationMatchSource[] = [
    {
      field: 'accountingJournalEntryId',
      id: normalizeNullable(input.accountingJournalEntryId) ?? '',
      key: 'accounting-journal',
      type: 'accounting-journal',
    },
    {
      field: 'accountingJournalEntryId',
      id: normalizeNullable(input.partnerBankDepositRequestId) ?? '',
      key: 'partner-bank-deposit',
      type: 'partner-bank-deposit',
    },
    {
      field: 'paymentClearingEntryId',
      id: normalizeNullable(input.paymentClearingEntryId) ?? '',
      key: 'payment-clearing',
      type: 'payment-clearing',
    },
    {
      field: 'withdrawalRequestId',
      id: normalizeNullable(input.withdrawalRequestId) ?? '',
      key: 'withdrawal',
      type: 'withdrawal',
    },
    {
      field: 'payoutBatchId',
      id: normalizeNullable(input.payoutBatchId) ?? '',
      key: 'payout-batch',
      type: 'payout-batch',
    },
  ];
  const sources = candidates.filter((source) => source.id.length > 0);

  if (sources.length !== 1) {
    throw new BadRequestException('Select exactly one reconciliation source');
  }

  return sources[0]!;
}

function bankReconciliationMatchSourceKey(
  bankTransactionId: string,
  source: AdminBankReconciliationMatchSource,
) {
  return `bank-reconciliation-match:${bankTransactionId}:${source.key}:${source.id}`;
}

function bankReconciliationStatusForAmount(matchedAmount: number, transactionAmount: number) {
  const matched = Math.abs(matchedAmount);
  const target = Math.abs(transactionAmount);
  if (matched <= 0) {
    return BankReconciliationStatus.UNMATCHED;
  }
  return matched >= target ? BankReconciliationStatus.MATCHED : BankReconciliationStatus.PARTIALLY_MATCHED;
}

function bookingPaymentClearingStatusForAmount(matchedAmount: number, clearingAmount: number) {
  const matched = Math.abs(matchedAmount);
  const target = Math.abs(clearingAmount);
  if (matched <= 0) {
    return BookingPaymentClearingStatus.OPEN;
  }
  return matched >= target
    ? BookingPaymentClearingStatus.CLEARED
    : BookingPaymentClearingStatus.PARTIALLY_CLEARED;
}

function activeBankReconciliationMatchedAmount(
  matches: readonly { readonly amount: number; readonly status?: BankReconciliationStatus }[],
) {
  return matches.reduce(
    (total, match) =>
      match.status === BankReconciliationStatus.REVERSED ? total : total + Math.abs(match.amount),
    0,
  );
}

function paymentClearingRemainingAmount(amount: number, matchedAmount: number) {
  return Math.max(0, Math.abs(amount) - Math.abs(matchedAmount));
}

function adminCouponFinanceSqlWhere(options: AdminPaymentOperationsQuery): Prisma.Sql {
  const conditions: Prisma.Sql[] = [
    Prisma.sql`("metadata" ? 'couponDiscountAmount' OR "metadata" ? 'couponCodeSnapshot' OR "metadata" ? 'couponId')`,
  ];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const period = normalizeOptionalAdminTaxPeriod(options.period);
  if (dateRange?.gte instanceof Date) {
    conditions.push(Prisma.sql`"postedAt" >= ${dateRange.gte}`);
  }
  if (dateRange?.lte instanceof Date) {
    conditions.push(Prisma.sql`"postedAt" <= ${dateRange.lte}`);
  }
  if (period) {
    conditions.push(Prisma.sql`"monthlyPeriod" = ${period}`);
  }

  const query = normalizeNullable(options.q);
  if (query) {
    const contains = `%${query}%`;
    conditions.push(Prisma.sql`(
      "bookingId" ILIKE ${contains}
      OR "providerProfileId" ILIKE ${contains}
      OR COALESCE("metadata"->>'couponCodeSnapshot', '') ILIKE ${contains}
      OR COALESCE("metadata"->>'couponId', '') ILIKE ${contains}
    )`);
  }

  const reviewSql = adminCouponFinanceReviewSql(options.review);
  if (reviewSql) {
    conditions.push(reviewSql);
  }

  return Prisma.sql`WHERE ${Prisma.join(conditions, ' AND ')}`;
}

function adminCouponFinanceActivityCteSql(options: AdminPaymentOperationsQuery) {
  return Prisma.sql`
    "couponSnapshots" AS NOT MATERIALIZED (
      SELECT *
      FROM "BookingSettlementSnapshot"
      ${adminCouponFinanceSqlWhere(options)}
    ),
    "couponReversals" AS NOT MATERIALIZED (
      SELECT *
      FROM "BookingSettlementReversalEntry"
      ${adminCouponFinanceReversalSqlWhere(options)}
    )
  `;
}

function adminCouponFinancePageSql(options: AdminPaymentOperationsQuery, take: number, skip: number) {
  return Prisma.sql`
    WITH
    ${adminCouponFinanceActivityCteSql(options)},
    "couponActivity" AS (
      SELECT
        snapshot."id",
        snapshot."postedAt" AS "activityAt",
        TRUE AS "grossIncluded",
        FALSE AS "correctionIncluded"
      FROM "couponSnapshots" snapshot
      UNION ALL
      SELECT
        reversal."originalSettlementSnapshotId" AS "id",
        reversal."occurredAt" AS "activityAt",
        FALSE AS "grossIncluded",
        TRUE AS "correctionIncluded"
      FROM "couponReversals" reversal
    )
    SELECT
      activity."id",
      BOOL_OR(activity."grossIncluded") AS "grossIncluded",
      BOOL_OR(activity."correctionIncluded") AS "correctionIncluded"
    FROM "couponActivity" activity
    GROUP BY activity."id"
    ORDER BY MAX(activity."activityAt") ${adminCouponFinanceSortSql(options.sort)}, activity."id" ${adminCouponFinanceSortSql(options.sort)}
    LIMIT ${take}
    OFFSET ${skip}
  `;
}

function adminCouponFinanceSummarySql(options: AdminPaymentOperationsQuery) {
  return Prisma.sql`
    WITH
    ${adminCouponFinanceActivityCteSql(options)},
    "couponSnapshotTotals" AS (
      SELECT
        COUNT(*)::bigint AS "couponSettlementCount",
        COUNT(*) FILTER (
          WHERE "settlementStatus" = ${BookingSettlementStatus.REVERSED}::"BookingSettlementStatus"
        )::bigint AS "reversedSnapshotCount",
        COALESCE(SUM(${adminJsonIntSql('bookingServiceAmount')}), 0)::bigint AS "bookingServiceAmount",
        COALESCE(SUM(${adminJsonIntSql('customerPaidAmount')}), 0)::bigint AS "customerPaidAmount",
        COALESCE(SUM(${adminJsonIntSql('settlementBaseAmount')}), 0)::bigint AS "settlementBaseAmount",
        COALESCE(SUM(${adminJsonIntSql('couponDiscountAmount')}), 0)::bigint AS "couponDiscountAmount",
        COALESCE(SUM(${adminJsonIntSql('companyCouponExpense')}), 0)::bigint AS "companyCouponExpense",
        COALESCE(SUM(${adminJsonIntSql('partnerFundedCouponAmount')}), 0)::bigint AS "partnerFundedCouponAmount",
        COALESCE(SUM(${adminJsonIntSql('platformFeeDiscountAmount')}), 0)::bigint AS "platformFeeDiscountAmount",
        COALESCE(SUM(${adminJsonIntSql('reversedCouponDiscountAmount')}), 0)::bigint AS "reversedCouponDiscountAmount",
        COALESCE(SUM(${adminJsonIntSql('reversedCompanyCouponExpense')}), 0)::bigint AS "reversedCompanyCouponExpense",
        COALESCE(SUM(${adminJsonIntSql('partnerFundedCouponAmount')}) FILTER (
          WHERE "settlementStatus" = ${BookingSettlementStatus.REVERSED}::"BookingSettlementStatus"
        ), 0)::bigint AS "reversedPartnerFundedCouponAmount",
        COALESCE(SUM(${adminJsonIntSql('platformFeeDiscountAmount')}) FILTER (
          WHERE "settlementStatus" = ${BookingSettlementStatus.REVERSED}::"BookingSettlementStatus"
        ), 0)::bigint AS "reversedPlatformFeeDiscountAmount",
        COUNT(*) FILTER (WHERE "metadata" ? 'couponReviewFlag')::bigint AS "couponReviewFlagCount"
      FROM "couponSnapshots"
    ),
    "couponReversalTotals" AS (
      SELECT
        COUNT(*)::bigint AS "couponReversalCount",
        COALESCE(SUM(${adminJsonIntSql('reversedCouponDiscountAmount')}), 0)::bigint AS "reversedCouponDiscountAmount",
        COALESCE(SUM(${adminJsonIntSql('reversedCompanyCouponExpense')}), 0)::bigint AS "reversedCompanyCouponExpense",
        COALESCE(SUM(${adminJsonIntSql('partnerFundedCouponAmount')}), 0)::bigint AS "reversedPartnerFundedCouponAmount",
        COALESCE(SUM(${adminJsonIntSql('platformFeeDiscountAmount')}), 0)::bigint AS "reversedPlatformFeeDiscountAmount"
      FROM "couponReversals"
    ),
    "couponOverlapTotals" AS (
      SELECT COUNT(*)::bigint AS "overlapCount"
      FROM "couponReversals" reversal
      INNER JOIN "couponSnapshots" snapshot
        ON snapshot."id" = reversal."originalSettlementSnapshotId"
    )
    SELECT
      snapshot."couponSettlementCount",
      (snapshot."couponSettlementCount" + reversal."couponReversalCount" - overlap."overlapCount")::bigint AS "couponActivityCount",
      (snapshot."reversedSnapshotCount" + reversal."couponReversalCount")::bigint AS "couponCorrectionCount",
      snapshot."bookingServiceAmount",
      snapshot."customerPaidAmount",
      snapshot."settlementBaseAmount",
      snapshot."couponDiscountAmount",
      snapshot."companyCouponExpense",
      snapshot."partnerFundedCouponAmount",
      snapshot."platformFeeDiscountAmount",
      (snapshot."reversedCouponDiscountAmount" + reversal."reversedCouponDiscountAmount")::bigint AS "reversedCouponDiscountAmount",
      (snapshot."reversedCompanyCouponExpense" + reversal."reversedCompanyCouponExpense")::bigint AS "reversedCompanyCouponExpense",
      (snapshot."reversedPartnerFundedCouponAmount" + reversal."reversedPartnerFundedCouponAmount")::bigint AS "reversedPartnerFundedCouponAmount",
      (snapshot."reversedPlatformFeeDiscountAmount" + reversal."reversedPlatformFeeDiscountAmount")::bigint AS "reversedPlatformFeeDiscountAmount",
      (snapshot."couponDiscountAmount" - snapshot."reversedCouponDiscountAmount" - reversal."reversedCouponDiscountAmount")::bigint AS "netCouponDiscountAmount",
      (snapshot."companyCouponExpense" - snapshot."reversedCompanyCouponExpense" - reversal."reversedCompanyCouponExpense")::bigint AS "netCompanyCouponExpense",
      (snapshot."partnerFundedCouponAmount" - snapshot."reversedPartnerFundedCouponAmount" - reversal."reversedPartnerFundedCouponAmount")::bigint AS "netPartnerFundedCouponAmount",
      (snapshot."platformFeeDiscountAmount" - snapshot."reversedPlatformFeeDiscountAmount" - reversal."reversedPlatformFeeDiscountAmount")::bigint AS "netPlatformFeeDiscountAmount",
      snapshot."couponReviewFlagCount"
    FROM "couponSnapshotTotals" snapshot
    CROSS JOIN "couponReversalTotals" reversal
    CROSS JOIN "couponOverlapTotals" overlap
  `;
}

export function adminCouponFinancePerformanceQueries(
  options: AdminPaymentOperationsQuery = {},
  take = 10,
  skip = 0,
) {
  return [
    { name: 'list-page', sql: adminCouponFinancePageSql(options, take, skip) },
    { name: 'summary-aggregate', sql: adminCouponFinanceSummarySql(options) },
  ] as const;
}

function adminCouponFinanceReversalSqlWhere(options: AdminPaymentOperationsQuery): Prisma.Sql {
  const conditions: Prisma.Sql[] = [
    Prisma.sql`(
      "metadata" ? 'reversedCouponDiscountAmount'
      OR "metadata" ? 'reversedCompanyCouponExpense'
      OR "metadata" ? 'couponCodeSnapshot'
      OR "metadata" ? 'couponId'
    )`,
  ];
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const period = normalizeOptionalAdminTaxPeriod(options.period);
  if (dateRange?.gte instanceof Date) conditions.push(Prisma.sql`"occurredAt" >= ${dateRange.gte}`);
  if (dateRange?.lte instanceof Date) conditions.push(Prisma.sql`"occurredAt" <= ${dateRange.lte}`);
  if (period) conditions.push(Prisma.sql`"monthlyPeriod" = ${period}`);

  const query = normalizeNullable(options.q);
  if (query) {
    const contains = `%${query}%`;
    conditions.push(Prisma.sql`(
      "bookingId" ILIKE ${contains}
      OR "providerProfileId" ILIKE ${contains}
      OR COALESCE("metadata"->>'couponCodeSnapshot', '') ILIKE ${contains}
      OR COALESCE("metadata"->>'couponId', '') ILIKE ${contains}
    )`);
  }
  const reviewSql = adminCouponFinanceReversalReviewSql(options.review);
  if (reviewSql) conditions.push(reviewSql);
  return Prisma.sql`WHERE ${Prisma.join(conditions, ' AND ')}`;
}

function adminCouponFinanceReversalReviewSql(review: string | null | undefined): Prisma.Sql | null {
  switch (normalizeNullable(review)) {
    case 'coupon-review':
      return Prisma.sql`"metadata" ? 'couponReviewFlag'`;
    case 'needs-action':
    case 'open':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.OPEN}::"BookingSettlementTaxStatus"`;
    case 'declared':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.DECLARED}::"BookingSettlementTaxStatus"`;
    case 'paid':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.PAID}::"BookingSettlementTaxStatus"`;
    case 'closed':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.CLOSED}::"BookingSettlementTaxStatus"`;
    case 'posted':
      return Prisma.sql`"settlementStatus" = ${BookingSettlementStatus.POSTED}::"BookingSettlementStatus"`;
    case 'reversed':
      return Prisma.sql`TRUE`;
    case 'cash':
      return Prisma.sql`"paymentMethod" = ${PaymentMethod.CASH}::"PaymentMethod"`;
    case 'non-cash':
      return Prisma.sql`"paymentMethod" <> ${PaymentMethod.CASH}::"PaymentMethod"`;
    default:
      return null;
  }
}

function adminCouponFinanceSortSql(value: string | null | undefined) {
  return normalizeNullable(value)?.toLowerCase() === 'oldest' ? Prisma.sql`ASC` : Prisma.sql`DESC`;
}

function adminCouponFinanceReviewSql(review: string | null | undefined): Prisma.Sql | null {
  switch (normalizeNullable(review)) {
    case 'coupon-review':
      return Prisma.sql`"metadata" ? 'couponReviewFlag'`;
    case 'needs-action':
    case 'open':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.OPEN}::"BookingSettlementTaxStatus"`;
    case 'declared':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.DECLARED}::"BookingSettlementTaxStatus"`;
    case 'paid':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.PAID}::"BookingSettlementTaxStatus"`;
    case 'closed':
      return Prisma.sql`"taxStatus" = ${BookingSettlementTaxStatus.CLOSED}::"BookingSettlementTaxStatus"`;
    case 'posted':
      return Prisma.sql`"settlementStatus" = ${BookingSettlementStatus.POSTED}::"BookingSettlementStatus"`;
    case 'reversed':
      return Prisma.sql`("settlementStatus" = ${BookingSettlementStatus.REVERSED}::"BookingSettlementStatus" OR "taxStatus" = ${BookingSettlementTaxStatus.REVERSED}::"BookingSettlementTaxStatus")`;
    case 'cash':
      return Prisma.sql`"paymentMethod" = ${PaymentMethod.CASH}::"PaymentMethod"`;
    case 'non-cash':
      return Prisma.sql`"paymentMethod" <> ${PaymentMethod.CASH}::"PaymentMethod"`;
    default:
      return null;
  }
}

function adminJsonIntSql(key: string): Prisma.Sql {
  return Prisma.sql`
    CASE
      WHEN "metadata" ? ${key} AND ("metadata"->>${key}) ~ '^-?[0-9]+$'
      THEN ("metadata"->>${key})::bigint
      ELSE 0
    END
  `;
}

function adminPartnerWithholdingTaxSqlWhere(period: string): Prisma.Sql {
  return Prisma.sql`
    WHERE "monthlyPeriod" = ${period}
      AND "settlementStatus" <> ${BookingSettlementStatus.REVERSED}::"BookingSettlementStatus"
      AND ("partnerTaxableRevenue" > 0 OR "partnerWithholdingTotal" > 0)
  `;
}

type AdminPartnerWithholdingEvidenceStatus = 'COMPLETE' | 'EXPLICIT_ZERO' | 'MIXED' | 'MISSING_EVIDENCE';

export function adminPartnerWithholdingEvidenceStatus(input: {
  readonly completeEvidenceCount: number;
  readonly explicitZeroEvidenceCount: number;
  readonly missingEvidenceCount: number;
}): AdminPartnerWithholdingEvidenceStatus {
  if (input.missingEvidenceCount > 0) return 'MISSING_EVIDENCE';
  if (input.completeEvidenceCount > 0 && input.explicitZeroEvidenceCount > 0) return 'MIXED';
  if (input.explicitZeroEvidenceCount > 0) return 'EXPLICIT_ZERO';
  return 'COMPLETE';
}

function adminPartnerWithholdingEvidenceEventStatusSql(columns: {
  readonly partnerPitRateBps: Prisma.Sql;
  readonly partnerVatRateBps: Prisma.Sql;
  readonly partnerWithholdingTotal: Prisma.Sql;
  readonly taxPolicyVersionId: Prisma.Sql;
  readonly taxRuleSnapshot: Prisma.Sql;
}) {
  const {
    partnerPitRateBps,
    partnerVatRateBps,
    partnerWithholdingTotal,
    taxPolicyVersionId,
    taxRuleSnapshot,
  } = columns;
  return Prisma.sql`
    CASE
      WHEN ${taxPolicyVersionId} IS NULL
        OR ${taxRuleSnapshot} IS NULL
        OR jsonb_typeof(${taxRuleSnapshot}) <> 'object'
        OR ${taxRuleSnapshot} = '{}'::jsonb
        THEN 'MISSING_EVIDENCE'
      WHEN ${partnerWithholdingTotal} = 0
        AND ${partnerVatRateBps} = 0
        AND ${partnerPitRateBps} = 0
        THEN 'EXPLICIT_ZERO'
      WHEN ${partnerWithholdingTotal} <> 0
        AND (${partnerVatRateBps} > 0 OR ${partnerPitRateBps} > 0)
        THEN 'COMPLETE'
      ELSE 'MISSING_EVIDENCE'
    END
  `;
}

function adminPartnerWithholdingTaxActivityCteSql(period: string): Prisma.Sql {
  return Prisma.sql`
    "withholdingActivity" AS (
      SELECT
        "providerProfileId",
        "monthlyPeriod",
        "currency",
        1::bigint AS "postedSettlementCount",
        0::bigint AS "reversalCount",
        "partnerTaxableRevenue"::bigint AS "grossServiceRevenue",
        "partnerPayoutAmount"::bigint AS "partnerPayoutTotal",
        "partnerVatAmount"::bigint AS "partnerVatWithheldTotal",
        "partnerPitAmount"::bigint AS "partnerPitWithheldTotal",
        "partnerWithholdingTotal"::bigint AS "totalPartnerTaxWithheld",
        ${adminPartnerWithholdingEvidenceEventStatusSql({
          partnerPitRateBps: Prisma.sql`"partnerPitRateBps"`,
          partnerVatRateBps: Prisma.sql`"partnerVatRateBps"`,
          partnerWithholdingTotal: Prisma.sql`"partnerWithholdingTotal"`,
          taxPolicyVersionId: Prisma.sql`"taxPolicyVersionId"`,
          taxRuleSnapshot: Prisma.sql`"taxRuleSnapshot"`,
        })} AS "withholdingEvidenceEventStatus"
      FROM "BookingSettlementSnapshot"
      ${adminPartnerWithholdingTaxSqlWhere(period)}

      UNION ALL

      SELECT
        reversal."providerProfileId",
        reversal."monthlyPeriod",
        reversal."currency",
        0::bigint AS "postedSettlementCount",
        1::bigint AS "reversalCount",
        reversal."partnerTaxableRevenue"::bigint AS "grossServiceRevenue",
        reversal."partnerPayoutAmount"::bigint AS "partnerPayoutTotal",
        reversal."partnerVatAmount"::bigint AS "partnerVatWithheldTotal",
        reversal."partnerPitAmount"::bigint AS "partnerPitWithheldTotal",
        reversal."partnerWithholdingTotal"::bigint AS "totalPartnerTaxWithheld",
        ${adminPartnerWithholdingEvidenceEventStatusSql({
          partnerPitRateBps: Prisma.sql`original."partnerPitRateBps"`,
          partnerVatRateBps: Prisma.sql`original."partnerVatRateBps"`,
          partnerWithholdingTotal: Prisma.sql`reversal."partnerWithholdingTotal"`,
          taxPolicyVersionId: Prisma.sql`original."taxPolicyVersionId"`,
          taxRuleSnapshot: Prisma.sql`original."taxRuleSnapshot"`,
        })} AS "withholdingEvidenceEventStatus"
      FROM "BookingSettlementReversalEntry" reversal
      INNER JOIN "BookingSettlementSnapshot" original
        ON original."id" = reversal."originalSettlementSnapshotId"
      WHERE reversal."monthlyPeriod" = ${period}
        AND (reversal."partnerTaxableRevenue" <> 0 OR reversal."partnerWithholdingTotal" <> 0)
    ),
    "withholdingEvidenceByProvider" AS (
      SELECT
        activity."providerProfileId",
        COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'COMPLETE')::bigint
          AS "completeEvidenceCount",
        COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'EXPLICIT_ZERO')::bigint
          AS "explicitZeroEvidenceCount",
        COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'MISSING_EVIDENCE')::bigint
          AS "missingEvidenceCount",
        CASE
          WHEN COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'MISSING_EVIDENCE') > 0
            THEN 'MISSING_EVIDENCE'
          WHEN COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'COMPLETE') > 0
            AND COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'EXPLICIT_ZERO') > 0
            THEN 'MIXED'
          WHEN COUNT(*) FILTER (WHERE activity."withholdingEvidenceEventStatus" = 'EXPLICIT_ZERO') > 0
            THEN 'EXPLICIT_ZERO'
          ELSE 'COMPLETE'
        END AS "withholdingEvidenceStatus"
      FROM "withholdingActivity" activity
      GROUP BY activity."providerProfileId"
    )
  `;
}

function adminPartnerBankDepositReconciliationCteSql(options: {
  assigneeAdminId?: string | null;
  owner?: 'all' | 'unassigned';
  period?: string | null;
  query?: string | null;
  sla?: 'all' | 'within-24h' | 'over-24h' | 'escalate';
  status?: PartnerBankDepositRequestStatus | null;
}): Prisma.Sql {
  const assigneeAdminId = options.assigneeAdminId ?? '';
  const owner = options.owner ?? 'all';
  const period = options.period ?? '';
  const query = options.query ?? '';
  const queryPattern = `%${query}%`;
  const sla = options.sla ?? 'all';
  const status = options.status ?? '';

  return Prisma.sql`
    "latestPartnerBankDepositAssignments" AS (
      SELECT DISTINCT ON (logs."target")
        logs."id" AS "assignmentAuditLogId",
        logs."target",
        logs."metadata"->>'assigneeAdminId' AS "assigneeAdminId",
        logs."createdAt" AS "assignedAt"
      FROM "AdminAuditLog" logs
      WHERE logs."action" = ${PARTNER_BANK_DEPOSIT_RECONCILIATION_ASSIGNMENT_ACTION}
      ORDER BY logs."target", logs."createdAt" DESC, logs."id" DESC
    ),
    "partnerBankDepositEvidence" AS (
      SELECT
        request."id",
        request."depositDate",
        request."createdAt",
        request."executedAt",
        COALESCE(MAX(entry."amount"), request."amount")::bigint AS "targetAmount",
        COALESCE(
          SUM(
            CASE
              WHEN match."status" IN (
                ${BankReconciliationStatus.MATCHED}::"BankReconciliationStatus",
                ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
              ) THEN ABS(match."amount")
              ELSE 0
            END
          ),
          0
        )::bigint AS "matchedAmount"
      FROM "PartnerBankDepositRequest" request
      LEFT JOIN "ProviderProfile" provider ON provider."id" = request."providerProfileId"
      LEFT JOIN "User" partnerUser ON partnerUser."id" = provider."userId"
      LEFT JOIN "AccountingJournalBatch" batch ON batch."id" = request."journalBatchId"
      LEFT JOIN "AccountingJournalEntry" entry
        ON entry."batchId" = batch."id"
        AND batch."sourceType" = ${AccountingJournalSourceType.PROVIDER_BANK_DEPOSIT}::"AccountingJournalSourceType"
        AND batch."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
        AND entry."side" = ${AccountingJournalEntrySide.DEBIT}::"AccountingJournalEntrySide"
        AND entry."accountCode" = 'company_bank_cash'
      LEFT JOIN "BankReconciliationMatch" match
        ON match."accountingJournalEntryId" = entry."id"
      WHERE request."status" = ${PartnerBankDepositRequestStatus.EXECUTED}::"PartnerBankDepositRequestStatus"
        AND (${status} = '' OR ${status} = ${PartnerBankDepositRequestStatus.EXECUTED})
        AND (
          ${period} = ''
          OR COALESCE(
            batch."monthlyPeriod",
            TO_CHAR(request."depositDate" AT TIME ZONE ${VIETNAM_TIME_ZONE}, 'YYYY-MM')
          ) = ${period}
        )
        AND (
          ${query} = ''
          OR request."id" ILIKE ${queryPattern}
          OR request."bankTransactionId" ILIKE ${queryPattern}
          OR request."providerProfileId" ILIKE ${queryPattern}
          OR provider."displayName" ILIKE ${queryPattern}
          OR partnerUser."fullName" ILIKE ${queryPattern}
        )
      GROUP BY request."id", request."amount", request."depositDate", request."createdAt", request."executedAt"
    ),
    "openPartnerBankDeposits" AS (
      SELECT
        evidence."id",
        evidence."depositDate",
        evidence."createdAt",
        evidence."executedAt",
        assignments."assignmentAuditLogId",
        assignments."assigneeAdminId",
        assignments."assignedAt",
        GREATEST(evidence."targetAmount" - LEAST(evidence."targetAmount", evidence."matchedAmount"), 0)::bigint AS "remainingAmount"
      FROM "partnerBankDepositEvidence" evidence
      LEFT JOIN "latestPartnerBankDepositAssignments" assignments
        ON assignments."target" = 'partner_bank_deposit_request:' || evidence."id"
      WHERE evidence."matchedAmount" < evidence."targetAmount"
        AND (${owner} <> 'unassigned' OR assignments."assigneeAdminId" IS NULL)
        AND (${assigneeAdminId} = '' OR assignments."assigneeAdminId" = ${assigneeAdminId})
        AND (
          ${sla} = 'all'
          OR (
            ${sla} = 'within-24h'
            AND COALESCE(evidence."executedAt", evidence."createdAt") > NOW() - INTERVAL '24 hours'
          )
          OR (
            ${sla} = 'over-24h'
            AND COALESCE(evidence."executedAt", evidence."createdAt") <= NOW() - INTERVAL '24 hours'
            AND COALESCE(evidence."executedAt", evidence."createdAt") > NOW() - INTERVAL '48 hours'
          )
          OR (
            ${sla} = 'escalate'
            AND COALESCE(evidence."executedAt", evidence."createdAt") <= NOW() - INTERVAL '48 hours'
          )
        )
    )
  `;
}

function adminPartnerPayoutBankReconciliationCteSql(options: { period: string }): Prisma.Sql {
  return Prisma.sql`
    ${adminPayoutBankOutflowReconciliationCteSql(options.period)},
    "payoutReturnInflowEvidence" AS (
      SELECT
        journal."id",
        journal."postedAt",
        journal."sourceId" AS "payoutBatchId",
        COALESCE(MAX(entry."amount"), journal."totalDebit")::bigint AS "targetAmount",
        COALESCE(
          SUM(
            CASE
              WHEN match."status" IN (
                ${BankReconciliationStatus.MATCHED}::"BankReconciliationStatus",
                ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
              )
                AND bank."status" IN (
                  ${BankReconciliationStatus.MATCHED}::"BankReconciliationStatus",
                  ${BankReconciliationStatus.PARTIALLY_MATCHED}::"BankReconciliationStatus"
                )
                AND bank."type" = ${CompanyBankTransactionType.INFLOW}::"CompanyBankTransactionType"
                AND bank."currency" = journal."currency"
              THEN ABS(match."amount")
              ELSE 0
            END
          ),
          0
        )::bigint AS "matchedAmount"
      FROM "AccountingJournalBatch" journal
      LEFT JOIN "AccountingJournalEntry" entry
        ON entry."batchId" = journal."id"
        AND entry."side" = ${AccountingJournalEntrySide.DEBIT}::"AccountingJournalEntrySide"
        AND entry."accountCode" = 'company_bank_cash'
      LEFT JOIN "BankReconciliationMatch" match
        ON match."payoutBatchId" = journal."sourceId"
        AND match."accountingJournalEntryId" = entry."id"
      LEFT JOIN "CompanyBankTransaction" bank
        ON bank."id" = match."bankTransactionId"
      WHERE journal."sourceType" = ${AccountingJournalSourceType.PROVIDER_PAYOUT_BATCH}::"AccountingJournalSourceType"
        AND journal."status" = ${AccountingJournalBatchStatus.POSTED}::"AccountingJournalBatchStatus"
        AND journal."sourceKey" = 'accounting-journal:provider-payout-batch:' || journal."sourceId" || ':reversal'
        AND journal."monthlyPeriod" = ${options.period}
      GROUP BY journal."id", journal."postedAt", journal."sourceId", journal."totalDebit"
    ),
    "openPayoutReturnInflows" AS (
      SELECT
        evidence."id",
        evidence."postedAt",
        evidence."payoutBatchId",
        GREATEST(
          evidence."targetAmount" - LEAST(evidence."targetAmount", evidence."matchedAmount"),
          0
        )::bigint AS "remainingAmount"
      FROM "payoutReturnInflowEvidence" evidence
      WHERE evidence."matchedAmount" < evidence."targetAmount"
    )
  `;
}

function adminPartnerWithholdingTaxPeriod(value: string | null | undefined) {
  const normalized = normalizeNullable(value);
  if (normalized && /^\d{4}-(0[1-9]|1[0-2])$/.test(normalized)) {
    return normalized;
  }

  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: VIETNAM_TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
  }).formatToParts(new Date());
  const year = parts.find((part) => part.type === 'year')?.value ?? '1970';
  const month = parts.find((part) => part.type === 'month')?.value ?? '01';
  return `${year}-${month}`;
}

function normalizeOptionalAdminTaxPeriod(value: string | null | undefined) {
  const normalized = normalizeNullable(value);
  if (!normalized) return undefined;
  if (/^\d{4}-(0[1-9]|1[0-2])$/.test(normalized)) return normalized;
  throw new BadRequestException('Accounting period must use YYYY-MM');
}

function adminAccountingPeriodDateRange(value: string | null | undefined) {
  const period = normalizeOptionalAdminTaxPeriod(value);
  if (!period) return undefined;
  const [yearText, monthText] = period.split('-');
  const year = Number(yearText);
  const month = Number(monthText);
  const nextYear = month === 12 ? year + 1 : year;
  const nextMonth = month === 12 ? 1 : month + 1;
  const nextPeriod = `${String(nextYear).padStart(4, '0')}-${String(nextMonth).padStart(2, '0')}`;

  return {
    gte: new Date(`${period}-01T00:00:00+07:00`),
    lt: new Date(`${nextPeriod}-01T00:00:00+07:00`),
  };
}

function monthlyTaxClosingStatus(value: MonthlyTaxClosingStatus | string | null | undefined) {
  if (value && Object.values(MonthlyTaxClosingStatus).includes(value as MonthlyTaxClosingStatus)) {
    return value as MonthlyTaxClosingStatus;
  }

  throw new BadRequestException('Valid monthly tax closing status is required.');
}

function assertMonthlyTaxClosingReconciliationIsBalanced(
  summary: { netRevenueDelta?: number; reconciliationDelta: number },
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (nextStatus === MonthlyTaxClosingStatus.DRAFT) {
    return;
  }
  if (summary.reconciliationDelta !== 0) {
    throw new BadRequestException(
      'Monthly close requires reconciliation delta to be zero before status can advance.',
    );
  }
  if ((summary.netRevenueDelta ?? 0) !== 0) {
    throw new BadRequestException(
      'Monthly close requires net revenue delta to be zero before status can advance.',
    );
  }
}

function assertMonthlyTaxClosingPaymentFeeEvidenceIsReady(
  summary: { paymentFeeReviewFlagCount: number },
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (nextStatus === MonthlyTaxClosingStatus.DRAFT || nextStatus === MonthlyTaxClosingStatus.REVIEWED) {
    return;
  }
  if (summary.paymentFeeReviewFlagCount > 0) {
    throw new BadRequestException(
      `Monthly close has ${summary.paymentFeeReviewFlagCount} settlement(s) without resolved payment fee policy evidence. Review and activate the applicable payment fee policy before declaration.`,
    );
  }
}

function assertMonthlyTaxClosingPlatformVatEvidenceIsReady(
  summary: { platformVatReviewFlagCount: number },
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (nextStatus === MonthlyTaxClosingStatus.DRAFT || nextStatus === MonthlyTaxClosingStatus.REVIEWED) {
    return;
  }
  if (summary.platformVatReviewFlagCount > 0) {
    throw new BadRequestException(
      `Monthly close has ${summary.platformVatReviewFlagCount} settlement(s) with unexplained or unavailable platform VAT evidence. Review the exact VAT evidence queue before declaration.`,
    );
  }
}

function assertMonthlyTaxClosingPartnerDepositReconciliationIsReady(
  summary: { partnerDepositReconciliationOpenCount: number },
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (nextStatus === MonthlyTaxClosingStatus.DRAFT || nextStatus === MonthlyTaxClosingStatus.REVIEWED) {
    return;
  }
  if (summary.partnerDepositReconciliationOpenCount > 0) {
    throw new BadRequestException(
      `Monthly close has ${summary.partnerDepositReconciliationOpenCount} executed Partner bank deposit(s) without complete bank reconciliation. Match the retained bank evidence before declaration.`,
    );
  }
}

function assertMonthlyTaxClosingPartnerPayoutReconciliationIsReady(
  summary: {
    payoutBankOutflowReconciliationOpenCount?: number;
    payoutReturnInflowReconciliationOpenCount?: number;
  },
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (nextStatus === MonthlyTaxClosingStatus.DRAFT || nextStatus === MonthlyTaxClosingStatus.REVIEWED) {
    return;
  }
  if ((summary.payoutBankOutflowReconciliationOpenCount ?? 0) > 0) {
    throw new BadRequestException(
      `Monthly close has ${summary.payoutBankOutflowReconciliationOpenCount} paid Partner payout batch(es) without complete bank outflow reconciliation. Match the payout and posted bank credit evidence before declaration.`,
    );
  }
  if ((summary.payoutReturnInflowReconciliationOpenCount ?? 0) > 0) {
    throw new BadRequestException(
      `Monthly close has ${summary.payoutReturnInflowReconciliationOpenCount} Partner payout return(s) without complete bank inflow reconciliation. Match the return and posted reversal bank debit evidence before declaration.`,
    );
  }
}

async function assertMonthlyTaxClosingPostedJournalsAreBalanced(
  prisma: Pick<PrismaService, '$queryRaw'> | Pick<Prisma.TransactionClient, '$queryRaw'>,
  period: string,
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (nextStatus === MonthlyTaxClosingStatus.DRAFT) {
    return;
  }

  const [imbalancedJournal] = await prisma.$queryRaw<Array<{ id: string; sourceKey: string }>>(
    Prisma.sql`
      ${adminAccountingJournalIntegrityCte({ period, range: 'all', review: 'posted' }, undefined, true)}
      SELECT integrity."id", integrity."sourceKey"
      FROM journal_integrity integrity
      WHERE integrity."integrityState" <> 'CLEAR'
      ORDER BY integrity."postedAt" ASC, integrity."id" ASC
      LIMIT 1
    `,
  );

  if (imbalancedJournal) {
    throw new BadRequestException(
      'Monthly close requires every posted journal batch to pass header, entry, formula, and period integrity checks before status can advance.',
    );
  }
}

async function assertMonthlyTaxClosingWithholdingRemittanceIsReady(
  prisma:
    | Pick<PrismaService, 'accountingJournalBatch'>
    | Pick<Prisma.TransactionClient, 'accountingJournalBatch'>,
  input: {
    readonly currency: string;
    readonly existing: {
      readonly remittanceMetadata: Prisma.JsonValue | null;
      readonly status: MonthlyTaxClosingStatus;
    } | null;
    readonly nextStatus: MonthlyTaxClosingStatus;
    readonly partnerWithholdingTotal: number;
    readonly period: string;
  },
) {
  if (input.nextStatus !== MonthlyTaxClosingStatus.CLOSED) {
    return;
  }
  if (input.partnerWithholdingTotal < 0) {
    throw new BadRequestException(
      'Monthly close requires a non-negative Partner withholding balance after reversal entries are applied.',
    );
  }
  if (input.partnerWithholdingTotal === 0) {
    return;
  }

  const remittanceMetadata = jsonObject(input.existing?.remittanceMetadata ?? null);
  if (
    input.existing?.status !== MonthlyTaxClosingStatus.PAID ||
    !adminJsonString(remittanceMetadata.transferRef) ||
    !adminJsonString(remittanceMetadata.evidenceUrl) ||
    !adminJsonString(remittanceMetadata.approvedByAdminId) ||
    !adminJsonString(remittanceMetadata.remittedByAdminId) ||
    !adminJsonString(remittanceMetadata.paidAt)
  ) {
    throw new BadRequestException(
      'Monthly close requires immutable Partner withholding remittance approval and payment evidence.',
    );
  }

  const journal = await prisma.accountingJournalBatch.findUnique({
    where: {
      sourceKey: `accounting-journal:withholding-remittance:${input.period}:${input.currency}`,
    },
    select: {
      entries: {
        select: {
          accountCode: true,
          amount: true,
          side: true,
        },
      },
      sourceType: true,
      status: true,
      totalCredit: true,
      totalDebit: true,
    },
  });
  const payableDebit =
    journal?.entries
      .filter(
        (entry) =>
          entry.accountCode === 'partner_vat_pit_payable' && entry.side === AccountingJournalEntrySide.DEBIT,
      )
      .reduce((total, entry) => total + entry.amount, 0) ?? 0;
  const bankCredit =
    journal?.entries
      .filter(
        (entry) =>
          entry.accountCode === 'company_bank_cash' && entry.side === AccountingJournalEntrySide.CREDIT,
      )
      .reduce((total, entry) => total + entry.amount, 0) ?? 0;

  if (
    journal?.status !== AccountingJournalBatchStatus.POSTED ||
    journal.sourceType !== AccountingJournalSourceType.WITHHOLDING_REMITTANCE ||
    journal.totalDebit !== input.partnerWithholdingTotal ||
    journal.totalCredit !== input.partnerWithholdingTotal ||
    payableDebit !== input.partnerWithholdingTotal ||
    bankCredit !== input.partnerWithholdingTotal
  ) {
    throw new BadRequestException(
      'Monthly close requires a posted Partner withholding remittance journal matching the current reversal-adjusted withholding balance.',
    );
  }
}

type MonthlyTaxClosingRemittanceJournalPreflight = {
  readonly entries: ReadonlyArray<{
    readonly accountCode: string;
    readonly amount: number;
    readonly side: AccountingJournalEntrySide;
  }>;
  readonly sourceType: AccountingJournalSourceType;
  readonly status: AccountingJournalBatchStatus;
  readonly totalCredit: number;
  readonly totalDebit: number;
} | null;

type MonthlyTaxClosingPreflightBlockerCode =
  | 'NEGATIVE_WITHHOLDING'
  | 'NET_REVENUE_DELTA'
  | 'PARTNER_DEPOSIT_RECONCILIATION'
  | 'PAYOUT_BANK_OUTFLOW_RECONCILIATION'
  | 'PAYOUT_RETURN_INFLOW_RECONCILIATION'
  | 'PAYMENT_FEE_EVIDENCE'
  | 'PLATFORM_VAT_EVIDENCE'
  | 'POSTED_JOURNAL_DELTA'
  | 'RECONCILIATION_DELTA'
  | 'REMITTANCE_AMOUNT_MISMATCH'
  | 'REMITTANCE_EVIDENCE'
  | 'REMITTANCE_JOURNAL';

function monthlyTaxClosingNextStatus(status: MonthlyTaxClosingStatus) {
  const currentIndex = MONTHLY_TAX_CLOSING_STATUS_ORDER.indexOf(status);
  if (currentIndex < 0 || currentIndex >= MONTHLY_TAX_CLOSING_STATUS_ORDER.length - 1) {
    return null;
  }
  return MONTHLY_TAX_CLOSING_STATUS_ORDER[currentIndex + 1] ?? null;
}

function monthlyTaxClosingPreflight(input: {
  readonly closing: {
    readonly remittanceMetadata?: Prisma.JsonValue | null;
    readonly status: MonthlyTaxClosingStatus;
  } | null;
  readonly journalReconciliationIssueCount: number;
  readonly netRevenueDelta: number;
  readonly nextStatus: MonthlyTaxClosingStatus | null;
  readonly partnerDepositReconciliationOpenCount: number;
  readonly payoutBankOutflowReconciliationOpenCount: number;
  readonly payoutReturnInflowReconciliationOpenCount: number;
  readonly partnerWithholdingTotal: number;
  readonly paymentFeeReviewFlagCount: number;
  readonly platformVatReviewFlagCount: number;
  readonly reconciliationDelta: number;
  readonly withholdingRemittanceJournal: MonthlyTaxClosingRemittanceJournalPreflight;
}) {
  const blockers: Array<{ code: MonthlyTaxClosingPreflightBlockerCode; message: string }> = [];
  const nextStatus = input.nextStatus;

  if (!nextStatus) {
    return { blockers, nextStatus, ready: true };
  }
  if (input.reconciliationDelta !== 0) {
    blockers.push({
      code: 'RECONCILIATION_DELTA',
      message: 'Customer payment reconciliation must equal 0 before the period can advance.',
    });
  }
  if (input.netRevenueDelta !== 0) {
    blockers.push({
      code: 'NET_REVENUE_DELTA',
      message:
        'Platform fee, company VAT, and net revenue reconciliation must equal 0 before the period can advance.',
    });
  }
  if (input.journalReconciliationIssueCount > 0) {
    blockers.push({
      code: 'POSTED_JOURNAL_DELTA',
      message: `${input.journalReconciliationIssueCount} posted journal batch(es) have an open reconciliation delta.`,
    });
  }

  if (nextStatus !== MonthlyTaxClosingStatus.REVIEWED) {
    if (input.paymentFeeReviewFlagCount > 0) {
      blockers.push({
        code: 'PAYMENT_FEE_EVIDENCE',
        message: `${input.paymentFeeReviewFlagCount} settlement(s) still need resolved payment fee policy evidence.`,
      });
    }
    if (input.platformVatReviewFlagCount > 0) {
      blockers.push({
        code: 'PLATFORM_VAT_EVIDENCE',
        message: `${input.platformVatReviewFlagCount} settlement(s) have unexplained or unavailable platform VAT evidence.`,
      });
    }
    if (input.partnerDepositReconciliationOpenCount > 0) {
      blockers.push({
        code: 'PARTNER_DEPOSIT_RECONCILIATION',
        message: `${input.partnerDepositReconciliationOpenCount} executed Partner bank deposit(s) still need complete bank reconciliation.`,
      });
    }
    if (input.payoutBankOutflowReconciliationOpenCount > 0) {
      blockers.push({
        code: 'PAYOUT_BANK_OUTFLOW_RECONCILIATION',
        message: `${input.payoutBankOutflowReconciliationOpenCount} paid Partner payout batch(es) still need complete bank outflow reconciliation.`,
      });
    }
    if (input.payoutReturnInflowReconciliationOpenCount > 0) {
      blockers.push({
        code: 'PAYOUT_RETURN_INFLOW_RECONCILIATION',
        message: `${input.payoutReturnInflowReconciliationOpenCount} Partner payout return(s) still need complete bank inflow reconciliation.`,
      });
    }
  }

  if (nextStatus === MonthlyTaxClosingStatus.CLOSED) {
    if (input.partnerWithholdingTotal < 0) {
      blockers.push({
        code: 'NEGATIVE_WITHHOLDING',
        message: 'Partner withholding must be non-negative after reversal entries are applied.',
      });
    } else if (input.partnerWithholdingTotal > 0) {
      const remittanceMetadata = jsonObject(input.closing?.remittanceMetadata ?? null);
      if (
        input.closing?.status !== MonthlyTaxClosingStatus.PAID ||
        !adminJsonString(remittanceMetadata.transferRef) ||
        !adminJsonString(remittanceMetadata.evidenceUrl) ||
        !adminJsonString(remittanceMetadata.approvedByAdminId) ||
        !adminJsonString(remittanceMetadata.remittedByAdminId) ||
        !adminJsonString(remittanceMetadata.paidAt)
      ) {
        blockers.push({
          code: 'REMITTANCE_EVIDENCE',
          message:
            'Retained remittance reference, evidence, maker, approver, and paid timestamp are required before final close.',
        });
      }

      const journal = input.withholdingRemittanceJournal;
      if (
        journal?.status !== AccountingJournalBatchStatus.POSTED ||
        journal.sourceType !== AccountingJournalSourceType.WITHHOLDING_REMITTANCE
      ) {
        blockers.push({
          code: 'REMITTANCE_JOURNAL',
          message: 'A posted Partner withholding remittance journal is required before final close.',
        });
      } else {
        const payableDebit = journal.entries
          .filter(
            (entry) =>
              entry.accountCode === 'partner_vat_pit_payable' &&
              entry.side === AccountingJournalEntrySide.DEBIT,
          )
          .reduce((total, entry) => total + entry.amount, 0);
        const bankCredit = journal.entries
          .filter(
            (entry) =>
              entry.accountCode === 'company_bank_cash' && entry.side === AccountingJournalEntrySide.CREDIT,
          )
          .reduce((total, entry) => total + entry.amount, 0);
        if (
          journal.totalDebit !== input.partnerWithholdingTotal ||
          journal.totalCredit !== input.partnerWithholdingTotal ||
          payableDebit !== input.partnerWithholdingTotal ||
          bankCredit !== input.partnerWithholdingTotal
        ) {
          blockers.push({
            code: 'REMITTANCE_AMOUNT_MISMATCH',
            message:
              'The posted remittance journal does not match the current reversal-adjusted Partner withholding balance.',
          });
        }
      }
    }
  }

  return { blockers, nextStatus, ready: blockers.length === 0 };
}

async function upsertWithholdingRemittanceJournal(
  tx: Pick<Prisma.TransactionClient, 'accountingJournalBatch'>,
  input: {
    readonly actorId: string;
    readonly closingId: string;
    readonly currency: string;
    readonly period: string;
    readonly remittanceMetadata: Prisma.InputJsonObject | null;
    readonly total: number;
  },
) {
  if (!input.remittanceMetadata || input.total <= 0) {
    return;
  }

  const sourceKey = `accounting-journal:withholding-remittance:${input.period}:${input.currency}`;
  const entries = [
    {
      accountCode: 'partner_vat_pit_payable',
      accountName: 'Partner VAT/PIT payable',
      amount: input.total,
      currency: input.currency,
      memo: `Withholding remittance paid for ${input.period}`,
      side: 'DEBIT' as const,
      sourceId: input.closingId,
      sourceType: AccountingJournalSourceType.WITHHOLDING_REMITTANCE,
    },
    {
      accountCode: 'company_bank_cash',
      accountName: 'Company bank cash',
      amount: input.total,
      currency: input.currency,
      memo: `Manual withholding remittance transfer for ${input.period}`,
      side: 'CREDIT' as const,
      sourceId: input.closingId,
      sourceType: AccountingJournalSourceType.WITHHOLDING_REMITTANCE,
    },
  ];
  const batchData = {
    createdById: input.actorId,
    currency: input.currency,
    entries: {
      create: entries,
    },
    metadata: toJson({
      monthlyTaxClosingId: input.closingId,
      partnerWithholdingRemittance: true,
      remittance: input.remittanceMetadata,
    }),
    monthlyPeriod: input.period,
    sourceId: input.closingId,
    sourceType: AccountingJournalSourceType.WITHHOLDING_REMITTANCE,
    status: AccountingJournalBatchStatus.POSTED,
    totalCredit: input.total,
    totalDebit: input.total,
  };

  await tx.accountingJournalBatch.upsert({
    where: { sourceKey },
    update: {},
    create: {
      ...batchData,
      sourceKey,
    },
  });
}

function monthlyTaxClosingRemittanceMetadata(
  status: MonthlyTaxClosingStatus,
  input: AdminMonthlyTaxClosingStatusInput,
  actorId: string,
) {
  if (status !== MonthlyTaxClosingStatus.PAID) {
    return null;
  }

  const approvedByAdminId = normalizeFinanceActionApprovalAdminId(
    input.approvalAdminId,
    actorId,
    'Partner withholding remittance paid closeout',
  );
  const transferRef = normalizeNullable(input.remittanceTransferRef);
  if (!transferRef) {
    throw new BadRequestException(
      'Partner withholding remittance transfer reference is required before marking paid.',
    );
  }
  const evidenceUrl = normalizeNullable(input.remittanceEvidenceUrl);
  if (!evidenceUrl) {
    throw new BadRequestException(
      'Partner withholding remittance evidence URL is required before marking paid.',
    );
  }

  const paidAtDate = monthlyTaxClosingPaidAtDate(input.paidAt);
  return {
    approvedByAdminId,
    paidAtDate,
    metadata: {
      transferRef,
      channel: normalizeNullable(input.remittanceChannel),
      evidenceUrl,
      paidAt: paidAtDate.toISOString(),
      remittedByAdminId: actorId,
      approvedByAdminId,
    },
  };
}

function monthlyTaxClosingPaidAtDate(value: string | null | undefined) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return new Date();
  }

  const parsed = new Date(normalized);
  if (Number.isNaN(parsed.getTime())) {
    throw new BadRequestException('Valid partner withholding remittance paidAt is required.');
  }
  return parsed;
}

function monthlyTaxClosingStatusMutationData(status: MonthlyTaxClosingStatus, actorId: string, at: Date) {
  switch (status) {
    case MonthlyTaxClosingStatus.REVIEWED:
      return { reviewedById: actorId };
    case MonthlyTaxClosingStatus.DECLARED:
      return { declaredAt: at, declaredById: actorId };
    case MonthlyTaxClosingStatus.PAID:
      return { paidAt: at, paidById: actorId };
    case MonthlyTaxClosingStatus.CLOSED:
      return { closedAt: at, closedById: actorId };
    default:
      return {};
  }
}

function monthlyTaxClosingSettlementTaxStatus(
  status: MonthlyTaxClosingStatus,
): BookingSettlementTaxStatus | null {
  switch (status) {
    case MonthlyTaxClosingStatus.DECLARED:
      return BookingSettlementTaxStatus.DECLARED;
    case MonthlyTaxClosingStatus.PAID:
      return BookingSettlementTaxStatus.PAID;
    case MonthlyTaxClosingStatus.CLOSED:
      return BookingSettlementTaxStatus.CLOSED;
    default:
      return null;
  }
}

const MONTHLY_TAX_CLOSING_STATUS_ORDER: readonly MonthlyTaxClosingStatus[] = [
  MonthlyTaxClosingStatus.DRAFT,
  MonthlyTaxClosingStatus.REVIEWED,
  MonthlyTaxClosingStatus.DECLARED,
  MonthlyTaxClosingStatus.PAID,
  MonthlyTaxClosingStatus.CLOSED,
];

function assertMonthlyTaxClosingStatusTransition(
  currentStatus: MonthlyTaxClosingStatus,
  nextStatus: MonthlyTaxClosingStatus,
) {
  if (currentStatus === nextStatus) {
    return;
  }

  const currentIndex = MONTHLY_TAX_CLOSING_STATUS_ORDER.indexOf(currentStatus);
  const nextIndex = MONTHLY_TAX_CLOSING_STATUS_ORDER.indexOf(nextStatus);
  if (currentIndex < 0 || nextIndex !== currentIndex + 1) {
    throw new BadRequestException(
      'Monthly tax closing status must move in order: REVIEWED, DECLARED, PAID, CLOSED.',
    );
  }
}

function platformVatCategory(rateBps: number) {
  if (rateBps === 800) {
    return 'REDUCED_8';
  }
  if (rateBps === 1000) {
    return 'STANDARD_10';
  }
  return 'MANUAL_REVIEW';
}

type AdminPlatformVatRegisterEvidenceStatus =
  | 'POSITIVE_STANDARD_OR_REDUCED'
  | 'EXPLICIT_ZERO_RULE'
  | 'ZERO_FROM_POLICY'
  | 'ZERO_UNEXPLAINED'
  | 'EVIDENCE_UNAVAILABLE';

export function adminPlatformVatRegisterEvidenceStatus(input: {
  readonly companyOutputVat: number;
  readonly platformFeePolicyVersionId?: string | null;
  readonly platformFeeRuleSnapshot?: unknown;
  readonly platformVatRateBps: number;
}): AdminPlatformVatRegisterEvidenceStatus {
  if (input.companyOutputVat > 0 || input.platformVatRateBps > 0) {
    return 'POSITIVE_STANDARD_OR_REDUCED';
  }
  const ruleSnapshot = adminJsonObject(input.platformFeeRuleSnapshot);
  const lines = Array.isArray(ruleSnapshot?.lines) ? ruleSnapshot.lines : [];
  const hasExplicitZeroRule =
    ruleSnapshot?.source === 'SERVICE_PAYOUT_RULE' &&
    lines.length > 0 &&
    lines.every((line) => adminJsonObject(line)?.vatBps === 0);
  if (hasExplicitZeroRule) return 'EXPLICIT_ZERO_RULE';
  if (input.platformFeePolicyVersionId) return 'ZERO_FROM_POLICY';
  if (!ruleSnapshot) return 'EVIDENCE_UNAVAILABLE';
  return 'ZERO_UNEXPLAINED';
}

function adminPlatformVatEvidenceStatusSql(columns: {
  readonly companyOutputVat: Prisma.Sql;
  readonly platformFeePolicyVersionId: Prisma.Sql;
  readonly platformFeeRuleSnapshot: Prisma.Sql;
  readonly platformVatRateBps: Prisma.Sql;
}) {
  const { companyOutputVat, platformFeePolicyVersionId, platformFeeRuleSnapshot, platformVatRateBps } =
    columns;
  const safeLines = Prisma.sql`CASE
    WHEN jsonb_typeof(${platformFeeRuleSnapshot}->'lines') = 'array'
    THEN ${platformFeeRuleSnapshot}->'lines'
    ELSE '[]'::jsonb
  END`;
  return Prisma.sql`
    CASE
      WHEN ${companyOutputVat} > 0 OR ${platformVatRateBps} > 0
        THEN 'POSITIVE_STANDARD_OR_REDUCED'
      WHEN COALESCE(${platformFeeRuleSnapshot}->>'source', '') = 'SERVICE_PAYOUT_RULE'
        AND jsonb_array_length(${safeLines}) > 0
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(${safeLines}) line
          WHERE NOT CASE
            WHEN COALESCE(line->>'vatBps', '') ~ '^-?[0-9]+$'
            THEN (line->>'vatBps')::integer = 0
            ELSE FALSE
          END
        )
        THEN 'EXPLICIT_ZERO_RULE'
      WHEN ${platformFeePolicyVersionId} IS NOT NULL THEN 'ZERO_FROM_POLICY'
      WHEN ${platformFeeRuleSnapshot} IS NULL THEN 'EVIDENCE_UNAVAILABLE'
      ELSE 'ZERO_UNEXPLAINED'
    END
  `;
}

function adminPlatformVatEvidenceCteSql(period: string) {
  return Prisma.sql`
    "platformVatEvidenceRecords" AS NOT MATERIALIZED (
      SELECT
        snapshot."id",
        snapshot."companyOutputVat",
        snapshot."platformFeePolicyVersionId",
        snapshot."platformFeeRuleSnapshot",
        snapshot."platformVatRateBps"
      FROM "BookingSettlementSnapshot" snapshot
      WHERE snapshot."monthlyPeriod" = ${period}
        AND snapshot."settlementStatus"::text <> 'REVERSED'

      UNION

      SELECT
        original."id",
        original."companyOutputVat",
        original."platformFeePolicyVersionId",
        original."platformFeeRuleSnapshot",
        original."platformVatRateBps"
      FROM "BookingSettlementReversalEntry" reversal
      INNER JOIN "BookingSettlementSnapshot" original
        ON original."id" = reversal."originalSettlementSnapshotId"
      WHERE reversal."monthlyPeriod" = ${period}
    ),
    "platformVatEvidenceClassified" AS NOT MATERIALIZED (
      SELECT
        evidence.*,
        ${adminPlatformVatEvidenceStatusSql({
          companyOutputVat: Prisma.sql`evidence."companyOutputVat"`,
          platformFeePolicyVersionId: Prisma.sql`evidence."platformFeePolicyVersionId"`,
          platformFeeRuleSnapshot: Prisma.sql`evidence."platformFeeRuleSnapshot"`,
          platformVatRateBps: Prisma.sql`evidence."platformVatRateBps"`,
        })} AS "evidenceStatus"
      FROM "platformVatEvidenceRecords" evidence
    )
  `;
}

function adminPaymentOperationsWhere(
  options: AdminPaymentOperationsQuery,
): Prisma.PaymentWhereInput | undefined {
  const where = adminPaymentReviewWhere(normalizeAdminPaymentReview(options.review)) ?? {};
  const bookingDateWhere = adminPaymentBookingDateWhere(options.range);
  const customerProfileId = normalizeNullable(options.customerProfileId);
  const ageWhere = adminQueueAgeDateWhere(options.age);
  const filters: Prisma.PaymentWhereInput[] = [];
  const paymentMethod = normalizeAdminBookingSettlementGapPaymentMethod(options.paymentMethod);
  const paymentStatus = normalizeAdminPaymentStatus(options.paymentStatus);
  const bookingStatus = normalizeAdminBookingStatus(options.bookingStatus);
  const query = normalizeNullable(options.q)?.slice(0, 120);

  where.booking = adminMergePaymentBookingWhere(where.booking, adminBookingProductionDataWhere());

  if (bookingDateWhere) {
    where.booking = adminMergePaymentBookingWhere(where.booking, bookingDateWhere);
  }
  if (customerProfileId) {
    where.booking = adminMergePaymentBookingWhere(where.booking, { customerProfileId });
  }
  if (ageWhere) {
    where.booking = adminMergePaymentBookingWhere(where.booking, { updatedAt: ageWhere });
  }

  if (paymentMethod) {
    filters.push({ method: paymentMethod });
  }
  if (paymentStatus) {
    filters.push({ status: paymentStatus });
  }
  if (bookingStatus) {
    filters.push({ booking: { status: bookingStatus } });
  }
  const evidenceWhere = adminPaymentEvidenceWhere(options.evidence);
  if (evidenceWhere) {
    filters.push(evidenceWhere);
  }
  if (query) {
    const textFilter = { contains: query, mode: 'insensitive' as const };
    filters.push({
      OR: [
        { id: textFilter },
        { bookingId: textFilter },
        { providerRef: textFilter },
        { booking: { customerProfile: { user: { fullName: textFilter } } } },
        { booking: { customerProfile: { user: { phone: textFilter } } } },
        { booking: { selectedProvider: { is: { displayName: textFilter } } } },
        { booking: { selectedProvider: { is: { user: { is: { fullName: textFilter } } } } } },
        { booking: { selectedProvider: { is: { user: { is: { phone: textFilter } } } } } },
      ],
    });
  }

  return filters.reduce<Prisma.PaymentWhereInput | undefined>(
    (result, filter) => adminMergePaymentOperationsWhere(result, filter),
    Object.keys(where).length > 0 ? where : undefined,
  );
}

