function adminPaymentOperationsCte(
  options: AdminPaymentOperationsQuery,
  updatedAtWhere?: Prisma.DateTimeFilter,
  paymentId?: string,
) {
  const filters: Prisma.Sql[] = [
    adminBookingProductionDataSql(Prisma.sql`booking`, {
      fixture: adminPaymentBookingFixtureOwnerSql(),
      legacyFixture: adminPaymentBookingLegacyFixtureOwnerSql(),
    }),
  ];
  const bounds = adminPaymentDateRangeBounds(options.range);
  const customerProfileId = normalizeNullable(options.customerProfileId);
  const method = normalizeAdminBookingSettlementGapPaymentMethod(options.paymentMethod);
  const paymentStatus = normalizeAdminPaymentStatus(options.paymentStatus);
  const bookingStatus = normalizeAdminBookingStatus(options.bookingStatus);
  const query = normalizeNullable(options.q)?.slice(0, 120);
  const ageWhere = adminQueueAgeDateWhere(options.age);
  const bookingUpdatedAt = adminMergeDateTimeFilters(ageWhere, updatedAtWhere);

  if (bounds) {
    filters.push(Prisma.sql`booking."createdAt" >= ${new Date(bounds.startMs)}`);
    filters.push(Prisma.sql`booking."createdAt" <= ${new Date(bounds.endMs)}`);
  }
  if (customerProfileId) filters.push(Prisma.sql`booking."customerProfileId" = ${customerProfileId}`);
  if (method) filters.push(Prisma.sql`payment.method::text = ${method}`);
  if (paymentStatus) filters.push(Prisma.sql`payment.status::text = ${paymentStatus}`);
  if (bookingStatus) filters.push(Prisma.sql`booking.status::text = ${bookingStatus}`);
  if (paymentId) filters.push(Prisma.sql`payment.id = ${paymentId}`);
  if (bookingUpdatedAt?.gte) filters.push(Prisma.sql`booking."updatedAt" >= ${bookingUpdatedAt.gte}`);
  if (bookingUpdatedAt?.gt) filters.push(Prisma.sql`booking."updatedAt" > ${bookingUpdatedAt.gt}`);
  if (bookingUpdatedAt?.lte) filters.push(Prisma.sql`booking."updatedAt" <= ${bookingUpdatedAt.lte}`);
  if (bookingUpdatedAt?.lt) filters.push(Prisma.sql`booking."updatedAt" < ${bookingUpdatedAt.lt}`);
  if (query) {
    const like = `%${query.toLowerCase()}%`;
    filters.push(Prisma.sql`(
      LOWER(payment.id) LIKE ${like}
      OR LOWER(payment."bookingId") LIKE ${like}
      OR LOWER(COALESCE(payment."providerRef", '')) LIKE ${like}
      OR LOWER(COALESCE(customer_user."fullName", '')) LIKE ${like}
      OR LOWER(COALESCE(customer_user.phone, '')) LIKE ${like}
      OR LOWER(COALESCE(partner."displayName", '')) LIKE ${like}
      OR LOWER(COALESCE(partner_user."fullName", '')) LIKE ${like}
      OR LOWER(COALESCE(partner_user.phone, '')) LIKE ${like}
    )`);
  }

  return Prisma.sql`
    WITH payment_base AS (
      SELECT
        payment.id,
        payment."bookingId",
        payment.method::text AS method,
        payment.status::text AS "paymentStatus",
        payment."providerRef",
        payment.amount,
        payment."rawMeta",
        booking.status::text AS "bookingStatus",
        booking."createdAt" AS "bookingCreatedAt",
        booking."updatedAt" AS "bookingUpdatedAt"
      FROM "Payment" payment
      JOIN "Booking" booking ON booking.id = payment."bookingId"
      JOIN "CustomerProfile" customer ON customer.id = booking."customerProfileId"
      JOIN "User" customer_user ON customer_user.id = customer."userId"
      LEFT JOIN "ProviderProfile" preferred_partner ON preferred_partner.id = booking."preferredProviderId"
      LEFT JOIN "User" preferred_partner_user ON preferred_partner_user.id = preferred_partner."userId"
      LEFT JOIN "ProviderProfile" partner ON partner.id = booking."selectedProviderId"
      LEFT JOIN "User" partner_user ON partner_user.id = partner."userId"
      WHERE ${Prisma.join(filters, ' AND ')}
    ), callback_facts AS (
      SELECT
        base.id,
        COALESCE(BOOL_OR(
          callback.id IS NOT NULL
            AND (
              callback.outcome NOT IN ('ACCEPTED', 'REPLAY')
              OR callback."signatureVerified" IS DISTINCT FROM TRUE
              OR (callback."callbackAmount" IS NOT NULL AND callback."callbackAmount" <> base.amount)
            )
        ), FALSE) AS "evidenceConflict",
        COALESCE(BOOL_OR(
          callback.id IS NOT NULL
            AND callback.outcome IN ('ACCEPTED', 'REPLAY')
            AND callback."signatureVerified" = TRUE
          AND (callback."callbackAmount" IS NULL OR callback."callbackAmount" = base.amount)
        ), FALSE) AS "verifiedCallback"
      FROM payment_base base
      LEFT JOIN "PaymentCallbackAttempt" callback ON callback."paymentId" = base.id
      GROUP BY base.id, base.amount
    ), wallet_facts AS (
      SELECT base."bookingId", TRUE AS "walletVerified"
      FROM payment_base base
      JOIN "CustomerWalletLedgerEntry" wallet
        ON wallet."bookingId" = base."bookingId"
            AND wallet.amount < 0
        AND wallet."sourceKey" LIKE '%' || base."bookingId" || '%'
      GROUP BY base."bookingId"
    ), cash_debt_facts AS (
      SELECT base."bookingId", TRUE AS "cashDebt"
      FROM payment_base base
      JOIN "ProviderEarning" earning
        ON earning."bookingId" = base."bookingId"
            AND earning."netAmount" < 0
            AND earning.status::text <> 'PAID'
      GROUP BY base."bookingId"
    ), refund_facts AS (
      SELECT base.id, COUNT(refund.id) AS "refundCount"
      FROM payment_base base
      JOIN "Refund" refund ON refund."paymentId" = base.id
      GROUP BY base.id
    ), payment_facts AS (
      SELECT
        base.*,
        callback."evidenceConflict",
        callback."verifiedCallback",
        COALESCE(wallet."walletVerified", FALSE) AS "walletVerified",
        (
          NULLIF(base."rawMeta" #>> '{cashCollectedAt}', '') IS NOT NULL
          AND NULLIF(base."rawMeta" #>> '{cashCollectedBy}', '') IS NOT NULL
          AND NULLIF(base."rawMeta" #>> '{cashCollectionReference}', '') IS NOT NULL
        ) AS "cashVerified",
        COALESCE(cash_debt."cashDebt", FALSE) AS "cashDebt",
        COALESCE(refund."refundCount", 0) AS "refundCount"
      FROM payment_base base
      JOIN callback_facts callback ON callback.id = base.id
      LEFT JOIN wallet_facts wallet ON wallet."bookingId" = base."bookingId"
      LEFT JOIN cash_debt_facts cash_debt ON cash_debt."bookingId" = base."bookingId"
      LEFT JOIN refund_facts refund ON refund.id = base.id
    ), payment_scoped AS (
      SELECT *, CASE
        WHEN method IN ('MOMO', 'VNPAY', 'CARD', 'BANK_TRANSFER') AND "evidenceConflict" THEN 'CONFLICT'
        WHEN method IN ('MOMO', 'VNPAY', 'CARD', 'BANK_TRANSFER')
          AND "providerRef" IS NOT NULL AND "verifiedCallback" THEN 'VERIFIED'
        WHEN method IN ('MOMO', 'VNPAY', 'CARD', 'BANK_TRANSFER') THEN 'MISSING'
        WHEN method = 'CUSTOMER_WALLET' AND "walletVerified" THEN 'VERIFIED'
        WHEN method = 'CUSTOMER_WALLET' THEN 'MISSING'
        WHEN method = 'CASH' AND "cashVerified" THEN 'VERIFIED'
        WHEN method = 'CASH' THEN 'MISSING'
        ELSE 'NOT_APPLICABLE'
      END AS "evidenceState"
      FROM payment_facts
    ), payment_classified AS (
      SELECT *, CASE
        WHEN "evidenceState" = 'CONFLICT' THEN 'evidence-conflict'
        WHEN "paymentStatus" = 'REFUNDED' THEN 'history-refunded'
        WHEN "paymentStatus" = 'RELEASED' THEN 'history-released'
        WHEN method IN ('MOMO', 'VNPAY', 'CARD', 'BANK_TRANSFER') AND "evidenceState" = 'MISSING'
          THEN 'missing-gateway-evidence'
        WHEN method = 'CASH' AND "paymentStatus" = 'PENDING'
          AND "bookingStatus" IN ('CANCELLED', 'EXPIRED', 'NO_SHOW', 'REFUNDED')
          THEN 'terminal-cash-cleanup'
        WHEN "bookingStatus" = 'COMPLETED' AND "evidenceState" = 'VERIFIED'
          AND ((method = 'CASH' AND "paymentStatus" = 'PENDING') OR (method <> 'CASH' AND "paymentStatus" = 'AUTHORIZED'))
          THEN 'capture-ready'
        WHEN "paymentStatus" = 'AUTHORIZED' AND "bookingStatus" = 'COMPLETED'
          THEN 'completed-authorization-blocked'
        WHEN "paymentStatus" = 'AUTHORIZED' AND "evidenceState" = 'VERIFIED'
          AND method IN ('MOMO', 'VNPAY', 'CARD', 'BANK_TRANSFER', 'CUSTOMER_WALLET')
          AND "bookingStatus" IN ('CANCELLED', 'EXPIRED', 'NO_SHOW', 'REFUNDED')
          THEN 'release-recommended'
        WHEN method = 'CASH' AND "paymentStatus" = 'PENDING' AND "cashDebt" THEN 'cash-debt'
        WHEN method = 'CASH' AND "paymentStatus" = 'PENDING'
          AND "bookingStatus" IN ('CREATED', 'OPEN_MATCHING', 'MATCHED', 'PROVIDER_ON_THE_WAY', 'ARRIVED', 'IN_SERVICE')
          THEN 'active-cash'
        WHEN "paymentStatus" = 'FAILED'
          AND "bookingStatus" IN ('CREATED', 'OPEN_MATCHING', 'MATCHED', 'PROVIDER_ON_THE_WAY', 'ARRIVED', 'IN_SERVICE')
          THEN 'failed-active'
        WHEN "paymentStatus" = 'CAPTURED' THEN 'history-captured'
        WHEN "paymentStatus" = 'AUTHORIZED' THEN 'authorized-diagnostic'
        ELSE 'needs-action'
      END AS "primaryQueue"
      FROM payment_scoped
    )
  `;
}

function adminPaymentBookingFixtureOwnerSql() {
  return Prisma.sql`
    customer_user."fixtureKind" IS NOT NULL
    OR customer_user."fixtureRunId" IS NOT NULL
    OR customer_user."fixtureExpiresAt" IS NOT NULL
    OR preferred_partner_user."fixtureKind" IS NOT NULL
    OR preferred_partner_user."fixtureRunId" IS NOT NULL
    OR preferred_partner_user."fixtureExpiresAt" IS NOT NULL
    OR partner_user."fixtureKind" IS NOT NULL
    OR partner_user."fixtureRunId" IS NOT NULL
    OR partner_user."fixtureExpiresAt" IS NOT NULL
  `;
}

function adminPaymentBookingLegacyFixtureOwnerSql() {
  return Prisma.sql`
    LOWER(customer_user.id) LIKE 'smoke%'
    OR LOWER(customer_user.id) LIKE 'seed-%'
    OR LOWER(customer_user.id) LIKE 'audit\\_%' ESCAPE '\\'
    OR LOWER(COALESCE(preferred_partner_user.id, '')) LIKE 'smoke%'
    OR LOWER(COALESCE(preferred_partner_user.id, '')) LIKE 'seed-%'
    OR LOWER(COALESCE(preferred_partner_user.id, '')) LIKE 'audit\\_%' ESCAPE '\\'
    OR LOWER(COALESCE(partner_user.id, '')) LIKE 'smoke%'
    OR LOWER(COALESCE(partner_user.id, '')) LIKE 'seed-%'
    OR LOWER(COALESCE(partner_user.id, '')) LIKE 'audit\\_%' ESCAPE '\\'
  `;
}

function adminPaymentOperationsSqlFilter(options: AdminPaymentOperationsQuery) {
  const filters: Prisma.Sql[] = [];
  const review = normalizeAdminPaymentReview(options.review);
  const evidence = normalizeNullable(options.evidence)?.toUpperCase().replace('-', '_');
  if (review && review !== 'all') {
    if (review === 'authorized') filters.push(Prisma.sql`"paymentStatus" = 'AUTHORIZED'`);
    else if (review === 'callback-verified') filters.push(Prisma.sql`"verifiedCallback" = TRUE`);
    else filters.push(Prisma.sql`"primaryQueue" = ${review}`);
  }
  if (evidence) filters.push(Prisma.sql`"evidenceState" = ${evidence}`);
  return filters.length > 0 ? Prisma.sql`WHERE ${Prisma.join(filters, ' AND ')}` : Prisma.empty;
}

function adminPaymentOperationsPageSql(
  options: AdminPaymentOperationsQuery,
  take: number,
  skip: number,
  updatedAtWhere?: Prisma.DateTimeFilter,
) {
  const direction = adminQueueSortDirection(options.sort) === 'asc' ? Prisma.sql`ASC` : Prisma.sql`DESC`;
  return Prisma.sql`
    ${adminPaymentOperationsCte(options, updatedAtWhere)}
    SELECT
      page.id,
      (
        SELECT callback."createdAt"
        FROM "PaymentCallbackAttempt" callback
        WHERE callback."paymentId" = page.id
          AND (
            callback.outcome NOT IN ('ACCEPTED', 'REPLAY')
            OR callback."signatureVerified" IS DISTINCT FROM TRUE
            OR (callback."callbackAmount" IS NOT NULL AND callback."callbackAmount" <> page.amount)
          )
        ORDER BY callback."createdAt" DESC, callback.id DESC
        LIMIT 1
      ) AS "evidenceConflictAt",
      page."evidenceState",
      page."primaryQueue",
      (
        SELECT callback."createdAt"
        FROM "PaymentCallbackAttempt" callback
        WHERE callback."paymentId" = page.id
          AND callback.outcome IN ('ACCEPTED', 'REPLAY')
          AND callback."signatureVerified" = TRUE
          AND (callback."callbackAmount" IS NULL OR callback."callbackAmount" = page.amount)
        ORDER BY callback."createdAt" DESC, callback.id DESC
        LIMIT 1
      ) AS "verifiedCallbackAt"
    FROM (
      SELECT id, amount, "bookingUpdatedAt", "evidenceState", "primaryQueue"
      FROM payment_classified
    ${adminPaymentOperationsSqlFilter(options)}
    ORDER BY "bookingUpdatedAt" ${direction}, id ${direction}
    LIMIT ${take} OFFSET ${skip}
    ) page
    ORDER BY page."bookingUpdatedAt" ${direction}, page.id ${direction}
  `;
}

function adminPaymentOperationDecisionFactSql(paymentId: string) {
  return Prisma.sql`
    ${adminPaymentOperationsCte({}, undefined, paymentId)}
    SELECT
      classified.id,
      (
        SELECT callback."createdAt"
        FROM "PaymentCallbackAttempt" callback
        WHERE callback."paymentId" = classified.id
          AND (
            callback.outcome NOT IN ('ACCEPTED', 'REPLAY')
            OR callback."signatureVerified" IS DISTINCT FROM TRUE
            OR (callback."callbackAmount" IS NOT NULL AND callback."callbackAmount" <> classified.amount)
          )
        ORDER BY callback."createdAt" DESC, callback.id DESC
        LIMIT 1
      ) AS "evidenceConflictAt",
      classified."evidenceState",
      classified."primaryQueue",
      (
        SELECT callback."createdAt"
        FROM "PaymentCallbackAttempt" callback
        WHERE callback."paymentId" = classified.id
          AND callback.outcome IN ('ACCEPTED', 'REPLAY')
          AND callback."signatureVerified" = TRUE
          AND (callback."callbackAmount" IS NULL OR callback."callbackAmount" = classified.amount)
        ORDER BY callback."createdAt" DESC, callback.id DESC
        LIMIT 1
      ) AS "verifiedCallbackAt"
    FROM payment_classified classified
    WHERE classified.id = ${paymentId}
    LIMIT 1
  `;
}

type AdminPaymentDecisionCallbackAttempt = {
  callbackAmount?: number | null;
  createdAt?: Date | string | null;
  outcome?: string | null;
  signatureVerified?: boolean | null;
};

function adminPaymentDecisionCallbackAttempts(
  row: AdminPaymentQueueIdRow | undefined,
  amount: number,
  fallback: readonly AdminPaymentDecisionCallbackAttempt[],
): readonly AdminPaymentDecisionCallbackAttempt[] {
  if (!row?.evidenceState) return fallback;
  if (row.evidenceState === 'CONFLICT') {
    return [
      {
        callbackAmount: amount,
        createdAt: row.evidenceConflictAt ?? null,
        outcome: 'REJECTED',
        signatureVerified: true,
      },
    ];
  }
  if (row.evidenceState === 'VERIFIED' && row.verifiedCallbackAt) {
    return [
      {
        callbackAmount: amount,
        createdAt: row.verifiedCallbackAt,
        outcome: 'ACCEPTED',
        signatureVerified: true,
      },
    ];
  }
  return [];
}

function adminPaymentOperationsCountSql(
  options: AdminPaymentOperationsQuery,
  updatedAtWhere?: Prisma.DateTimeFilter,
) {
  return Prisma.sql`
    ${adminPaymentOperationsCte(options, updatedAtWhere)}
    SELECT COUNT(*) AS count FROM payment_classified
    ${adminPaymentOperationsSqlFilter(options)}
  `;
}

function adminPaymentOperationsAgeAggregateSql(
  options: AdminPaymentOperationsQuery,
  updatedAtWhere?: Prisma.DateTimeFilter,
  now = new Date(),
) {
  const oneHourAgo = new Date(now.getTime() - 60 * 60_000);
  const fourHoursAgo = new Date(now.getTime() - 4 * 60 * 60_000);
  const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60_000);
  const unboundedOptions = { ...options, age: 'all', sla: 'all' };

  return Prisma.sql`
    ${adminPaymentOperationsCte(unboundedOptions, updatedAtWhere)}
    SELECT
      COUNT(*) AS all,
      COUNT(*) FILTER (
        WHERE "bookingUpdatedAt" >= ${oneHourAgo} AND "bookingUpdatedAt" <= ${now}
      ) AS "underOneHour",
      COUNT(*) FILTER (
        WHERE "bookingUpdatedAt" >= ${fourHoursAgo} AND "bookingUpdatedAt" < ${oneHourAgo}
      ) AS "oneToFourHours",
      COUNT(*) FILTER (
        WHERE "bookingUpdatedAt" >= ${twentyFourHoursAgo} AND "bookingUpdatedAt" < ${fourHoursAgo}
      ) AS "fourToTwentyFourHours",
      COUNT(*) FILTER (WHERE "bookingUpdatedAt" < ${twentyFourHoursAgo}) AS "overTwentyFourHours"
    FROM payment_classified
    ${adminPaymentOperationsSqlFilter(unboundedOptions)}
  `;
}

export function adminPaymentOperationsPerformanceQueries(
  options: AdminPaymentOperationsQuery = {},
  take = 10,
  skip = 0,
  now = new Date(),
) {
  return [
    { name: 'list-page', sql: adminPaymentOperationsPageSql(options, take, skip) },
    { name: 'summary-aggregate', sql: adminPaymentOperationsAggregateSql(options) },
    { name: 'summary-current-count', sql: adminPaymentOperationsCountSql(options) },
    { name: 'summary-age-buckets', sql: adminPaymentOperationsAgeAggregateSql(options, undefined, now) },
  ] as const;
}

function adminPaymentOperationsAggregateSql(options: AdminPaymentOperationsQuery) {
  return Prisma.sql`
    ${adminPaymentOperationsCte({ ...options, age: 'all', review: 'all', sla: 'all' })}
    SELECT
      COUNT(*) FILTER (WHERE "primaryQueue" = 'active-cash') AS "activeCashCollection",
      COUNT(*) FILTER (WHERE "paymentStatus" = 'AUTHORIZED') AS authorized,
      COUNT(*) FILTER (WHERE "verifiedCallback") AS "callbackVerified",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'capture-ready') AS "captureReady",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'cash-debt') AS "cashDebt",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'completed-authorization-blocked') AS "completedAuthorizationBlocked",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'evidence-conflict') AS "evidenceConflicts",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'failed-active') AS "failedActive",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'history-captured') AS "historyCaptured",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'history-refunded') AS "historyRefunded",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'history-released') AS "historyReleased",
      COALESCE(SUM("refundCount"), 0) AS "linkedRefunds",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'missing-gateway-evidence') AS "missingGatewayEvidence",
      COUNT(*) FILTER (WHERE "primaryQueue" NOT LIKE 'history-%' AND "primaryQueue" <> 'authorized-diagnostic') AS "needsAction",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'release-recommended') AS "releaseRecommended",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'terminal-cash-cleanup') AS "terminalCashCleanup",
      COUNT(*) FILTER (WHERE "primaryQueue" = 'needs-action') AS "unclassifiedNeedsAction"
    FROM payment_classified
    ${adminPaymentOperationsSqlFilter({ ...options, review: 'all' })}
  `;
}

function adminMergeDateTimeFilters(
  left: Prisma.DateTimeFilter | undefined,
  right: Prisma.DateTimeFilter | undefined,
): Prisma.DateTimeFilter | undefined {
  if (!left) return right;
  if (!right) return left;
  return {
    ...(left.gte ? { gte: left.gte } : {}),
    ...(left.gt ? { gt: left.gt } : {}),
    ...(left.lte ? { lte: left.lte } : {}),
    ...(left.lt ? { lt: left.lt } : {}),
    ...(right.gte ? { gte: right.gte } : {}),
    ...(right.gt ? { gt: right.gt } : {}),
    ...(right.lte ? { lte: right.lte } : {}),
    ...(right.lt ? { lt: right.lt } : {}),
  };
}

function adminMergePaymentOperationsWhere(
  base: Prisma.PaymentWhereInput | undefined,
  next: Prisma.PaymentWhereInput,
): Prisma.PaymentWhereInput {
  return base ? { AND: [base, next] } : next;
}

function adminPaymentCallbackAttemptWhere(
  options: AdminPaymentCallbackAttemptQuery,
): Prisma.PaymentCallbackAttemptWhereInput | undefined {
  const filters: Prisma.PaymentCallbackAttemptWhereInput[] = [
    { payment: { booking: adminBookingProductionDataWhere() } },
  ];
  const customerProfileId = normalizeNullable(options.customerProfileId);
  const dateWhere = adminPaymentCallbackAttemptDateWhere(options.range);
  const reviewWhere = adminPaymentCallbackAttemptReviewWhere(options.review);
  const ageWhere = adminQueueAgeDateWhere(options.age);

  if (dateWhere) {
    filters.push(dateWhere);
  }
  if (reviewWhere) {
    filters.push(reviewWhere);
  }
  if (ageWhere) {
    filters.push({ createdAt: ageWhere });
  }
  if (customerProfileId) {
    filters.push({ payment: { booking: { customerProfileId } } });
  }

  if (filters.length === 0) {
    return undefined;
  }
  return filters.length === 1 ? filters[0] : { AND: filters };
}

const ADMIN_PAYMENT_PRIMARY_QUEUE_ORDER = [
  'evidence-conflict',
  'missing-gateway-evidence',
  'terminal-cash-cleanup',
  'capture-ready',
  'completed-authorization-blocked',
  'release-recommended',
  'cash-debt',
  'active-cash',
  'failed-active',
  'history-captured',
  'history-refunded',
  'history-released',
  'authorized-diagnostic',
  'needs-action',
] as const;

type AdminPaymentPrimaryQueue = (typeof ADMIN_PAYMENT_PRIMARY_QUEUE_ORDER)[number];

function normalizeAdminPaymentReview(review: string | null | undefined) {
  switch (normalizeNullable(review)) {
    case 'callback-review':
      return 'evidence-conflict';
    case 'stale-mismatch':
      return 'terminal-cash-cleanup';
    case 'capture':
      return 'capture-ready';
    case 'cash':
      return 'active-cash';
    case 'missing-ref':
      return 'missing-gateway-evidence';
    case 'all-authorized':
      return 'authorized';
    default:
      return normalizeNullable(review);
  }
}

function adminPaymentReviewWhere(review: string | null | undefined): Prisma.PaymentWhereInput | undefined {
  const normalized = normalizeAdminPaymentReview(review);
  if (normalized && ADMIN_PAYMENT_PRIMARY_QUEUE_ORDER.includes(normalized as AdminPaymentPrimaryQueue)) {
    return adminPaymentPrimaryQueueWhere(normalized as AdminPaymentPrimaryQueue);
  }
  switch (normalized) {
    case 'capture-ready':
    case 'release-recommended':
    case 'missing-gateway-evidence':
      return adminPaymentPrimaryQueueWhere(normalized);
    case 'authorized':
      return { status: PaymentStatus.AUTHORIZED };
    case 'callback-verified':
      return { callbackAttempts: { some: adminPaymentCallbackAttemptVerifiedWhere() } };
    case 'refunded':
    case 'history-refunded':
      return { status: PaymentStatus.REFUNDED };
    case 'history-captured':
      return { status: PaymentStatus.CAPTURED };
    case 'history-released':
      return { status: PaymentStatus.RELEASED };
    default:
      return undefined;
  }
}

function adminPaymentPrimaryQueueWhere(queue: AdminPaymentPrimaryQueue): Prisma.PaymentWhereInput {
  const index = ADMIN_PAYMENT_PRIMARY_QUEUE_ORDER.indexOf(queue);
  const base = adminPaymentPrimaryQueueBaseWhere(queue);
  const previous = ADMIN_PAYMENT_PRIMARY_QUEUE_ORDER.slice(0, index).map((candidate) => ({
    NOT: adminPaymentPrimaryQueueBaseWhere(candidate),
  }));
  return previous.length > 0 ? { AND: [base, ...previous] } : base;
}

function adminPaymentPrimaryQueueBaseWhere(queue: AdminPaymentPrimaryQueue): Prisma.PaymentWhereInput {
  const externalMethods = [
    PaymentMethod.MOMO,
    PaymentMethod.VNPAY,
    PaymentMethod.CARD,
    PaymentMethod.BANK_TRANSFER,
  ];
  const terminalStatuses = [
    BookingStatus.CANCELLED,
    BookingStatus.EXPIRED,
    BookingStatus.NO_SHOW,
    BookingStatus.REFUNDED,
  ];
  const externalVerified: Prisma.PaymentWhereInput = {
    callbackAttempts: {
      none: adminPaymentCallbackAttemptNeedsReviewWhere(),
      some: adminPaymentCallbackAttemptVerifiedWhere(),
    },
    method: { in: externalMethods },
    providerRef: { not: null },
  };
  const walletVerified: Prisma.PaymentWhereInput = {
    booking: { customerWalletLedgerEntries: { some: { amount: { lt: 0 } } } },
    method: PaymentMethod.CUSTOMER_WALLET,
  };
  const cashVerified: Prisma.PaymentWhereInput = {
    AND: [
      { method: PaymentMethod.CASH },
      { rawMeta: { path: ['cashCollectedAt'], not: Prisma.AnyNull } },
      { rawMeta: { path: ['cashCollectedBy'], not: Prisma.AnyNull } },
      { rawMeta: { path: ['cashCollectionReference'], not: Prisma.AnyNull } },
    ],
  };

  switch (queue) {
    case 'evidence-conflict':
      return { callbackAttempts: { some: adminPaymentCallbackAttemptNeedsReviewWhere() } };
    case 'missing-gateway-evidence':
      return {
        callbackAttempts: { none: adminPaymentCallbackAttemptNeedsReviewWhere() },
        method: { in: externalMethods },
        OR: [
          { providerRef: null },
          { callbackAttempts: { none: adminPaymentCallbackAttemptVerifiedWhere() } },
        ],
      };
    case 'terminal-cash-cleanup':
      return {
        booking: { status: { in: terminalStatuses } },
        method: PaymentMethod.CASH,
        status: PaymentStatus.PENDING,
      };
    case 'capture-ready':
      return {
        booking: { status: BookingStatus.COMPLETED },
        OR: [
          { AND: [externalVerified, { status: PaymentStatus.AUTHORIZED }] },
          { AND: [walletVerified, { status: PaymentStatus.AUTHORIZED }] },
          { AND: [cashVerified, { status: PaymentStatus.PENDING }] },
        ],
      };
    case 'completed-authorization-blocked':
      return { booking: { status: BookingStatus.COMPLETED }, status: PaymentStatus.AUTHORIZED };
    case 'release-recommended':
      return {
        booking: { status: { in: terminalStatuses } },
        OR: [externalVerified, walletVerified],
        status: PaymentStatus.AUTHORIZED,
      };
    case 'cash-debt':
      return {
        booking: { earning: { is: { netAmount: { lt: 0 }, status: { not: EarningStatus.PAID } } } },
        method: PaymentMethod.CASH,
        status: PaymentStatus.PENDING,
      };
    case 'active-cash':
      return {
        booking: { status: { in: Array.from(ADMIN_VIETNAM_ACTIVE_BOOKING_STATUSES) } },
        method: PaymentMethod.CASH,
        status: PaymentStatus.PENDING,
      };
    case 'failed-active':
      return {
        booking: { status: { in: Array.from(ADMIN_VIETNAM_ACTIVE_BOOKING_STATUSES) } },
        status: PaymentStatus.FAILED,
      };
    case 'history-captured':
      return { status: PaymentStatus.CAPTURED };
    case 'history-refunded':
      return { status: PaymentStatus.REFUNDED };
    case 'history-released':
      return { status: PaymentStatus.RELEASED };
    case 'authorized-diagnostic':
      return { status: PaymentStatus.AUTHORIZED };
    case 'needs-action':
      return { status: { notIn: [PaymentStatus.CAPTURED, PaymentStatus.REFUNDED, PaymentStatus.RELEASED] } };
  }
}

function adminPaymentEvidenceWhere(
  evidence: string | null | undefined,
): Prisma.PaymentWhereInput | undefined {
  const externalMethods = [
    PaymentMethod.MOMO,
    PaymentMethod.VNPAY,
    PaymentMethod.CARD,
    PaymentMethod.BANK_TRANSFER,
  ];
  switch (normalizeNullable(evidence)) {
    case 'verified':
      return {
        OR: [
          {
            callbackAttempts: {
              none: adminPaymentCallbackAttemptNeedsReviewWhere(),
              some: adminPaymentCallbackAttemptVerifiedWhere(),
            },
            method: { in: externalMethods },
            providerRef: { not: null },
          },
          {
            booking: { customerWalletLedgerEntries: { some: { amount: { lt: 0 } } } },
            method: PaymentMethod.CUSTOMER_WALLET,
          },
          { method: PaymentMethod.CASH },
        ],
      };
    case 'conflict':
      return { callbackAttempts: { some: adminPaymentCallbackAttemptNeedsReviewWhere() } };
    case 'missing':
      return {
        OR: [
          {
            method: { in: externalMethods },
            OR: [
              { providerRef: null },
              { callbackAttempts: { none: adminPaymentCallbackAttemptVerifiedWhere() } },
            ],
          },
          {
            booking: { customerWalletLedgerEntries: { none: { amount: { lt: 0 } } } },
            method: PaymentMethod.CUSTOMER_WALLET,
          },
          { method: PaymentMethod.CASH },
        ],
      };
    case 'not-applicable':
      return { method: PaymentMethod.MANUAL };
    default:
      return undefined;
  }
}

function normalizeAdminPaymentStatus(value: string | null | undefined): PaymentStatus | null {
  const normalized = normalizeNullable(value)?.toUpperCase();
  return normalized && Object.values(PaymentStatus).includes(normalized as PaymentStatus)
    ? (normalized as PaymentStatus)
    : null;
}

function normalizeAdminBookingStatus(value: string | null | undefined): BookingStatus | null {
  const normalized = normalizeNullable(value)?.toUpperCase();
  return normalized && Object.values(BookingStatus).includes(normalized as BookingStatus)
    ? (normalized as BookingStatus)
    : null;
}

function adminPaymentCallbackAttemptReviewWhere(
  review: string | null | undefined,
): Prisma.PaymentCallbackAttemptWhereInput | undefined {
  if (normalizeNullable(review) === 'callback-review') {
    return adminPaymentCallbackAttemptNeedsReviewWhere();
  }
  if (normalizeNullable(review) === 'callback-verified') {
    return adminPaymentCallbackAttemptVerifiedWhere();
  }
  if (normalizeNullable(review) === 'failed-active') {
    return {
      payment: {
        booking: {
          status: {
            in: [
              BookingStatus.CREATED,
              BookingStatus.OPEN_MATCHING,
              BookingStatus.MATCHED,
              BookingStatus.PROVIDER_ON_THE_WAY,
              BookingStatus.ARRIVED,
              BookingStatus.IN_SERVICE,
            ],
          },
        },
        status: PaymentStatus.FAILED,
      },
    };
  }
  return undefined;
}

function adminPaymentCallbackAttemptNeedsReviewWhere(): Prisma.PaymentCallbackAttemptWhereInput {
  return {
    OR: [
      { outcome: { notIn: ['ACCEPTED', 'REPLAY'] } },
      { outcome: { in: ['ACCEPTED', 'REPLAY'] }, signatureVerified: { not: true } },
    ],
  };
}

function adminPaymentCallbackAttemptVerifiedWhere(): Prisma.PaymentCallbackAttemptWhereInput {
  return {
    outcome: { in: ['ACCEPTED', 'REPLAY'] },
    signatureVerified: true,
  };
}

function adminPaymentBookingDateWhere(
  range: string | null | undefined,
): Prisma.BookingWhereInput | undefined {
  const dateRange = adminPaymentDateRangeWhere(range);
  return dateRange ? { OR: [{ createdAt: dateRange }] } : undefined;
}

function adminPaymentCallbackAttemptDateWhere(
  range: string | null | undefined,
): Prisma.PaymentCallbackAttemptWhereInput | undefined {
  const dateRange = adminPaymentDateRangeWhere(range);
  return dateRange ? { createdAt: dateRange } : undefined;
}

function adminPaymentDateRangeWhere(range: string | null | undefined): Prisma.DateTimeFilter | undefined {
  const bounds = adminPaymentDateRangeBounds(range);
  if (!bounds) {
    return undefined;
  }

  return {
    gte: new Date(bounds.startMs),
    lte: new Date(bounds.endMs),
  };
}

function adminPreviousPaymentDateRangeWhere(
  range: string | null | undefined,
): Prisma.DateTimeFilter | undefined {
  const bounds = adminPaymentDateRangeBounds(range);
  if (!bounds) {
    return undefined;
  }
  const windowDurationMs = bounds.endMs - bounds.startMs + 1;

  return {
    gte: new Date(bounds.startMs - windowDurationMs),
    lte: new Date(bounds.startMs - 1),
  };
}

function adminFinanceOverviewComparisonSummary(
  current: {
    count: number;
    customerPaymentAmount: number;
    partnerPayoutAmount: number;
    platformFeeNetRevenue: number;
  },
  previous: {
    settlementCount: number;
    customerPaymentAmount: number;
    partnerPayoutAmount: number;
    platformFeeNetRevenue: number;
  },
  range: string | null | undefined,
) {
  return {
    previousRangeLabel: adminFinanceOverviewPreviousRangeLabel(range),
    settlementCount: adminFinanceOverviewComparisonMetric(current.count, previous.settlementCount),
    customerPaymentAmount: adminFinanceOverviewComparisonMetric(
      current.customerPaymentAmount,
      previous.customerPaymentAmount,
    ),
    partnerPayoutAmount: adminFinanceOverviewComparisonMetric(
      current.partnerPayoutAmount,
      previous.partnerPayoutAmount,
    ),
    platformFeeNetRevenue: adminFinanceOverviewComparisonMetric(
      current.platformFeeNetRevenue,
      previous.platformFeeNetRevenue,
    ),
  };
}

function adminFinanceOverviewComparisonMetric(current: number, previous: number) {
  return {
    current,
    previous,
    delta: current - previous,
    deltaPercent: previous === 0 ? null : Math.round(((current - previous) / previous) * 1000) / 10,
  };
}

function adminFinanceOverviewPreviousRangeLabel(range: string | null | undefined) {
  switch (normalizeNullable(range)) {
    case '7d':
      return 'Previous 7 days';
    case '30d':
      return 'Previous 30 days';
    case '90d':
      return 'Previous 90 days';
    case 'today':
    default:
      return 'Previous day';
  }
}

function adminPaymentDateRangeBounds(range: string | null | undefined) {
  const nowMs = Date.now();
  const todayStartMs = startOfLocalDay(nowMs);
  const todayEndMs = endOfLocalDay(todayStartMs);

  switch (normalizeNullable(range) ?? 'today') {
    case '7d':
      return { startMs: addLocalDays(todayStartMs, -6), endMs: todayEndMs };
    case '30d':
      return { startMs: addLocalDays(todayStartMs, -29), endMs: todayEndMs };
    case '90d':
      return { startMs: addLocalDays(todayStartMs, -89), endMs: todayEndMs };
    case 'all':
      return undefined;
    case 'today':
    default:
      return { startMs: todayStartMs, endMs: todayEndMs };
  }
}

function adminStartShiftRange(range: string | null | undefined) {
  const normalized = normalizeNullable(range);
  switch (normalized) {
    case '7d':
    case '30d':
    case '90d':
    case 'all':
      return normalized;
    case 'today':
    default:
      return 'today' as const;
  }
}

function adminStartShiftAnalyticsGranularity(range: string) {
  if (range === 'today') {
    return 'hour' as const;
  }
  if (range === 'all') {
    return 'month' as const;
  }
  return 'day' as const;
}

function adminStartShiftNotificationRange(range: string) {
  const bounds = adminPaymentDateRangeBounds(range);
  if (!bounds) {
    return {};
  }
  return {
    from: new Date(bounds.startMs).toISOString(),
    to: new Date(bounds.endMs + 1).toISOString(),
  };
}

function adminSettledValue<T>(result: PromiseSettledResult<T>): T | null {
  return result.status === 'fulfilled' ? result.value : null;
}

function adminMergePaymentBookingWhere(
  existing: Prisma.BookingWhereInput | undefined,
  next: Prisma.BookingWhereInput,
): Prisma.BookingWhereInput {
  return existing ? { ...existing, ...next } : next;
}

function adminRefundOperationsWhere(
  options: AdminRefundOperationsQuery,
): Prisma.RefundWhereInput | undefined {
  let where = adminMergeRefundOperationsWhere(adminRefundReviewWhere(options.review), {
    booking: adminBookingProductionDataWhere(),
  });
  const customerProfileId = normalizeNullable(options.customerProfileId);
  const dateRange = adminPaymentDateRangeWhere(options.range);
  const ageWhere = adminRefundQueueAgeDateWhere(options.age);
  const query = normalizeNullable(options.q);

  if (dateRange) {
    where = adminMergeRefundOperationsWhere(where, { createdAt: dateRange });
  }
  if (customerProfileId) {
    where = adminMergeRefundOperationsWhere(where, {
      booking: { customerProfileId },
    });
  }
  if (ageWhere) {
    where = adminMergeRefundOperationsWhere(where, {
      createdAt: ageWhere,
    });
  }
  if (query) {
    where = adminMergeRefundOperationsWhere(where, {
      OR: [
        { id: { contains: query, mode: 'insensitive' } },
        { bookingId: { contains: query, mode: 'insensitive' } },
        { paymentId: { contains: query, mode: 'insensitive' } },
        {
          booking: {
            customerProfile: {
              user: {
                OR: [
                  { fullName: { contains: query, mode: 'insensitive' } },
                  { phone: { contains: query, mode: 'insensitive' } },
                ],
              },
            },
          },
        },
      ],
    });
  }

  return Object.keys(where).length > 0 ? where : undefined;
}

function adminMergeRefundOperationsWhere(
  base: Prisma.RefundWhereInput | undefined,
  next: Prisma.RefundWhereInput,
): Prisma.RefundWhereInput {
  return base ? { AND: [base, next] } : next;
}

function adminRefundCountArgs(where: Prisma.RefundWhereInput | undefined): Prisma.RefundCountArgs {
  return where ? { where } : {};
}

type AdminRefundOperationsRecord = {
  booking?: { status?: string | null } | null;
  payment?: { status?: string | null } | null;
  status: string;
};

function adminRefundOperationsReadModel<T extends AdminRefundOperationsRecord>(refund: T) {
  const stateMismatchReason = adminRefundStateMismatchReason(refund);
  const operationalStage = adminRefundOperationalStage(refund);

  return {
    ...refund,
    assignee:
      operationalStage === 'STATE_MISMATCH'
        ? 'Finance reconciliation'
        : operationalStage === 'AWAITING_DECISION'
          ? 'Finance approval'
          : operationalStage === 'PAYMENT_PROCESSING'
            ? 'Payment operations'
            : operationalStage === 'REVIEW_REQUIRED'
              ? 'Finance operations'
              : null,
    nextAction:
      operationalStage === 'STATE_MISMATCH'
        ? 'Reconcile refund, payment, and booking states'
        : operationalStage === 'AWAITING_DECISION'
          ? 'Review evidence and approve or reject'
          : operationalStage === 'PAYMENT_PROCESSING'
            ? 'Check payment refund progress'
            : operationalStage === 'CLOSED'
              ? 'Review closed refund evidence'
              : operationalStage === 'REJECTED'
                ? 'Review rejection record'
                : 'Review refund state',
    operationalStage,
    stateMismatchReason,
  };
}

function adminBoundedPositiveInteger(
  value: number | string | null | undefined,
  defaultValue: number,
  maxValue: number,
) {
  if (value === null || value === undefined || value === '') {
    return defaultValue;
  }

  const parsed = typeof value === 'number' ? value : Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return defaultValue;
  }

  return Math.min(Math.trunc(parsed), maxValue);
}

function normalizeNotificationBoardTake(value: string | undefined) {
  const parsed = Number.parseInt(value ?? '', 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return ADMIN_NOTIFICATION_BOARD_DEFAULT_LIMIT;
  }
  return Math.min(parsed, ADMIN_NOTIFICATION_BOARD_MAX_LIMIT);
}

function normalizeNotificationBoardSkip(value: string | undefined) {
  const parsed = Number.parseInt(value ?? '', 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return 0;
  }
  if (parsed > ADMIN_NOTIFICATION_BOARD_MAX_SKIP) {
    throw new BadRequestException(
      `Notification skip must not exceed ${ADMIN_NOTIFICATION_BOARD_MAX_SKIP}. Narrow the date range or search filters.`,
    );
  }
  return parsed;
}

function adminQueueSlaSqlCondition(
  occurredAt: Prisma.Sql,
  bounds?: { readonly afterAt?: Date; readonly beforeAt?: Date },
) {
  if (bounds?.afterAt && bounds.beforeAt) {
    return Prisma.sql`AND ${occurredAt} > ${bounds.afterAt} AND ${occurredAt} <= ${bounds.beforeAt}`;
  }
  if (bounds?.afterAt) {
    return Prisma.sql`AND ${occurredAt} > ${bounds.afterAt}`;
  }
  if (bounds?.beforeAt) {
    return Prisma.sql`AND ${occurredAt} <= ${bounds.beforeAt}`;
  }
  return Prisma.empty;
}

function notificationCountArgs(where?: Prisma.NotificationWhereInput): Prisma.NotificationCountArgs {
  return where ? { where } : {};
}

function notificationBoardAndWhere(
  baseWhere?: Prisma.NotificationWhereInput,
  extraWhere?: Prisma.NotificationWhereInput,
): Prisma.NotificationWhereInput | undefined {
  const filters = [baseWhere, extraWhere].filter(Boolean) as Prisma.NotificationWhereInput[];
  if (filters.length === 0) {
    return undefined;
  }
  if (filters.length === 1) {
    return filters[0];
  }
  return { AND: filters };
}

type NotificationBoardSummaryOptions = {
  readonly campaignId?: string;
  readonly age?: string;
  readonly booking?: string;
  readonly financeAge?: string;
  readonly financeOwner?: string;
  readonly from?: string;
  readonly incidentState?: string;
  readonly review?: string;
  readonly sla?: string;
  readonly to?: string;
  readonly user?: string;
  readonly sort?: string;
  readonly q?: string;
  readonly recipientRole?: string;
  readonly channel?: string;
  readonly failureCode?: string;
  readonly failureProvider?: string;
  readonly scope?: string;
  readonly dataScope?: string;
  readonly viewMode?: string;
};

type NotificationDeliveryHealthCounts = {
  readonly deliveryGaps: number;
  readonly failed: number;
  readonly noPushPathNotificationCount: number;
  readonly noPushPathRecipientCount: number;
  readonly staleRouteNotifications: number;
};

function addNotificationDeliveryHealth(
  current: NotificationDeliveryHealthCounts | undefined,
  history: NotificationDeliveryHealthCounts | undefined,
): NotificationDeliveryHealthCounts | undefined {
  if (!current || !history) return undefined;
  return {
    deliveryGaps: current.deliveryGaps + history.deliveryGaps,
    failed: current.failed + history.failed,
    noPushPathNotificationCount: current.noPushPathNotificationCount + history.noPushPathNotificationCount,
    noPushPathRecipientCount: current.noPushPathRecipientCount + history.noPushPathRecipientCount,
    staleRouteNotifications: current.staleRouteNotifications + history.staleRouteNotifications,
  };
}

type NotificationBoardQueryOptions = NotificationBoardSummaryOptions & {
  readonly skip?: string;
  readonly take?: string;
};

type AdminNotificationTemplateListQuery = {
  readonly skip?: string;
  readonly take?: string;
};

function notificationBoardWhere(
  options: NotificationBoardSummaryOptions,
): Prisma.NotificationWhereInput | undefined {
  const where: Prisma.NotificationWhereInput = {};
  const dateWhere = notificationBoardDateWhere(options);
  const filters: Prisma.NotificationWhereInput[] = [adminNotificationDataScopeWhere(options.dataScope)];
  const booking = normalizeNullable(options.booking);
  const user = normalizeNullable(options.user);
  const reviewWhere = notificationBoardReviewWhere(options.review);
  const incidentStateWhere = notificationBoardIncidentStateWhere(options.incidentState);
  const ageWhere = adminQueueAgeDateWhere(options.age);
  const search = normalizeNullable(options.q);
  const recipientRole = normalizeNotificationRecipientRole(options.recipientRole);
  const channel = normalizeNotificationChannel(options.channel);
  const campaignId = normalizeNullable(options.campaignId);

  if (dateWhere) {
    Object.assign(where, dateWhere);
  }
  if (booking) {
    filters.push({ data: { path: ['bookingId'], equals: booking } });
  }
  if (user) {
    filters.push({ userId: user });
  }
  if (campaignId) {
    filters.push({ data: { path: ['campaignId'], equals: campaignId } });
  }
  if (reviewWhere) {
    filters.push(reviewWhere);
  }
  if (incidentStateWhere) {
    filters.push(incidentStateWhere);
  }
  if (ageWhere) {
    filters.push({ createdAt: ageWhere });
  }
  if (search) {
    filters.push({
      OR: [
        { id: { contains: search, mode: Prisma.QueryMode.insensitive } },
        { userId: { contains: search, mode: Prisma.QueryMode.insensitive } },
        { user: { fullName: { contains: search, mode: Prisma.QueryMode.insensitive } } },
        {
          user: {
            providerProfile: { displayName: { contains: search, mode: Prisma.QueryMode.insensitive } },
          },
        },
        { data: { path: ['bookingId'], string_contains: search } },
      ],
    });
  }
  if (recipientRole) {
    filters.push({ user: { roles: { has: recipientRole } } });
  }
  if (channel) {
    filters.push(notificationDeliveryProviderWhere(channel));
  }
  if (filters.length > 0) {
    where.AND = filters;
  }

  return Object.keys(where).length > 0 ? where : undefined;
}

function normalizeNotificationRecipientRole(value: string | undefined) {
  const normalized = normalizeNullable(value)?.toUpperCase();
  return normalized === 'CUSTOMER' || normalized === 'PROVIDER' || normalized === 'ADMIN'
    ? (normalized as Role)
    : null;
}

function normalizeNotificationChannel(value: string | undefined) {
  const normalized = normalizeNullable(value)?.toUpperCase();
  return normalized === 'FCM' || normalized === 'IN_APP_ONLY' ? normalized : null;
}

function notificationBoardReviewWhere(value: string | undefined): Prisma.NotificationWhereInput | undefined {
  const review = normalizeNullable(value);
  switch (review) {
    case 'disabled-device':
      return { user: { pushDevices: { some: { enabled: false } } } };
    case 'failed':
      return notificationDeliveryStatusWhere('FAILED');
    case 'unresolved-failed':
      return {
        AND: [
          notificationDeliveryStatusWhere('FAILED'),
          {
            deliveries: {
              none: { status: { in: ['SENT', 'DELIVERED', 'SUCCESS'] } },
            },
          },
        ],
      };
    case 'fcm':
      return notificationDeliveryProviderWhere('FCM');
    case 'finance-overdue':
      return notificationFinanceOverdueWhere('open');
    case 'finance-overdue-history':
      return notificationFinanceOverdueWhere('resolved');
    case 'in-app-route':
      return notificationDeliveryProviderWhere('IN_APP_ONLY');
    case 'needs-retry':
      return {
        OR: [
          notificationDeliveryStatusWhere('FAILED'),
          { user: { pushDevices: { some: { enabled: false } } } },
          notificationStaleDeliveryCandidateWhere(),
        ],
      };
    case 'no-show':
      return { type: 'booking.no_show' };
    case 'partner-alerts':
      return { type: { in: [...ADMIN_NOTIFICATION_PARTNER_ALERT_TYPES] } };
    case 'payout-setup':
      return { type: 'provider.payout_setup_required' };
    case 'delivery-gap':
    case 'no-push-path':
    case 'pending':
    case 'unattempted':
      return { deliveries: { none: {} } };
    case 'sent':
      return notificationDeliveryStatusWhere('SENT');
    case 'skipped':
      return notificationDeliveryStatusWhere('SKIPPED');
    case 'stale-device':
      return notificationStaleDeliveryCandidateWhere();
    case 'system-incidents':
      return { type: { startsWith: 'admin.system.' } };
    default:
      return undefined;
  }
}

function notificationBoardUnattemptedDisposition(
  value: string | undefined,
): AdminNotificationUnattemptedDisposition | null {
  switch (normalizeNullable(value)) {
    case 'delivery-gap':
      return 'delivery-gap';
    case 'no-push-path':
      return 'no-push-path';
    case 'pending':
    case 'unattempted':
      return 'unattempted';
    default:
      return null;
  }
}

function notificationBoardDeliveryDisposition(
  value: string | undefined,
): AdminNotificationDeliveryDisposition | null {
  switch (normalizeNullable(value)) {
    case 'failed':
    case 'needs-retry':
      return 'failed';
    case 'sent':
      return 'delivered';
    case 'skipped':
      return 'skipped';
    default:
      return null;
  }
}

function notificationDeliveryIncidentMode(value: string | undefined): AdminNotificationIncidentMode | null {
  switch (normalizeNullable(value)) {
    case 'delivery-incidents':
      return 'current';
    case 'delivery-incident-history':
      return 'historical';
    case 'delivery-incidents-all':
      return 'all';
    default:
      return null;
  }
}

function notificationFinanceOverdueWhere(state: 'open' | 'resolved'): Prisma.NotificationWhereInput {
  const typeWhere: Prisma.NotificationWhereInput = {
    type: { in: [...ADMIN_NOTIFICATION_FINANCE_OVERDUE_TYPES] },
  };
  if (state === 'resolved') {
    return {
      AND: [typeWhere, { data: { path: ['financeReviewStatus'], equals: 'RESOLVED' } }],
    };
  }
  return {
    AND: [
      typeWhere,
      {
        OR: [
          { data: { path: ['financeReviewStatus'], equals: Prisma.AnyNull } },
          { data: { path: ['financeReviewStatus'], not: 'RESOLVED' } },
        ],
      },
    ],
  };
}

function notificationBackgroundJobIncidentId(notification: {
  readonly data: Prisma.JsonValue | null;
  readonly type: string;
}) {
  if (!notification.type.startsWith('admin.system.background_job')) return null;
  return jsonString(jsonObject(notification.data).incidentId);
}

function legacyNotificationReviewSource(notification: {
  readonly data: Prisma.JsonValue | null;
  readonly id: string;
  readonly type: string;
}) {
  if (!notification.type.startsWith('admin.system.background_job')) return null;
  const data = jsonObject(notification.data);
  const queueName = jsonString(data.queueName);
  const jobId = jsonString(data.jobId);
  if (!queueName || !jobId) return null;
  return { jobId, queueName, sourceKey: `job:${queueName}:${jobId}` };
}

