function notificationDeliveryIncidentPageNotifications<
  T extends { readonly data: Prisma.JsonValue | null; readonly id: string },
>(
  notifications: readonly T[],
  incidents: readonly AdminNotificationIncidentPageRow[],
  mode: AdminNotificationIncidentMode,
  windowMinutes: number,
): T[] {
  const notificationById = new Map(notifications.map((notification) => [notification.id, notification]));
  return incidents.flatMap((incident) => {
    const notification = notificationById.get(incident.id);
    if (!notification) return [];
    return [
      {
        ...notification,
        data: toJson({
          ...jsonObject(notification.data),
          deliveryIncidentAffectedUserCount: incident.affectedUserCount,
          deliveryIncidentCustomerFallback: 'DIRECT_CONTACT',
          deliveryIncidentFailureCode: incident.failureCode,
          deliveryIncidentFirstOccurredAt: incident.firstOccurredAt.toISOString(),
          deliveryIncidentHistory: mode === 'historical',
          deliveryIncidentKey: `${incident.provider}:${incident.failureCode}:${incident.windowStartedAt.toISOString()}`,
          deliveryIncidentLastOccurredAt: incident.lastOccurredAt.toISOString(),
          deliveryIncidentNotificationCount: incident.notificationCount,
          deliveryIncidentOwner: 'Platform',
          deliveryIncidentProvider: incident.provider,
          deliveryIncidentWindowMinutes: windowMinutes,
          deliveryIncidentWindowStartedAt: incident.windowStartedAt.toISOString(),
        }),
      } as T,
    ];
  });
}

function notificationBoardIncidentStateWhere(
  value: string | undefined,
): Prisma.NotificationWhereInput | undefined {
  const incidentState = normalizeNullable(value)?.toLowerCase();
  if (!incidentState || incidentState === 'all') return undefined;
  const systemIncidentWhere: Prisma.NotificationWhereInput = {
    type: { startsWith: 'admin.system.' },
  };
  if (incidentState === 'open') {
    return {
      AND: [systemIncidentWhere, { data: { path: ['incidentStatus'], equals: 'OPEN' } }],
    };
  }
  if (incidentState === 'recovered') {
    return {
      AND: [systemIncidentWhere, { data: { path: ['incidentStatus'], equals: 'RECOVERED' } }],
    };
  }
  if (incidentState === 'reviewed') {
    return {
      AND: [systemIncidentWhere, { data: { path: ['incidentStatus'], equals: 'LEGACY_REVIEWED' } }],
    };
  }
  if (incidentState === 'legacy') {
    return {
      AND: [systemIncidentWhere, { data: { path: ['incidentStatus'], equals: Prisma.AnyNull } }],
    };
  }
  return undefined;
}

function notificationDeliveryStatusWhere(status: string): Prisma.NotificationWhereInput {
  return { deliveries: { some: { status } } };
}

function notificationDeliveryProviderWhere(provider: string): Prisma.NotificationWhereInput {
  return { deliveries: { some: { provider } } };
}

function notificationStaleDeliveryCandidateWhere(): Prisma.NotificationWhereInput {
  return {
    deliveries: {
      some: {
        pushDevice: {
          enabled: true,
          lastSeenAt: {
            lte: new Date(Date.now() - ADMIN_NOTIFICATION_STALE_DEVICE_AGE_DAYS * 24 * 60 * 60 * 1000),
          },
        },
      },
    },
  };
}

function notificationBoardDateWhere(options: {
  readonly from?: string;
  readonly to?: string;
}): Prisma.NotificationWhereInput | undefined {
  const from = normalizeNotificationDateBoundary(options.from, 'from');
  const to = normalizeNotificationDateBoundary(options.to, 'to');
  if (!from && !to) {
    return undefined;
  }
  if (from && to && from.getTime() >= to.getTime()) {
    throw new BadRequestException('Notification date range is invalid');
  }

  return {
    createdAt: {
      ...(from ? { gte: from } : {}),
      ...(to ? { lt: to } : {}),
    },
  };
}

function normalizeNotificationDateBoundary(value: string | undefined, field: string) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return undefined;
  }
  const timestamp = Date.parse(normalized);
  if (!Number.isFinite(timestamp)) {
    throw new BadRequestException(`Notification ${field} date is invalid`);
  }
  return new Date(timestamp);
}

function normalizeAdminPushCampaignHistoryTake(value: string | undefined) {
  const parsed = Number.parseInt(value ?? '', 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return ADMIN_PUSH_CAMPAIGN_HISTORY_DEFAULT_LIMIT;
  }
  return Math.min(parsed, ADMIN_PUSH_CAMPAIGN_HISTORY_MAX_LIMIT);
}

function normalizeAdminPushCampaignHistorySkip(value: string | undefined) {
  const parsed = Number.parseInt(value ?? '', 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return 0;
  }
  if (parsed > ADMIN_PUSH_CAMPAIGN_HISTORY_MAX_SKIP) {
    throw new BadRequestException(
      `Push campaign skip must not exceed ${ADMIN_PUSH_CAMPAIGN_HISTORY_MAX_SKIP}. Narrow the history range.`,
    );
  }
  return parsed;
}

function adminPushCampaignHistoryDateWhere(options: {
  readonly from?: string;
  readonly to?: string;
}): Prisma.AdminPushCampaignWhereInput | undefined {
  const from = normalizeAdminPushCampaignDateBoundary(options.from, 'from');
  const to = normalizeAdminPushCampaignDateBoundary(options.to, 'to');
  if (!from && !to) {
    return undefined;
  }
  if (from && to && from.getTime() >= to.getTime()) {
    throw new BadRequestException('Push campaign date range is invalid');
  }

  return {
    createdAt: {
      ...(from ? { gte: from } : {}),
      ...(to ? { lt: to } : {}),
    },
  };
}

function normalizeAdminPushCampaignDateBoundary(value: string | undefined, field: string) {
  const normalized = normalizeNullable(value);
  if (!normalized) {
    return undefined;
  }
  const timestamp = Date.parse(normalized);
  if (!Number.isFinite(timestamp)) {
    throw new BadRequestException(`Push campaign ${field} date is invalid`);
  }
  return new Date(timestamp);
}

function normalizeNotificationTemplateKey(value: string) {
  const key = normalizeNullable(value);
  if (
    !key ||
    !/^[a-z0-9_.-]+$/i.test(key) ||
    !DEFAULT_NOTIFICATION_TEMPLATES.some((template) => template.key === key)
  ) {
    throw new BadRequestException('Unsupported notification template key');
  }
  return key;
}

function normalizeNotificationTemplateLocale(value: string) {
  const locale = normalizeNullable(value);
  if (!locale || !isNotificationTemplateLocale(locale)) {
    throw new BadRequestException('Unsupported notification locale');
  }
  return locale;
}

function normalizeNotificationTemplateTranslations(input: UpdateNotificationTemplateDto) {
  const translations = input.translations?.length
    ? input.translations
    : input.locale && input.title && input.body
      ? [{ body: input.body, locale: input.locale, title: input.title }]
      : [];

  if (translations.length === 0 && typeof input.enabled !== 'boolean') {
    throw new BadRequestException('At least one notification translation is required');
  }

  const normalized = translations.map((translation) => {
    const locale = normalizeNotificationTemplateLocale(translation.locale);
    const title = normalizeNullable(translation.title);
    const body = normalizeNullable(translation.body);
    if (!title || !body) {
      throw new BadRequestException(`Notification ${locale} title and body are required`);
    }
    if (translation.confirmIdenticalTranslation && (locale === 'en' || !translation.reviewedAndReady)) {
      throw new BadRequestException(
        'Identical-language confirmation is only valid for a reviewed non-English translation',
      );
    }
    return {
      body,
      confirmIdenticalTranslation: translation.confirmIdenticalTranslation === true,
      locale,
      reviewedAndReady: translation.reviewedAndReady === true,
      title,
    };
  });
  if (normalized.length > NOTIFICATION_TEMPLATE_LOCALES.length) {
    throw new BadRequestException('Too many notification translations');
  }
  if (new Set(normalized.map((translation) => translation.locale)).size !== normalized.length) {
    throw new BadRequestException('Notification translation locales must be unique');
  }
  return normalized;
}

function notificationTemplateContractView<
  T extends {
    readonly audience: unknown;
    readonly channel: unknown;
    readonly description?: unknown;
    readonly key: string;
    readonly variables?: unknown;
  },
>(template: T) {
  const definition = DEFAULT_NOTIFICATION_TEMPLATES.find((candidate) => candidate.key === template.key);
  if (!definition) {
    return {
      ...template,
      contractIssues: notificationTemplateIssuesForKey(template),
      openBehavior: notificationTemplateOpenBehavior(template.key),
      requiredVariables: [],
      runtimeRoutes: [],
    };
  }
  return {
    ...template,
    audience: definition.audience,
    channel: definition.channel,
    contractIssues: notificationTemplateIssuesForKey(template),
    description: definition.description,
    openBehavior: notificationTemplateOpenBehavior(template.key),
    requiredVariables: [...definition.requiredVariables],
    runtimeRoutes: NOTIFICATION_TEMPLATE_ROUTES.filter((route) => route.templateKey === template.key).map(
      (route) => ({ targetRole: route.targetRole, type: route.type }),
    ),
    variables: [...definition.variables],
  };
}

function notificationTemplateIssuesForKey(template: {
  readonly audience: unknown;
  readonly channel: unknown;
  readonly key: string;
  readonly variables?: unknown;
}) {
  const routeIds = NOTIFICATION_TEMPLATE_ROUTES.filter((route) => route.templateKey === template.key).map(
    (route) => `${route.type}:${route.targetRole}`,
  );
  return [
    ...notificationTemplateMetadataIssues(template),
    ...notificationTemplateContractErrors().filter(
      (issue) => issue.includes(template.key) || routeIds.some((routeId) => issue.includes(routeId)),
    ),
  ];
}

function notificationTemplateMetadataIssues(template: {
  readonly audience: unknown;
  readonly channel: unknown;
  readonly key: string;
  readonly variables?: unknown;
}) {
  const definition = DEFAULT_NOTIFICATION_TEMPLATES.find((candidate) => candidate.key === template.key);
  if (!definition) return [`${template.key}: unexpected database template`];
  const issues: string[] = [];
  if (template.audience !== definition.audience) {
    issues.push(
      `${template.key}: audience mismatch (database ${String(template.audience)}, catalog ${definition.audience})`,
    );
  }
  if (template.channel !== definition.channel) {
    issues.push(
      `${template.key}: channel mismatch (database ${String(template.channel)}, catalog ${definition.channel})`,
    );
  }
  const databaseVariables = stringArray(template.variables);
  if (!sameStringSet(databaseVariables, definition.variables)) {
    issues.push(
      `${template.key}: variables mismatch (database ${formatContractList(databaseVariables)}, catalog ${formatContractList(definition.variables)})`,
    );
  }
  return issues;
}

function notificationCopyEquals(
  left: { readonly body: string; readonly title: string },
  right: { readonly body: string; readonly title: string },
) {
  return (
    normalizeNotificationCopy(left.title) === normalizeNotificationCopy(right.title) &&
    normalizeNotificationCopy(left.body) === normalizeNotificationCopy(right.body)
  );
}

function normalizeNotificationCopy(value: string) {
  return value.replace(/\r\n?/g, '\n').trim();
}

function stringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string') : [];
}

function sameStringSet(left: readonly string[], right: readonly string[]) {
  return [...new Set(left)].sort().join('\u0000') === [...new Set(right)].sort().join('\u0000');
}

function formatContractList(value: readonly string[]) {
  return value.length > 0 ? value.join(', ') : 'none';
}

function validateNotificationTemplatePlaceholders(
  definition: (typeof DEFAULT_NOTIFICATION_TEMPLATES)[number],
  translation: { readonly body: string; readonly locale: string; readonly title: string },
) {
  const allowed = new Set<string>(definition.variables);
  const required = new Set<string>(definition.requiredVariables);
  const actual = notificationTemplatePlaceholders(`${translation.title} ${translation.body}`);
  const unknown = [...actual].filter((placeholder) => !allowed.has(placeholder));
  const missing = [...required].filter((placeholder) => !actual.has(placeholder));

  if (unknown.length > 0) {
    throw new BadRequestException(
      `Unknown notification placeholder(s) for ${translation.locale}: ${unknown.join(', ')}`,
    );
  }
  if (missing.length > 0) {
    throw new BadRequestException(
      `Required notification placeholder(s) missing for ${translation.locale}: ${missing.join(', ')}`,
    );
  }
}

function notificationTemplatePlaceholders(value: string) {
  return new Set(Array.from(value.matchAll(/\{([^{}]+)\}/g), (match) => match[1].trim()));
}

function normalizeAdminPushTargetRole(value: Role) {
  if (value === Role.CUSTOMER || value === Role.PROVIDER) {
    return value;
  }
  throw new BadRequestException('Manual push target role must be CUSTOMER or PROVIDER');
}

function normalizeAdminPushTargetSegment(targetRole: Extract<Role, 'CUSTOMER' | 'PROVIDER'>, value?: string) {
  const segment = normalizeNullable(value) ?? ADMIN_PUSH_SEGMENT_ALL;
  const allowedSegments =
    targetRole === Role.PROVIDER ? ADMIN_PUSH_PROVIDER_SEGMENTS : ADMIN_PUSH_CUSTOMER_SEGMENTS;
  if (allowedSegments.has(segment)) {
    return segment;
  }
  throw new BadRequestException(`Unsupported manual push target segment for ${targetRole}`);
}

function normalizeAdminPushLocale(targetRole: Extract<Role, 'CUSTOMER' | 'PROVIDER'>, value?: string) {
  const locale = normalizeNullable(value)?.toLowerCase();
  if (!locale || !['en', 'vi', 'ko', 'ja', 'zh'].includes(locale)) {
    throw new BadRequestException('Manual push language is required');
  }
  if (targetRole === Role.PROVIDER && locale !== 'vi') {
    throw new BadRequestException('Partner manual push campaigns support Vietnamese only');
  }
  return locale;
}

function adminPushRecipientBaseWhere(
  targetRole: Extract<Role, 'CUSTOMER' | 'PROVIDER'>,
  targetUserId?: string,
  targetSegment = ADMIN_PUSH_SEGMENT_ALL,
  now = new Date(),
): Prisma.UserWhereInput {
  const normalizedTargetUserId = normalizeNullable(targetUserId);
  const baseWhere: Prisma.UserWhereInput = {
    ...(normalizedTargetUserId ? { id: normalizedTargetUserId } : {}),
    roles: { has: targetRole },
    ...(targetRole === Role.CUSTOMER
      ? { customerProfile: { isNot: null } }
      : { providerProfile: { is: { blockedAt: null, deletedAt: null } } }),
  };
  const segmentWhere = adminPushSegmentWhere(targetRole, targetSegment, now);
  return Object.keys(segmentWhere).length ? { AND: [baseWhere, segmentWhere] } : baseWhere;
}

function adminPushPreviewState(eligibleUsers: number, eligibleDevices: number) {
  if (eligibleUsers === 0 || eligibleDevices === 0) {
    return 'ZERO_RECIPIENTS' as const;
  }
  if (eligibleUsers > ADMIN_PUSH_CAMPAIGN_RECIPIENT_LIMIT) {
    return 'OVER_LIMIT' as const;
  }
  return 'READY' as const;
}

function adminPushHash(value: unknown) {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

function adminPushCampaignWithoutActorId<T extends { readonly createdById: string }>(campaign: T) {
  const { createdById, ...operatorCampaign } = campaign;
  void createdById;
  return operatorCampaign;
}

function adminPushSegmentWhere(
  targetRole: Extract<Role, 'CUSTOMER' | 'PROVIDER'>,
  targetSegment: string,
  now: Date,
): Prisma.UserWhereInput {
  if (targetSegment === ADMIN_PUSH_SEGMENT_ALL) {
    return {};
  }

  if (targetRole === Role.CUSTOMER) {
    return adminPushCustomerSegmentWhere(targetSegment, now);
  }
  return adminPushProviderSegmentWhere(targetSegment, now);
}

function adminPushCustomerSegmentWhere(targetSegment: string, now: Date): Prisma.UserWhereInput {
  const since7Days = new Date(now.getTime() - ADMIN_PUSH_SEGMENT_WINDOWS.customerCompletedRecentMs);
  const since30Days = new Date(now.getTime() - ADMIN_PUSH_SEGMENT_WINDOWS.customerInactiveMs);
  const since3Days = new Date(now.getTime() - ADMIN_PUSH_SEGMENT_WINDOWS.customerActiveNoBookingMs);

  if (targetSegment === 'customer_completed_last_7_days') {
    return {
      customerProfile: {
        is: {
          bookings: { some: completedBookingWhere(since7Days) },
        },
      },
    };
  }

  if (targetSegment === 'customer_completed_inactive_30_days') {
    return {
      customerProfile: {
        is: {
          bookings: { some: completedBookingWhere() },
        },
      },
      appSessions: {
        none: {
          role: Role.CUSTOMER,
          lastSeenAt: { gte: since30Days },
        },
      },
    };
  }

  if (targetSegment === 'customer_never_booked') {
    return {
      customerProfile: {
        is: {
          bookings: { none: {} },
        },
      },
    };
  }

  if (targetSegment === 'customer_active_last_3_days_no_booking') {
    return {
      customerProfile: {
        is: {
          bookings: { none: {} },
        },
      },
      appSessions: {
        some: {
          role: Role.CUSTOMER,
          lastSeenAt: { gte: since3Days },
        },
      },
    };
  }

  if (targetSegment === 'customer_referral_parents') {
    return {
      customerProfile: {
        is: {
          referralsMade: { some: { audience: ReferralAudience.CUSTOMER } },
        },
      },
    };
  }

  throw new BadRequestException('Unsupported customer push segment');
}

function adminPushProviderSegmentWhere(targetSegment: string, now: Date): Prisma.UserWhereInput {
  const since7Days = new Date(now.getTime() - ADMIN_PUSH_SEGMENT_WINDOWS.providerInactiveMs);

  if (targetSegment === 'provider_completed_booking') {
    return {
      providerProfile: {
        is: {
          selectedBookings: { some: completedBookingWhere() },
        },
      },
    };
  }

  if (targetSegment === 'provider_referral_parents') {
    return {
      providerProfile: {
        is: {
          referralsMade: { some: { audience: ReferralAudience.PARTNER } },
        },
      },
    };
  }

  if (targetSegment === 'provider_inactive_last_7_days') {
    return {
      appSessions: {
        none: {
          role: Role.PROVIDER,
          lastSeenAt: { gte: since7Days },
        },
      },
    };
  }

  throw new BadRequestException('Unsupported partner push segment');
}

function completedBookingWhere(since?: Date): Prisma.BookingWhereInput {
  if (!since) {
    return { status: BookingStatus.COMPLETED };
  }
  return {
    status: BookingStatus.COMPLETED,
    OR: [
      { closedAt: { gte: since } },
      {
        closedAt: null,
        updatedAt: { gte: since },
      },
    ],
  };
}

async function ensureServiceDurationIsUnique(
  tx: Prisma.TransactionClient,
  input: { serviceGroupKey: string; durationMin: number; excludeServiceId?: string },
) {
  const existing = await tx.massageService.findFirst({
    where: {
      serviceGroupKey: input.serviceGroupKey,
      durationMin: input.durationMin,
      ...(input.excludeServiceId ? { id: { not: input.excludeServiceId } } : {}),
    },
    select: { id: true, name: true, durationMin: true },
  });

  if (existing) {
    throw new BadRequestException(
      `Service duration already exists for ${input.serviceGroupKey}: ${existing.durationMin} min`,
    );
  }
}
